(1, 'school', 1, NULL, 'snapshot', 'Initial content', '{"attributes":{"name":"School of Manufacturing Technologies","slug":"school-of-manufacturing-technologies","tagline":null,"summary":"The School of Manufacturing Technologies is focused on advancing the capabilities required for the next era of manufacturing. By bringing together engineering expertise, emerging technologies, industry collaboration, and experiential learning, the School prepares learners to create value across the evolving manufacturing ecosystem and contribute to India\u2019s ambition to become a globally competitive manufacturing powerhouse.","body":null,"image_id":7,"sort_order":0,"hidden_blocks":null,"meta_title":null,"meta_description":null,"og_image_id":null,"canonical_url":null,"noindex":false},"relations":{"sections":[]}}', '2026-11-18 06:43:36', '2026-11-18 06:43:36'),
(2, 'school', 2, NULL, 'snapshot', 'Initial content', '{"attributes":{"name":"School of Manufacturing Design & AI","slug":"school-of-manufacturing-design-ai","tagline":null,"summary":"The School of Manufacturing Design & AI focuses on the convergence of design, engineering, computation, and artificial intelligence to shape the next generation of products, systems, and industrial innovation. Through an industry-first and experiential approach, the school prepares learners to work at the intersection of technology and human needs, translating emerging capabilities into solutions with real-world impact.","body":null,"image_id":3,"sort_order":1,"hidden_blocks":null,"meta_title":null,"meta_description":null,"og_image_id":null,"canonical_url":null,"noindex":false},"relations":{"sections":[]}}', '2026-11-18 06:43:36', '2026-11-18 06:43:36'),
(3, 'school', 3, NULL, 'snapshot', 'Initial content', '{"attributes":{"name":"School of Robotics","slug":"school-of-robotics","tagline":null,"summary":"The School of Robotics prepares the next generation of professionals to design, develop, and deploy intelligent machines and autonomous systems that will transform industry and society. By combining engineering, emerging technologies, hands-on experimentation, and real-world application, the school equips learners to build the future of human\u2013machine collaboration and intelligent automation.","body":null,"image_id":10,"sort_order":2,"hidden_blocks":null,"meta_title":null,"meta_description":null,"og_image_id":null,"canonical_url":null,"noindex":false},"relations":{"sections":[]}}', '2026-11-18 06:43:36', '2026-11-18 06:43:36'),
(4, 'school', 4, NULL, 'snapshot', 'Initial content', '{"attributes":{"name":"School of Sustainability","slug":"school-of-sustainability","tagline":null,"summary":"The School of Sustainability focuses on enabling the transition towards more resilient, resource-efficient, and sustainable industries. By bringing together technology, engineering, innovation, and systems thinking, the School prepares learners to address complex environmental and industrial challenges and create solutions that balance economic growth, resource security, and long-term sustainability.","body":null,"image_id":11,"sort_order":3,"hidden_blocks":null,"meta_title":null,"meta_description":null,"og_image_id":null,"canonical_url":null,"noindex":false},"relations":{"sections":[]}}', '2026-11-18 06:43:36', '2026-11-18 06:43:36'),
(5, 'school', 5, NULL, 'snapshot', 'Initial content', '{"attributes":{"name":"School of Technical Education","slug":"school-of-technical-education","tagline":null,"summary":"The School of Technical Education enables ITI and diploma-qualified learners to build on their technical foundations and progress into higher levels of technological capability. Through practical, industry-oriented learning and curriculum designed in collaboration with ITE Education Services, Singapore, the School creates pathways for skilled technicians to evolve into confident, industry-ready technologists capable of contributing to the future of modern industry.","body":null,"image_id":21,"sort_order":4,"hidden_blocks":null,"meta_title":null,"meta_description":null,"og_image_id":null,"canonical_url":null,"noindex":false},"relations":{"sections":[]}}', '2026-11-18 06:43:36', '2026-11-18 06:43:36'),
(6, 'centre', 1, NULL, 'snapshot', 'Initial content', '{"attributes":{"school_id":null,"name":"Center of Excellence in Automotive Engineering","slug":"coe-in-automotive-engineering","tagline":null,"summary":"The Center of Excellence in Automotive Engineering advances the future of mobility by bringing together engineering, technology, design, and industry expertise. The Center enables learners and industry to explore emerging opportunities, address real-world mobility challenges, and develop solutions that contribute to a more intelligent, connected, and sustainable automotive ecosystem.","body":null,"image_id":2,"sort_order":0,"hidden_blocks":null,"meta_title":null,"meta_description":null,"og_image_id":null,"canonical_url":null,"noindex":false},"relations":{"sections":[]}}', '2026-11-18 06:43:36', '2026-11-18 06:43:36'),
(7, 'centre', 2, NULL, 'snapshot', 'Initial content', '{"attributes":{"school_id":null,"name":"Center of Advanced Computing & AI","slug":"centre-of-advanced-computing-ai","tagline":null,"summary":"The Center for Advanced Computing & AI focuses on harnessing computing and artificial intelligence to address complex challenges across industry and society. By connecting advanced technology with real-world application, the Center enables learners, researchers, and industry to develop intelligent solutions and unlock new possibilities for technology-led transformation.","body":null,"image_id":21,"sort_order":1,"hidden_blocks":null,"meta_title":null,"meta_description":null,"og_image_id":null,"canonical_url":null,"noindex":false},"relations":{"sections":[]}}', '2026-11-18 06:43:37', '2026-11-18 06:43:37'),
(8, 'centre', 3, NULL, 'snapshot', 'Initial content', '{"attributes":{"school_id":null,"name":"Center of Management Studies","slug":"center-of-management","tagline":null,"summary":"The Center of Management Studies helps NAMTECH graduates develop the strategic, business, and managerial capabilities required to navigate an increasingly technology-driven economy. By bringing together design thinking, strategic intelligence, and business & professional communication, the Center prepares professionals to bridge technology and enterprise, drive transformation, and drive organizational value.","body":null,"image_id":22,"sort_order":2,"hidden_blocks":null,"meta_title":null,"meta_description":null,"og_image_id":null,"canonical_url":null,"noindex":false},"relations":{"sections":[]}}', '2026-11-18 06:43:37', '2026-11-18 06:43:37'),
(9, 'centre', 4, NULL, 'snapshot', 'Initial content', '{"attributes":{"school_id":null,"name":"Experiential Learning Center for Sustainable Energy & Circularity","slug":"experiential-learning-center-for-sustainable-energy-circularity","tagline":null,"summary":"Co-created with IIT Roorkee and supported by NTPC, The Experiential Learning Center for Sustainable Energy & Circularity (ELC:SEC) focuses on enabling the transition towards more sustainable, resource-efficient, and resilient industrial systems. The Center addresses the interconnected challenges of energy, resources, and industrial growth through convergence of technology, innovation, and systems thinking, for a low-carbon and circular future.","body":null,"image_id":20,"sort_order":3,"hidden_blocks":null,"meta_title":null,"meta_description":null,"og_image_id":null,"canonical_url":null,"noindex":false},"relations":{"sections":[]}}', '2026-11-18 06:43:37', '2026-11-18 06:43:37'),
(10, 'program', 1, NULL, 'snapshot', 'Initial content', '{"attributes":{"school_id":1,"title":"B.Tech. Mechanical Engineering (Smart Manufacturing)","slug":"btech-mechanical-engineering-smart-manufacturing","level":"undergraduate","award":"B.Tech","summary":"A forward-looking undergraduate degree integrating core mechanical engineering with cyber-physical systems, additive manufacturing, industrial IoT, and digital twin simulation to engineer next-generation smart factories.","body":null,"mode":"On-Campus","location":"Ahmedabad","intake":"August, 2026","application_deadline":"2026-07-30 00:00:00","duration":"4 years","duration_detail":"8 Semesters","apply_url":"\/admissions#enquire","image_id":7,"is_featured":true,"sort_order":0,"hidden_blocks":null,"details":null,"meta_title":null,"meta_description":null,"og_image_id":null,"canonical_url":null,"noindex":false},"relations":{"sections":[]}}', '2026-11-18 06:43:37', '2026-11-18 06:43:37'),
(11, 'program', 2, NULL, 'snapshot', 'Initial content', '{"attributes":{"school_id":1,"title":"B.Tech. Mechanical Engineering (Automotive)","slug":"btech-mechanical-engineering-automotive","level":"undergraduate","award":"B.Tech","summary":"Focuses on modern vehicle architecture, powertrain electrification, autonomous driving dynamics, and advanced materials engineering designed in collaboration with leading automotive OEMs.","body":null,"mode":"On-Campus","location":"Ahmedabad","intake":"August, 2026","application_deadline":"2026-07-30 00:00:00","duration":"4 years","duration_detail":"8 Semesters","apply_url":"\/admissions#enquire","image_id":3,"is_featured":true,"sort_order":1,"hidden_blocks":null,"details":null,"meta_title":null,"meta_description":null,"og_image_id":null,"canonical_url":null,"noindex":false},"relations":{"sections":[]}}', '2026-11-18 06:43:37', '2026-11-18 06:43:37'),
(12, 'program', 3, NULL, 'snapshot', 'Initial content', '{"attributes":{"school_id":3,"title":"B.Tech. Robotics & AI","slug":"btech-robotics-and-ai","level":"undergraduate","award":"B.Tech","summary":"Brings together mechanical kinematics, sensor fusion, computer vision, and machine learning to build autonomous robotic systems, collaborative cobots, and intelligent automation platforms.","body":null,"mode":"On-Campus","location":"Ahmedabad","intake":"August, 2026","application_deadline":"2026-07-30 00:00:00","duration":"4 years","duration_detail":"8 Semesters","apply_url":"\/admissions#enquire","image_id":11,"is_featured":true,"sort_order":2,"hidden_blocks":null,"details":null,"meta_title":null,"meta_description":null,"og_image_id":null,"canonical_url":null,"noindex":false},"relations":{"sections":[]}}', '2026-11-18 06:43:37', '2026-11-18 06:43:37'),
(13, 'program', 4, NULL, 'snapshot', 'Initial content', '{"attributes":{"school_id":4,"title":"B.Tech. Smart & Sustainable Energy","slug":"btech-smart-and-sustainable-energy","level":"undergraduate","award":"B.Tech","summary":"Prepares engineers to pioneer clean energy transitions, renewable grid integration, hydrogen storage systems, and circular manufacturing frameworks to achieve net-zero industrial targets.","body":null,"mode":"On-Campus","location":"Ahmedabad","intake":"August, 2026","application_deadline":"2026-07-30 00:00:00","duration":"4 years","duration_detail":"8 Semesters","apply_url":"\/admissions#enquire","image_id":2,"is_featured":true,"sort_order":3,"hidden_blocks":null,"details":null,"meta_title":null,"meta_description":null,"og_image_id":null,"canonical_url":null,"noindex":false},"relations":{"sections":[]}}', '2026-11-18 06:43:37', '2026-11-18 06:43:37'),
(14, 'program', 5, NULL, 'snapshot', 'Initial content', '{"attributes":{"school_id":2,"title":"B.Tech. Computer Science Engineering","slug":"btech-computer-science-engineering","level":"undergraduate","award":"B.Tech","summary":"Focuses on high-performance computing, distributed cloud architectures, industrial cybersecurity, and data-driven systems powering mission-critical manufacturing and enterprise environments.","body":null,"mode":"On-Campus","location":"Ahmedabad","intake":"August, 2026","application_deadline":"2026-07-30 00:00:00","duration":"4 years","duration_detail":"8 Semesters","apply_url":"\/admissions#enquire","image_id":21,"is_featured":true,"sort_order":4,"hidden_blocks":null,"details":null,"meta_title":null,"meta_description":null,"og_image_id":null,"canonical_url":null,"noindex":false},"relations":{"sections":[]}}', '2026-11-18 06:43:37', '2026-11-18 06:43:37'),
(15, 'program', 6, NULL, 'snapshot', 'Initial content', '{"attributes":{"school_id":1,"title":"B.Tech. Electronics Engineering (Semiconductor Technology)","slug":"btech-electronics-engineering-semiconductor-technology","level":"undergraduate","award":"B.Tech","summary":"Equips engineers with expertise in VLSI design, semiconductor fabrication processes, cleanroom operations, and microelectronics packaging aligned with India\u2019s national semiconductor mission.","body":null,"mode":"On-Campus","location":"Ahmedabad","intake":"August, 2026","application_deadline":"2026-07-30 00:00:00","duration":"4 years","duration_detail":"8 Semesters","apply_url":"\/admissions#enquire","image_id":20,"is_featured":true,"sort_order":5,"hidden_blocks":null,"details":null,"meta_title":null,"meta_description":null,"og_image_id":null,"canonical_url":null,"noindex":false},"relations":{"sections":[]}}', '2026-11-18 06:43:37', '2026-11-18 06:43:37'),
