(17, 'program', 8, NULL, 'snapshot', 'Initial content', '{"attributes":{"school_id":1,"title":"Master in Smart Manufacturing Technology & Management","slug":"master-in-smart-manufacturing-technology-and-management","level":"postgraduate","award":"Master","summary":"Develop advanced expertise in smart manufacturing, Industry 4.0 and 5.0, intelligent automation, digital production systems, and technology management to lead the transformation of modern manufacturing enterprises.","body":null,"mode":"On-Campus","location":"Ahmedabad","intake":"August, 2026","application_deadline":"2026-07-30 00:00:00","duration":"2 years","duration_detail":"4 Semesters","apply_url":"\/admissions#enquire","image_id":3,"is_featured":true,"sort_order":7,"hidden_blocks":null,"details":null,"meta_title":null,"meta_description":null,"og_image_id":null,"canonical_url":null,"noindex":false},"relations":{"sections":[]}}', '2026-11-18 06:43:37', '2026-11-18 06:43:37'),
(18, 'program', 9, NULL, 'snapshot', 'Initial content', '{"attributes":{"school_id":1,"title":"Master in Heavy Industry Engineering & Management","slug":"master-in-heavy-industry-engineering-and-management","level":"postgraduate","award":"Master","summary":"Developed in collaboration with the ArcelorMittal Design and Engineering Center (AMDEC), this program prepares engineers for heavy industries like steel manufacturing, mining and mineral processing, ports, and capital infrastructure. It combines a rigorous engineering foundation with three specialization tracks and an extended paid industry residency at AMDEC.","body":null,"mode":"On-Campus","location":"Ahmedabad","intake":"August, 2026","application_deadline":"2026-07-30 00:00:00","duration":"2 years","duration_detail":"4 Semesters","apply_url":"\/admissions#enquire","image_id":11,"is_featured":true,"sort_order":8,"hidden_blocks":null,"details":null,"meta_title":null,"meta_description":null,"og_image_id":null,"canonical_url":null,"noindex":false},"relations":{"sections":[]}}', '2026-11-18 06:43:37', '2026-11-18 06:43:37'),
