(25, 'program', 16, NULL, 'snapshot', 'Initial content', '{"attributes":{"school_id":5,"title":"iPTP Automation","slug":"iptp-automation","level":"technical","award":"iPTP","summary":"Build upon your ITI or diploma foundation with advanced expertise in industrial automation, control systems, instrumentation, and connected production technologies to configure, integrate, and optimize automated manufacturing systems.","body":null,"mode":null,"location":null,"intake":null,"application_deadline":null,"duration":null,"duration_detail":null,"apply_url":"\/admissions#enquire","image_id":2,"is_featured":true,"sort_order":15,"hidden_blocks":null,"details":null,"meta_title":null,"meta_description":null,"og_image_id":null,"canonical_url":null,"noindex":false},"relations":{"sections":[]}}', '2026-11-18 06:43:38', '2026-11-18 06:43:38'),
(26, 'program', 17, NULL, 'snapshot', 'Initial content', '{"attributes":{"school_id":5,"title":"iPTP Semiconductor Manufacturing","slug":"iptp-semiconductor-manufacturing","level":"technical","award":"iPTP","summary":"Gain specialized expertise in semiconductor manufacturing, precision processes, cleanroom practices, and advanced production technologies to build the capabilities needed for India\u2019s growing semiconductor ecosystem.","body":null,"mode":null,"location":null,"intake":null,"application_deadline":null,"duration":null,"duration_detail":null,"apply_url":"\/admissions#enquire","image_id":21,"is_featured":true,"sort_order":16,"hidden_blocks":null,"details":null,"meta_title":null,"meta_description":null,"og_image_id":null,"canonical_url":null,"noindex":false},"relations":{"sections":[]}}', '2026-11-18 06:43:38', '2026-11-18 06:43:38'),
(27, 'program', 18, NULL, 'snapshot', 'Initial content', '{"attributes":{"school_id":5,"title":"iPTP Industrial Robotics","slug":"iptp-industrial-robotics","level":"technical","award":"iPTP","summary":"Strengthen your ITI or diploma foundation with specialized expertise in industrial robotics, robotic programming, machine vision, and robot\u2013machine integration to evolve from a skilled technician into an industry-ready technologist.","body":null,"mode":null,"location":null,"intake":null,"application_deadline":null,"duration":null,"duration_detail":null,"apply_url":"\/admissions#enquire","image_id":20,"is_featured":true,"sort_order":17,"hidden_blocks":null,"details":null,"meta_title":null,"meta_description":null,"og_image_id":null,"canonical_url":null,"noindex":false},"relations":{"sections":[]}}', '2026-11-18 06:43:38', '2026-11-18 06:43:38'),
(28, 'partner', 1, NULL, 'snapshot', 'Initial content', '{"attributes":{"partnership_category_id":1,"name":"Massachusetts Institute of Technology","slug":"mit","summary":"In collaboration with MIT\u2019s Department of Mechanical Engineering, NAMTECH brings the renowned MIT 2.008 Manufacturing course to India \u2014 combining core manufacturing principles with hands-on application, from product design and process planning to production systems and optimization.","story":"<p>In collaboration with MIT\u2019s Department of Mechanical Engineering, NAMTECH brings the renowned MIT 2.008 Manufacturing course to India \u2014 combining core manufacturing principles with hands-on application, from product design and process planning to production systems and optimization.<\/p><p>Through this strategic alliance, NAMTECH and our partner collaborate on curriculum co-development, industry-grade experiential learning facilities, faculty training, and direct recruitment pipelines to accelerate India\u2019s manufacturing competitiveness.<\/p>","highlight":null,"website_url":null,"logo_id":null,"image_id":31,"is_featured":true,"sort_order":0,"meta_title":null,"meta_description":null,"og_image_id":null,"canonical_url":null,"noindex":false},"relations":[]}', '2026-11-18 06:43:38', '2026-11-18 06:43:38'),
(29, 'partner', 2, NULL, 'snapshot', 'Initial content', '{"attributes":{"partnership_category_id":1,"name":"Carnegie Mellon University","slug":"carnegie-mellon-university","summary":"Through its collaboration with Carnegie Mellon University, NAMTECH leverages CMU\u2019s expertise in learning science, digital education, and technology-enabled learning to develop and share advanced learning resources and methodologies with ITIs, strengthening the quality and reach of technical education. The collaboration also supports faculty training and learning science research.","story":"<p>Through its collaboration with Carnegie Mellon University, NAMTECH leverages CMU\u2019s expertise in learning science, digital education, and technology-enabled learning to develop and share advanced learning resources and methodologies with ITIs, strengthening the quality and reach of technical education. The collaboration also supports faculty training and learning science research.<\/p><p>Through this strategic alliance, NAMTECH and our partner collaborate on curriculum co-development, industry-grade experiential learning facilities, faculty training, and direct recruitment pipelines to accelerate India\u2019s manufacturing competitiveness.<\/p>","highlight":null,"website_url":null,"logo_id":null,"image_id":32,"is_featured":true,"sort_order":1,"meta_title":null,"meta_description":null,"og_image_id":null,"canonical_url":null,"noindex":false},"relations":[]}', '2026-11-18 06:43:38', '2026-11-18 06:43:38'),
(30, 'partner', 3, NULL, 'snapshot', 'Initial content', '{"attributes":{"partnership_category_id":1,"name":"Indian Institute of Technology (IIT), Roorkee","slug":"iit-roorkee","summary":"Together with IIT Roorkee, and supported by National Thermal Power Corporation (NTPC), NAMTECH has established the Experiential Learning Center for Sustainable Energy & Circularity (ELC:SEC) to advance applied research, industry-focused learning, and technology-led solutions for a more energy-efficient and resource-resilient industrial future.","story":"<p>Together with IIT Roorkee, and supported by National Thermal Power Corporation (NTPC), NAMTECH has established the Experiential Learning Center for Sustainable Energy &amp; Circularity (ELC:SEC) to advance applied research, industry-focused learning, and technology-led solutions for a more energy-efficient and resource-resilient industrial future.<\/p><p>Through this strategic alliance, NAMTECH and our partner collaborate on curriculum co-development, industry-grade experiential learning facilities, faculty training, and direct recruitment pipelines to accelerate India\u2019s manufacturing competitiveness.<\/p>","highlight":null,"website_url":null,"logo_id":null,"image_id":33,"is_featured":true,"sort_order":2,"meta_title":null,"meta_description":null,"og_image_id":null,"canonical_url":null,"noindex":false},"relations":[]}', '2026-11-18 06:43:38', '2026-11-18 06:43:38'),
(31, 'partner', 4, NULL, 'snapshot', 'Initial content', '{"attributes":{"partnership_category_id":2,"name":"AM\/NS India","slug":"amns-india","summary":null,"story":"<p>NAMTECH has partnered with AMNS India, a leading integrated steel manufacturer and a joint venture between ArcelorMittal and Nippon Steel. This collaboration focuses on advancing skill development, industry-aligned education, and research in manufacturing and materials technologies.<\/p><p>Through joint initiatives in curriculum design, experiential learning, and applied research, NAMTECH and AMNS India aim to bridge the gap between academia and industry, nurturing a new generation of engineers equipped with cutting-edge technical and managerial capabilities.<\/p><p>AMNS India\u2019s leadership in sustainable steelmaking and advanced manufacturing complements NAMTECH\u2019s vision of shaping future-ready talent for India\u2019s manufacturing and engineering sectors. Together, this partnership enables real-world exposure, access to industry infrastructure, and career opportunities that empower students to contribute to India\u2019s industrial transformation and global competitiveness.<\/p>","highlight":null,"website_url":null,"logo_id":23,"image_id":null,"is_featured":false,"sort_order":3,"meta_title":null,"meta_description":null,"og_image_id":null,"canonical_url":null,"noindex":false},"relations":[]}', '2026-11-18 06:43:38', '2026-11-18 06:43:38'),
(32, 'partner', 5, NULL, 'snapshot', 'Initial content', '{"attributes":{"partnership_category_id":1,"name":"TUM Asia","slug":"tum-asia","summary":null,"story":null,"highlight":null,"website_url":null,"logo_id":24,"image_id":null,"is_featured":false,"sort_order":4,"meta_title":null,"meta_description":null,"og_image_id":null,"canonical_url":null,"noindex":false},"relations":[]}', '2026-11-18 06:43:38', '2026-11-18 06:43:38'),
(33, 'partner', 6, NULL, 'snapshot', 'Initial content', '{"attributes":{"partnership_category_id":2,"name":"Siemens","slug":"siemens","summary":"NAMTECH\u2019s strategic partnership with Siemens strengthens learning in smart manufacturing, automation, and technical education. The collaboration focuses on experiential learning, hands-on training, co-developed curricula, and advanced learning infrastructure to prepare learners for Industry 4.0.","story":"<p>NAMTECH has forged a strategic partnership with Siemens to revolutionize education in smart manufacturing, automation, and advanced technical education. This collaboration aims to integrate cutting-edge industry expertise into NAMTECH\u2019s academic framework, introducing new electives and dedicated courses within the Master\u2019s, Executive and iPTP programmes.<\/p><p>The partnership emphasizes experiential learning, hands-on industry training, and the co-development of dynamic course curricula. A key highlight is the establishment of a robust industry attachment programme for both faculty and students, fostering deeper industry-academic integration.<\/p><p>Additionally, NAMTECH and Siemens will collaborate on developing state-of-the-art infrastructure, creating continuous knowledge-sharing platforms, and designing advanced learning modules to prepare learners for the challenges of Industry 4.0 and beyond.<\/p><p>Through this partnership, NAMTECH and Siemens are shaping a future-ready workforce equipped with the skills and expertise to drive innovation in manufacturing and automation.<\/p>","highlight":null,"website_url":null,"logo_id":29,"image_id":8,"is_featured":true,"sort_order":5,"meta_title":null,"meta_description":null,"og_image_id":null,"canonical_url":null,"noindex":false},"relations":[]}', '2026-11-18 06:43:38', '2026-11-18 06:43:38'),
(34, 'partner', 7, NULL, 'snapshot', 'Initial content', '{"attributes":{"partnership_category_id":2,"name":"Cisco","slug":"cisco","summary":null,"story":"<p>NAMTECH has partnered with Cisco, a global leader in networking and technology solutions. This partnership brings together expertise in manufacturing technologies and digital innovation to enhance our academic programmes and industry relevance.<\/p><p>This strategic collaboration reflects NAMTECH\u2019S commitment to delivering industry-relevant education and empowering students to excel in the dynamic fields of Cybersecurity and Networking in the field of manufacturing.<\/p><p>The partnership with industry leaders like CISCO to co-design curriculum, co-invest in learning infrastructure, and participate in recruitment drives helps is highly beneficial for our young professionals. Moreover, by working closely with partners, NAMTECH ensures that its curriculum is aligned with industry needs, providing students with hands-on experience, cutting-edge infrastructure, and pathways to meaningful careers.<\/p>","highlight":null,"website_url":null,"logo_id":26,"image_id":null,"is_featured":false,"sort_order":6,"meta_title":null,"meta_description":null,"og_image_id":null,"canonical_url":null,"noindex":false},"relations":[]}', '2026-11-18 06:43:38', '2026-11-18 06:43:38'),
(35, 'partner', 8, NULL, 'snapshot', 'Initial content', '{"attributes":{"partnership_category_id":2,"name":"Micron","slug":"micron","summary":null,"story":"<p>NAMTECH has partnered with Micron, a global leader in semiconductor solutions. This collaboration spans across academic development, infrastructure setup, student training, and recruitment initiatives.<\/p><p>Micron is leading the semiconductor manufacturing foray in India and establishing a state-of-the-art facility in Sanand, which lies in close proximity to our campus. By working closely with industry leaders, NAMTECH ensures that its programmes are aligned with industry demands, providing students with hands-on experience, cutting-edge infrastructure, and opportunities for career advancement.<\/p><p>This holistic approach to the partnership enhances the educational experience and prepares students for successful careers. This synergistic partnership is in line with the steadily growing ecosystem in India and South-East Asia and students stand to benefit from faculty with industry expertise and the skills exposure, as well as employment opportunities in India and abroad.<\/p>","highlight":null,"website_url":null,"logo_id":27,"image_id":null,"is_featured":false,"sort_order":7,"meta_title":null,"meta_description":null,"og_image_id":null,"canonical_url":null,"noindex":false},"relations":[]}', '2026-11-18 06:43:38', '2026-11-18 06:43:38'),
(36, 'partner', 9, NULL, 'snapshot', 'Initial content', '{"attributes":{"partnership_category_id":2,"name":"Festo","slug":"festo","summary":null,"story":"<p>NAMTECH has forged a strategic partnership with Festo, a global leader in automation technology. Festo will design and supply cutting-edge labs at NAMTECH interim campus at Research Park, IIT Gandhinagar, Gujarat, India.<\/p><p>Festo\u2019s role as a strategic partner for lab equipment and curriculum development ensures that our students have access to state-of-the-art facilities and industry-aligned learning experiences. NAMTECH work with the didactic team at Festo with an aim to offer students insights into leading Industry 4.0 technology.<\/p><p>This partnership not only enriches our academic programmes but also empowers students with practical skills and knowledge that are highly relevant in today\u2019s manufacturing landscape. Together, we are shaping the future of manufacturing education, preparing students to excel in their careers and contribute meaningfully to the industry.<\/p>","highlight":null,"website_url":null,"logo_id":28,"image_id":null,"is_featured":false,"sort_order":8,"meta_title":null,"meta_description":null,"og_image_id":null,"canonical_url":null,"noindex":false},"relations":[]}', '2026-11-18 06:43:38', '2026-11-18 06:43:38'),
(37, 'partner', 10, NULL, 'snapshot', 'Initial content', '{"attributes":{"partnership_category_id":2,"name":"ABB","slug":"abb","summary":"In collaboration with ABB, NAMTECH advances robotics education and supports India\u2019s transition towards automation. The collaboration bridges the skills gap through industry-grade equipment, experiential learning, knowledge sharing via ABB\u2019s experts, applied research, and immersive industry exposure, equipping learners with practical expertise in robotics and automation.","story":"<p>NAMTECH and ABB have partnered to create a School of Robotics, setting a benchmark in robotics and automation education in India.<\/p><p>This visionary collaboration bridges the education gap in automation, advancing robotics skills and fostering seamless industry integration.<\/p><p>At the NAMTECH School of Robotics, ABB Robotics will play a pivotal role in designing, supporting, and executing various programmes. The programmes will be hands-on and industry-focused, supported by world-class infrastructure and guided by global industry leaders like ABB. The goal is to cultivate a highly skilled talent pool for the industrial sector, ensuring students are ready to meet the demands of a rapidly evolving technological landscape.<\/p><p>ABB\u2019s robotics experts will drive knowledge-sharing initiatives, spearhead cutting-edge research, and facilitate immersive industry exposure, offering unparalleled opportunities for students to gain practical expertise.<\/p><p>In 2023, India achieved a new milestone with the installation of 8,510 industrial robots, a 59% increase from the previous year. This growth positions India as the seventh-largest global market for annual robot installations and underscores its burgeoning potential in automation. As this trend accelerates through 2024 and 2025, job opportunities in the robotics sector are booming, particularly in roles such as Robotics Engineers, Robot Design Engineers, Application Engineers, and Smart Factory Designers.<\/p><p>With ABB\u2019s partnership, NAMTECH is at the forefront of shaping the future of robotics education and driving India\u2019s automation revolution.<\/p>","highlight":null,"website_url":null,"logo_id":null,"image_id":34,"is_featured":true,"sort_order":9,"meta_title":null,"meta_description":null,"og_image_id":null,"canonical_url":null,"noindex":false},"relations":[]}', '2026-11-18 06:43:38', '2026-11-18 06:43:38'),
(38, 'partner', 11, NULL, 'snapshot', 'Initial content', '{"attributes":{"partnership_category_id":2,"name":"Schneider Electric","slug":"schneider-electric","summary":"Through its partnership with Schneider Electric, NAMTECH advances smart manufacturing education through industry-grade infrastructure, advanced training labs, and experiential learning.","story":"<p>Schneider Electric is a global leader in energy management, automation, and digitization, providing sustainable solutions for industries, infrastructure, data centres, buildings, and homes. The company focuses on electrification, industrial IoT, automation, smart grid technologies, and digital twin platforms to help organizations enhance reliability, safety, efficiency, and environmental performance. Operating in over 100 countries, Schneider Electric has a substantial presence in India, serving as a key global hub with multiple manufacturing sites, robust R&amp;D capabilities, and significant investments in sustainable and digital technologies.<\/p><p>NAMTECH\u2019s partnership with Schneider Electric is both strategic and transformative. This collaboration allows us to develop a world-class smart campus and advanced training labs at our temporary Gandhinagar site and the upcoming Ahmedabad campus. Students gain hands-on experience with state-of-the-art lab infrastructure, industry-relevant learning, and direct apprenticeships with experts. Beyond infrastructure, we integrate Schneider\u2019s expertise into our curriculum, particularly for the International Professional Master\u2019s Programme in Smart Manufacturing, ensuring our graduates are prepared for Industry 4.0.<\/p><p>This partnership offers NAMTECH students employment opportunities in India and internationally, while faculty members benefit from exposure to global best practices. The collaboration supports India\u2019s goals to modernize manufacturing, enhance competitiveness, and bridge the gap between industry and academia. As a result, our graduates are technically skilled, innovative, and prepared to lead in the digital industrial era.<\/p>","highlight":null,"website_url":null,"logo_id":25,"image_id":35,"is_featured":true,"sort_order":10,"meta_title":null,"meta_description":null,"og_image_id":null,"canonical_url":null,"noindex":false},"relations":[]}', '2026-11-18 06:43:38', '2026-11-18 06:43:38'),
(39, 'partner', 12, NULL, 'snapshot', 'Initial content', '{"attributes":{"partnership_category_id":2,"name":"L&T Heavy Engineering","slug":"lt-heavy-engineering","summary":null,"story":"<p>NAMTECH has partnered with L&amp;T Heavy Engineering, a prominent leader in the industrial and manufacturing sector. This partnership brings together expertise in advanced manufacturing technologies and digital innovation to enhance our academic programmes and industry relevance.<\/p><p>This strategic collaboration reflects NAMTECH\u2019S commitment to delivering industry-relevant education and empowering students to excel in the dynamic fields of AI\/ML, automation, and advanced manufacturing operations.<\/p><p>The partnership with industry leaders like L&amp;T Heavy Engineering to co-design capstone projects, tackle real-world challenges like drone surveillance, and provide direct industry certification is highly beneficial for our young professionals.<\/p>","highlight":null,"website_url":null,"logo_id":30,"image_id":null,"is_featured":false,"sort_order":11,"meta_title":null,"meta_description":null,"og_image_id":null,"canonical_url":null,"noindex":false},"relations":[]}', '2026-11-18 06:43:38', '2026-11-18 06:43:38'),
(40, 'faculty', 1, NULL, 'snapshot', 'Initial content', '{"attributes":{"school_id":1,"category":"residential","name":"Dr. Meera Iyer","slug":"dr-meera-iyer","designation":"Dean of Research, School of Manufacturing Technologies","department":null,"email":null,"phone":null,"summary":null,"bio":"<p>Distinguished academic and industry expert with decades of experience in engineering education, advanced automation, and manufacturing technology. Actively involved in pioneering applied research, mentoring cohorts, and driving industry collaborations at NAMTECH.<\/p>","qualifications":[{"period":"1994 \u2013 1997","title":"PhD","institution":"The Queen\u2019s University of Belfast, United Kingdom","text":null},{"period":"1985 \u2013 1987","title":"MTech","institution":"University of Delhi, Delhi","text":null}],"experience":null,"research":null,"publications":null,"awards":null,"research_interests":"Robotics & Autonomous Systems","profile_url":null,"photo_id":36,"is_featured":false,"sort_order":5,"hidden_blocks":null,"meta_title":null,"meta_description":null,"og_image_id":null,"canonical_url":null,"noindex":false},"relations":{"programs":[]}}', '2026-11-18 06:43:39', '2026-11-18 06:43:39'),
