(92, 'event', 1, NULL, 'snapshot', 'Initial content', '{"attributes":{"category":"conference","school_id":4,"centre_id":null,"title":"Sustainable Manufacturing Summit 2026","slug":"sustainable-manufacturing-summit-2026","subtitle":"Masterclass by Prof. Daniel Philip, MIT","summary":"Experience learning with real industry equipment and state-of-the-art infrastructure designed for the future of manufacturing.","overview":"<p>Join global leaders, faculty, and industry pioneers for an intensive masterclass exploring the future of sustainable manufacturing, decarbonization technologies, and circular economy practices. Experience hands-on sessions in state-of-the-art labs and network with leading academicians from MIT and TUM Asia.<\/p>","outcomes":[{"text":"Understand the core principles of Industry 5.0 and sustainable factory design."},{"text":"Hands-on exposure to decarbonization frameworks, digital twins, and resource efficiency tools."},{"text":"Direct networking with leaders from MIT, TUM Asia, and global manufacturing giants."}],"speaker":{"name":"Prof. Daniel Philip","role":"Dean of Research, MIT","photo":38,"quote":"Sustainability in manufacturing is no longer an optional initiative\u2014it is the engineering discipline that will define industrial competitiveness for the next century.","bio":"<p>Prof. Daniel Philip is the Dean of Research at MIT, specializing in advanced manufacturing systems, precision engineering, and sustainable industrial ecosystems. He has authored over 120 peer-reviewed papers and advises governments and Fortune 500 manufacturers globally.<\/p>"},"starts_at":"2027-04-15 09:00:00","ends_at":"2027-04-15 17:00:00","venue":"NAMTECH Auditorium 3","registration_url":"\/contact","image_id":75,"hidden_blocks":null,"meta_title":null,"meta_description":null,"og_image_id":null,"canonical_url":null,"noindex":false},"relations":[]}', '2026-11-18 06:43:42', '2026-11-18 06:43:42'),
(93, 'job_opening', 1, NULL, 'snapshot', 'Initial content', '{"attributes":{"category":"academic","department":"School of Manufacturing Technologies","title":"Assistant Professor - Mechanical Engineering","slug":"assistant-professor-mechanical-engineering","summary":"Join our faculty and leadership team to shape the future of manufacturing education in India.","description":"<p>We are seeking high-caliber professionals to lead curriculum delivery, student mentorship, and applied research in manufacturing technology, robotics, and industrial leadership. Candidates should have a proven track record of academic or industrial excellence and a passion for hands-on, experiential learning.<\/p><h3>Key Responsibilities<\/h3><ul><li>Design and deliver state-of-the-art experiential coursework and lab modules.<\/li><li>Engage in industry-collaborative research and student capstone projects.<\/li><li>Mentor students for career advancement and global industry placement.<\/li><\/ul>","closes_on":null,"mode":"On Campus (Gujarat Campus)","sort_order":0,"meta_title":null,"meta_description":null,"og_image_id":null,"canonical_url":null,"noindex":false},"relations":[]}', '2026-11-18 06:43:42', '2026-11-18 06:43:42'),
(94, 'job_opening', 2, NULL, 'snapshot', 'Initial content', '{"attributes":{"category":"executive","department":"NAMTECH","title":"Associate \/ Assistant Director - Marketing and Admissions","slug":"associate-assistant-director-marketing-and-admissions","summary":"Join our faculty and leadership team to shape the future of manufacturing education in India.","description":"<p>We are seeking high-caliber professionals to lead curriculum delivery, student mentorship, and applied research in manufacturing technology, robotics, and industrial leadership. Candidates should have a proven track record of academic or industrial excellence and a passion for hands-on, experiential learning.<\/p><h3>Key Responsibilities<\/h3><ul><li>Design and deliver state-of-the-art experiential coursework and lab modules.<\/li><li>Engage in industry-collaborative research and student capstone projects.<\/li><li>Mentor students for career advancement and global industry placement.<\/li><\/ul>","closes_on":null,"mode":"Remote","sort_order":1,"meta_title":null,"meta_description":null,"og_image_id":null,"canonical_url":null,"noindex":false},"relations":[]}', '2026-11-18 06:43:42', '2026-11-18 06:43:42'),
(95, 'job_opening', 3, NULL, 'snapshot', 'Initial content', '{"attributes":{"category":"executive","department":"NAMTECH","title":"MEPF Manager - Mechanical","slug":"mepf-manager-mechanical","summary":"Join our faculty and leadership team to shape the future of manufacturing education in India.","description":"<p>We are seeking high-caliber professionals to lead curriculum delivery, student mentorship, and applied research in manufacturing technology, robotics, and industrial leadership. Candidates should have a proven track record of academic or industrial excellence and a passion for hands-on, experiential learning.<\/p><h3>Key Responsibilities<\/h3><ul><li>Design and deliver state-of-the-art experiential coursework and lab modules.<\/li><li>Engage in industry-collaborative research and student capstone projects.<\/li><li>Mentor students for career advancement and global industry placement.<\/li><\/ul>","closes_on":null,"mode":"On Campus (Gujarat Campus)","sort_order":2,"meta_title":null,"meta_description":null,"og_image_id":null,"canonical_url":null,"noindex":false},"relations":[]}', '2026-11-18 06:43:42', '2026-11-18 06:43:42'),
(96, 'post', 1, NULL, 'snapshot', 'Initial content', '{"attributes":{"type":"news","category_id":1,"post_author_id":1,"title":"AM\/NS India Leadership Visits NAMTECH","slug":"am-ns-india-leadership-visits-namtech","excerpt":"Senior executive leadership from ArcelorMittal Nippon Steel India visited NAMTECH\u2019s living laboratories, reviewing student capstones in automated defect detection and advanced robotics cells.","body":"<p>A high-level executive delegation from ArcelorMittal Nippon Steel India (AM\/NS India) toured NAMTECH\u2019s advanced manufacturing campus to evaluate student-led innovations and review ongoing co-created curriculum initiatives.<\/p><p>The leadership team interacted with undergraduate and postgraduate cohorts working on live industrial capstone challenges, including real-time machine vision inspection systems, robotic welding cells, and industrial IoT monitoring rigs.<\/p><p>AM\/NS India reiterated its long-term commitment to nurturing world-class technical talent in India and expanding industry residency opportunities for NAMTECH graduates across its national manufacturing assets.<\/p>","external_url":null,"document_id":null,"image_id":16,"is_featured":true,"hidden_blocks":null,"meta_title":null,"meta_description":null,"og_image_id":null,"canonical_url":null,"noindex":false},"relations":{"tags":[],"sections":[]}}', '2026-11-18 06:43:42', '2026-11-18 06:43:42'),
(97, 'post', 2, NULL, 'snapshot', 'Initial content', '{"attributes":{"type":"news","category_id":1,"post_author_id":1,"title":"Dr. Bobby Mitra, CIO & President of Tata Electronics, Engages with NAMTECH","slug":"dr-bobby-mitra-cio-and-president-of-tata-electronics-engages-with-namtech","excerpt":"Dr. Bobby Mitra engaged with faculty and students on semiconductor ecosystem scaling, packaging innovations, and India\u2019s growing semiconductor workforce requirements.","body":"<p>Dr. Bobby Mitra, CIO & President of Tata Electronics, delivered a distinguished keynote address to the NAMTECH community, highlighting the transformative potential of India\u2019s semiconductor mission and precision electronics manufacturing.<\/p><p>During the interactive session, Dr. Mitra emphasized the urgent need for skilled technologists proficient in cleanroom operations, advanced lithography, chip packaging, and automated test methodologies.<\/p><p>Tata Electronics and NAMTECH leadership explored collaborative avenues for specialized talent incubation, curriculum benchmarking, and student internships aligned with next-generation semiconductor fabrication lines.<\/p>","external_url":null,"document_id":null,"image_id":17,"is_featured":false,"hidden_blocks":null,"meta_title":null,"meta_description":null,"og_image_id":null,"canonical_url":null,"noindex":false},"relations":{"tags":[],"sections":[]}}', '2026-11-18 06:43:42', '2026-11-18 06:43:42'),
(98, 'post', 3, NULL, 'snapshot', 'Initial content', '{"attributes":{"type":"news","category_id":3,"post_author_id":1,"title":"NAMTECH Strengthens Automotive Engineering Capabilities","slug":"namtech-strengthens-automotive-engineering-capabilities","excerpt":"NAMTECH expanded its Center of Excellence in Automotive Engineering with specialized testbeds for electric vehicle powertrains and autonomous driving simulation.","body":"<p>NAMTECH announced a major expansion of its Center of Excellence in Automotive Engineering, integrating state-of-the-art battery testbenches, electric motor dynos, and hardware-in-the-loop (HIL) simulation stations.<\/p><p>Developed in close consultation with leading automotive OEMs, the facility enables students and industry researchers to design, calibrate, and validate electric vehicle powertrains, battery management systems (BMS), and ADAS safety controllers.<\/p><p>This initiative directly supports India\u2019s accelerating transition to sustainable e-mobility and provides engineering graduates with Day-Zero readiness for global automotive careers.<\/p>","external_url":null,"document_id":null,"image_id":18,"is_featured":false,"hidden_blocks":null,"meta_title":null,"meta_description":null,"og_image_id":null,"canonical_url":null,"noindex":false},"relations":{"tags":[],"sections":[]}}', '2026-11-18 06:43:42', '2026-11-18 06:43:42'),
(99, 'post', 4, NULL, 'snapshot', 'Initial content', '{"attributes":{"type":"blog","category_id":5,"post_author_id":1,"title":"From Industry 4.0 to 5.0: India\u2019s Stride Towards Human\u2013Tech Synergy","slug":"from-industry-40-to-50-indias-stride-towards-human-tech-synergy","excerpt":"An in-depth perspective on the technological and human convergence reshaping modern factories across India and global supply chains.","body":"<h2>Understanding Industry 4.0<\/h2><p>Industry 4.0 represents the ongoing digital transformation of traditional manufacturing and industrial practices. By integrating large-scale cyber-physical systems, IoT sensors, cloud computing, and real-time machine telemetry, modern production lines achieve unprecedented levels of automation, predictive maintenance, and operational visibility.<\/p><h2>India\u2019s Industry 4.0 Journey<\/h2><p>India\u2019s manufacturing landscape is witnessing rapid acceleration under national initiatives like Make in India and Viksit Bharat 2047. Leading enterprises are upgrading legacy infrastructure with intelligent edge devices, AI-driven quality inspection, and automated guided vehicles (AGVs) to compete effectively on the global stage.<\/p><h2>The Requirement of Industry 5.0<\/h2><p>While Industry 4.0 focused intensely on automated efficiency and connectivity, Industry 5.0 re-centers the human element. It pairs human creativity, problem-solving, and cognitive nuance with the repetitive precision and physical strength of collaborative robots (cobots) to deliver bespoke, sustainable products.<\/p><h2>Unlocking Limitless Potential<\/h2><p>Realizing the full promise of advanced manufacturing demands a new breed of engineering professionals who move comfortably between mechanical shop floors and advanced digital systems. Immersive educational models that emphasize hands-on experimentation are vital to closing this capability divide.<\/p><h2>Manufacturing as India\u2019s Global Game-Changer<\/h2><p>Sustainable, digitally empowered manufacturing is set to be the primary engine of India\u2019s economic growth in the 21st century. By cultivating skilled talent equipped for Industry 5.0, India can pioneer resilient industrial ecosystems that balance high productivity with environmental stewardship.<\/p>","external_url":null,"document_id":null,"image_id":76,"is_featured":true,"hidden_blocks":null,"meta_title":null,"meta_description":null,"og_image_id":null,"canonical_url":null,"noindex":false},"relations":{"tags":[],"sections":[]}}', '2026-11-18 06:43:42', '2026-11-18 06:43:42'),
(100, 'post', 5, NULL, 'snapshot', 'Initial content', '{"attributes":{"type":"story","category_id":6,"post_author_id":1,"title":"iPTP Graduate \u2192 Smart Manufacturing Engineer, Germany","slug":"iptp-graduate-to-smart-manufacturing-engineer-germany","excerpt":"Aruna Kumari, an iPTP student from a Tier-3 town, joined NAMTECH without experience. She became a manufacturing engineer at a global automotive supplier in Germany, focusing on production optimization.","body":"<p>Coming from a humble background in a Tier-3 town, Aruna Kumari joined NAMTECH\u2019s International Professional Technologist Program with an aspiration to master industrial automation. Through intensive hands-on training on Siemens PLC systems, ABB robotics cells, and digital simulation tools, she developed deep technical fluency.<\/p><p>Following an outstanding industry residency, Aruna was recruited by a premier tier-1 German automotive manufacturing enterprise, where she now oversees automated assembly line optimization and predictive maintenance architectures.<\/p><p>\u201cNAMTECH didn\u2019t just teach me theory\u2014it gave me real machines, industrial mentors, and the confidence to operate at global standards,\u201d says Aruna.<\/p>","external_url":null,"document_id":null,"image_id":59,"is_featured":true,"hidden_blocks":null,"meta_title":null,"meta_description":null,"og_image_id":null,"canonical_url":null,"noindex":false},"relations":{"tags":[],"sections":[]}}', '2026-11-18 06:43:42', '2026-11-18 06:43:42');
INSERT INTO `content_revisions` VALUES
(101, 'post', 6, NULL, 'snapshot', 'Initial content', '{"attributes":{"type":"story","category_id":6,"post_author_id":1,"title":"NAMTECH Graduate Experiences Nearly 90% Increase in Salary","slug":"namtech-graduate-experiences-nearly-90-increase-in-salary","excerpt":"Rohan Patel transitioned from entry-level plant maintenance to a high-growth Industrial AI Lead role with an 88% compensation increase post-graduation.","body":"<p>After working for two years in conventional mechanical maintenance, Rohan Patel sought to future-proof his career by enrolling in NAMTECH\u2019s Master in Smart Manufacturing Technology & Management.<\/p><p>Equipped with specialized capabilities in cyber-physical systems, digital twin simulation, and machine vision analytics, Rohan received multiple competitive job offers during campus placements, ultimately accepting an Industrial AI Lead position at \u20b918 LPA\u2014an 88% leap over his prior CTC.<\/p><p>\u201cThe experiential labs at NAMTECH bridge the exact gap between traditional engineering and modern Industry 4.0 factories,\u201d Rohan remarked.<\/p>","external_url":null,"document_id":null,"image_id":77,"is_featured":false,"hidden_blocks":null,"meta_title":null,"meta_description":null,"og_image_id":null,"canonical_url":null,"noindex":false},"relations":{"tags":[],"sections":[]}}', '2026-11-18 06:43:42', '2026-11-18 06:43:42'),
(102, 'post', 7, NULL, 'snapshot', 'Initial content', '{"attributes":{"type":"story","category_id":10,"post_author_id":1,"title":"NAMTECH Students Revolutionize Prosthetics Design using 3D Printing","slug":"namtech-students-revolutionize-prosthetics-design-using-3d-printing","excerpt":"A multidisciplinary student team deployed advanced additive manufacturing technologies to produce low-cost, patient-customized prosthetic limbs.","body":"<p>A student research team from the School of Manufacturing Technologies and School of Robotics successfully engineered a patient-customized, 3D-printed bionic prosthetic hand capable of multi-grip adaptability.<\/p><p>Leveraging NAMTECH\u2019s Additive Manufacturing & Precision Engineering Lab, the team utilized SLA resin printing and biocompatible carbon-reinforced polymers, reducing fabrication costs by 80% compared to conventional prosthetics while maintaining exceptional structural durability.<\/p><p>The project received top recognition at the National Smart Manufacturing Hackathon and is currently undergoing clinical trials with partner healthcare institutions.<\/p>","external_url":null,"document_id":null,"image_id":60,"is_featured":false,"hidden_blocks":null,"meta_title":null,"meta_description":null,"og_image_id":null,"canonical_url":null,"noindex":false},"relations":{"tags":[],"sections":[]}}', '2026-11-18 06:43:43', '2026-11-18 06:43:43'),
(103, 'gallery', 1, NULL, 'snapshot', 'Initial content', '{"attributes":{"title":"Campus life and facilities","slug":"campus","description":null,"virtual_tour_url":null,"cover_id":12,"sort_order":0,"meta_title":null,"meta_description":null,"og_image_id":null,"canonical_url":null,"noindex":false},"relations":{"items":[]}}', '2026-11-18 06:43:43', '2026-11-18 06:43:43'),
(104, 'page', 1, NULL, 'snapshot', 'Initial content', '{"attributes":{"parent_id":null,"title":"Home","slug":"home","template":"home","excerpt":null,"sort_order":0,"meta_title":null,"meta_description":"NAMTECH prepares the next generation of innovators who are shaping the future of manufacturing in India.","og_image_id":null,"canonical_url":null,"noindex":false},"relations":{"sections":[{"type":"home_hero","label":null,"anchor":null,"is_visible":true,"data":{"badges":[{"text":"Make in India"},{"text":"Industry 4.0"},{"text":"Viksit Bharat 2047"}],"slides":[{"title":"Powering India\u2019s Next Manufacturing Revolution","body":"NAMTECH prepares the next generation of innovators who are shaping the future of manufacturing in India.","image":1,"cta_label":null,"cta_url":null}]}},{"type":"feature_blocks","label":null,"anchor":null,"is_visible":true,"data":{"eyebrow":"The NAMTECH Learning Model","heading":"A New Blueprint for Manufacturing Education","items":[{"title":"Specialized Labs","body":"Our labs are our classrooms. Students work with specialized, industry-grade equipment, mirroring the environments in which they will work and lead. Studying at NAMTECH is an experience rooted in practice. Students develop their capabilities by applying theoretical concepts and not just knowing them.","image":2,"link_url":"\/academics\/labs-and-infrastructure"},{"title":"Experiential Learning","body":"Learning at NAMTECH is deeply experiential. Through a problem-led approach, students apply concepts in real-world contexts to solve complex problems in modern manufacturing and engineering. Students learn by doing, building, and making.","image":3,"link_url":"\/academics\/pedagogy"},{"title":"Integrated Industry Partnerships","body":"Industry partnerships are the cornerstone of our education model, which goes far beyond textbook scenarios. At NAMTECH, students work on active industrial projects and gain expertise in real manufacturing processes and challenges.","image":67,"link_url":"\/partnerships\/corporate"},{"title":"Industry-Driven Placements","body":"Our placements are aligned with the future of industry, not just the jobs of today. With NAMTECH\u2019s strong industry partnerships, students gain access to elusive career opportunities in advanced manufacturing and technology at leading organizations.","image":4,"link_url":"\/placements"},{"title":"Global Academic Collaboration","body":"At NAMTECH, students are taught by the minds shaping modern manufacturing education. Co-created with global academic institutions and leading industry practitioners, the curriculum is built around real industry scenarios, ensuring graduates are prepared to lead from day one.","image":5,"link_url":"\/partnerships\/academic"},{"title":"Inclusivity","body":"At NAMTECH, world-class manufacturing education is designed to reach talent across every level. Through specialized learning pathways and dedicated programs for undergraduate & postgraduate engineering students, ITI & Diploma holders, faculty, and executives, we cultivate talent that can be deployed across levels of the organization.","image":6,"link_url":"\/school-of-technical-education"}]}},{"type":"academics_tabs","label":null,"anchor":null,"is_visible":true,"data":{"eyebrow":"Schools, Centres & Programs","heading":"MET Innovation Schools: Engineering Education for Industry 5.0","schools_label":"MET Innovation Schools","centres_label":"MET Innovation Centers","programs_label":"MET Programs","schools_heading":"MET Innovation Schools: Engineering Education for Industry 5.0","schools_body":"The Manufacturing Engineering Technology (MET) Innovation Schools at NAMTECH prepare graduates to become next-generation industrial and technology leaders. Through an industry-integrated approach, experiential learning, highly practical and specialized education, and applied innovation, each school builds deep expertise in critical domains shaping the future of manufacturing.","centres_heading":"MET Innovation Centers - Shaping Innovation for Industry 5.0","centres_body":"MET Innovation Centers at NAMTECH are built around a simple principle: innovation is best learned by doing. Students work alongside faculty and industry to explore emerging technologies, tackle real-world challenges, and develop practical solutions through applied research, experimentation, and domain-specific programs co-created and co-delivered with industry.","programs_heading":"MET Programs","programs_body":"At NAMTECH, we understand that running the industries of the future will require deep technical and engineering expertise alongside strong leadership capabilities.\n\nThe programs are built in collaboration with industry experts and globally leading institutions, as well as are deeply experiential. This immersive approach helps NAMTECH graduates develop the hands-on expertise and decisive strategic thinking needed to lead tomorrow\u2019s industries and contribute to India\u2019s industrial transformation.","default_tab":"schools","featured_only":false}},{"type":"partners_showcase","label":null,"anchor":null,"is_visible":true,"data":{"eyebrow":"Partnerships","heading":"Learning with Leading Global Universities & Industries","body":"Through strategic partnerships with global industry leaders and premier academic institutions, NAMTECH delivers education shaped by real-world insights and advanced technologies. We integrate advanced technologies, experiential learning on industry-grade equipment, and actual industry practices to offer an unparalleled learning experience.","cta_label":null,"cta_url":null,"cta2_label":"Corporate Partnership","cta2_url":"\/partnerships\/corporate","cta3_label":"Academic Partnership","cta3_url":"\/partnerships\/academic","category":null,"show_stories":true,"stories_cta_label":"Read all stories","stories_cta_url":"\/partnerships"}},{"type":"faculty_showcase","label":null,"anchor":null,"is_visible":true,"data":{"eyebrow":"Faculty","heading":"Learn from\nGlobal Experts","body":"NAMTECH\u2019s world-class faculty includes leading academicians, industry leaders, and technology experts who bring decades of rich experience and real-world insights into the classroom to shape technically rigorous, industry-ready professionals.","cta_label":"Explore Faculty","cta_url":"\/faculty","school":null}},{"type":"labs_showcase","label":null,"anchor":null,"is_visible":true,"data":{"eyebrow":"Labs & Infrastructure","heading":"Next-Gen Labs\n& Facilities","body":"With state-of-the-art infrastructure and experiential labs, students gain hands-on experience on real-industry equipment designed for the future of manufacturing.","cta_label":"Explore More","cta_url":"\/academics\/labs-and-infrastructure","slides":[{"image":10,"caption_start":"Learning with real machines","caption_end":"Into the real world","video_url":null},{"image":11,"caption_start":"Learning with real machines","caption_end":"Into the real world","video_url":null},{"image":21,"caption_start":"Learning with real machines","caption_end":"Into the real world","video_url":null}]}},{"type":"campus_showcase","label":null,"anchor":null,"is_visible":true,"data":{"eyebrow":"Campus","heading":"A World-Class Industry-Integrated Campus","body":"Built to replicate the smart manufacturing ecosystems shaping today\u2019s industrial landscape, the NAMTECH campus houses advanced labs, industry-grade equipment, and AI-enabled phygital learning experiences that simulate real industrial environments. The NAMTECH campus embodies MET philosophy \u2014 enabling convergence of technology, academic experience, and industry to make learning deeply applied and relevant.","feature_title":"Advanced Manufacturing Labs & Facilities","feature_body":"This immersive approach enables students to develop hands-on expertise, adapt to evolving technologies and be industry-ready from day one.","gallery":"campus","cta_label":"Explore Campus","cta_url":"\/campus","tour_label":"Virtual tour"}},{"type":"mission","label":null,"anchor":null,"is_visible":true,"data":{"heading":"Built to Build India - The 3 Million Mission","body":"NAMTECH is on a movement to work with ITIs across India to prepare a future-ready workforce for the era of advanced manufacturing. We hold a vision to empower 3 million young Indians in Industry 4.0 & 5.0 technologies as well as sustainability imperatives. Through this initiative, we are upgrading ITIs with advanced infrastructure, industry-aligned curricula, and training-the-trainer programs. Combined with mentorship and placement pathways, it is creating a new generation of industry-ready and globally competitive talent.","statistics_group":null,"limit":3,"cta_label":"Join Our Mission","cta_url":"\/school-of-technical-education\/outreach"}},{"type":"news_carousel","label":null,"anchor":null,"is_visible":true,"data":{"heading":"News & Insights","post_type":"news","limit":8,"cta_label":"View all insights","cta_url":"\/media"}}]}}', '2026-11-18 06:43:44', '2026-11-18 06:43:44'),
(105, 'page', 2, NULL, 'snapshot', 'Initial content', '{"attributes":{"parent_id":null,"title":"About NAMTECH","slug":"about","template":"default","excerpt":null,"sort_order":0,"meta_title":null,"meta_description":null,"og_image_id":null,"canonical_url":null,"noindex":false},"relations":{"sections":[{"type":"page_hero","label":null,"anchor":null,"is_visible":true,"data":{"eyebrow":"About us","title":"About NAMTECH","body":"New Age Makers\u2019 Institute of Technology (NAMTECH), by ArcelorMittal Nippon Steel India, is India\u2019s first Manufacturing Engineering & Technology institute.","image":89,"cta_label":null,"cta_url":null,"secondary_label":null,"secondary_url":null,"statistics_group":null,"layout":null,"meta":[]}},{"type":"subnav","label":null,"anchor":null,"is_visible":true,"data":{"items":[{"label":"About Us","url":"\/about"},{"label":"Board of Directors","url":"\/about\/board-of-directors"},{"label":"Advisory Council","url":"\/about\/advisory-council"},{"label":"Management Team","url":"\/about\/management-team"},{"label":"Mandatory Disclosures","url":"\/about\/mandatory-disclosures"},{"label":"Ranks And Accreditations","url":"\/about\/ranks-and-accreditations"}]}},{"type":"image_statement","label":null,"anchor":null,"is_visible":true,"data":{"eyebrow":null,"heading":"Our Purpose","body":"To empower 3 million youth with advancement in the MET sector and position India as a global hub for manufacturing excellence.","image":90,"position":"right"}},{"type":"image_statement","label":null,"anchor":null,"is_visible":true,"data":{"eyebrow":null,"heading":"Our Vision","body":"To empower 3 million youth with advancement in the MET sector and position India as a global hub for manufacturing excellence.","image":91,"position":"left"}},{"type":"value_list","label":null,"anchor":null,"is_visible":true,"data":{"eyebrow":null,"heading":"Our Core Values","body":"An integrated approach combining Manufacturing excellence with cutting-edge digital technologies.","items":[{"icon":"people","title":"Inclusivity & Opportunity","text":"Creating accessible, transformative technical education pathways for youth from all socio-economic backgrounds across India."},{"icon":"gear","title":"Hands-On Applied Learning","text":"Embedding learners directly in living factory simulations and cutting-edge labs where real industry problems are solved."},{"icon":"lightbulb","title":"Industry-Driven Curriculum","text":"Co-designing, co-delivering, and continuously iterating programs in lockstep with the world\u2019s leading industrial enterprises."}]}},{"type":"card_grid","label":null,"anchor":null,"is_visible":true,"data":{"eyebrow":"What We Do","heading":"Cultivating Talent for India\u2019s Manufacturing Dominance","body":null,"columns":"4","tone":"white","cards":[{"icon":"people","title":"Transforming India\u2019s Technician Workforce","body":null,"link_url":null},{"icon":"robot","title":"Experiential Learning Through Advanced Technology","body":null,"link_url":null},{"icon":"factory","title":"Industry-integrated, applied learning models","body":null,"link_url":null},{"icon":"globe","title":"Scaling Skills Access Across India","body":null,"link_url":null}],"style":"joined","cta_label":null,"cta_url":null}},{"type":"timeline","label":null,"anchor":null,"is_visible":true,"data":{"eyebrow":null,"heading":"Our Story","body":null,"items":[{"year":"2022","title":"June, 2022","text":"NAMTECH received the Letter of Intent from the University Grants Commission, marking a key step towards recognition as a Deemed-to-be-University.","image":92},{"year":"2023","title":"2023","text":"Inaugural cohort of International Professional Technologist Program (iPTP) commenced with 100% placement track record.","image":93},{"year":"2024","title":"2024","text":"Launched the School of Smart Manufacturing and state-of-the-art experiential learning labs in collaboration with global industry partners.","image":94},{"year":"2025","title":"2025","text":"Expanded academic and research partnerships with world-renowned technical institutes including TUM Asia and IIT Roorkee.","image":95},{"year":"2026","title":"2026","text":"Pioneering the future of manufacturing education with next-generation living labs and comprehensive industry co-creation.","image":55}]}},{"type":"video_feature","label":null,"anchor":null,"is_visible":true,"data":{"layout":"split","eyebrow":null,"heading":"Created to aid India\u2019s growth and development.","body":"New Age Makers\u2019 Institute of Technology (NAMTECH), by ArcelorMittal Nippon Steel India, is India\u2019s first Manufacturing Engineering & Technology institute. It supports \u2018Make in India\u2019 and \u2018Viksit Bharat 2047\u2019 by offering advanced engineering programs and promoting responsible technology. NAMTECH prepares young professionals with Industry 4.0 skills and training.","name":null,"role":null,"image":93,"video_url":null}},{"type":"intro","label":null,"anchor":null,"is_visible":true,"data":{"eyebrow":"About the Founder","heading":"About the Founder: AM\/NS India","body":"<p>ArcelorMittal Nippon Steel India (AM\/NS India) is an integrated flat carbon steel manufacturer with an ambition to drive modern industrial growth. As the founding partner of NAMTECH, AM\/NS India is committed to building a world-class manufacturing ecosystem in India through education, cutting-edge technology, and skilled talent. Created to aid India''s growth and development, this partnership ensures education is aligned directly with industrial excellence.<\/p>","cta_label":null,"cta_url":null,"icon":null,"tone":null}},{"type":"cta_band","label":null,"anchor":null,"is_visible":true,"data":{"heading":"Have Questions? Get in touch with us","body":"We partner with the best of industry, academia, and technology to co-create curriculum and align training with workforce needs. Partner with us to shape a skilled workforce for India\u2019s future.","cta_label":"Contact us","cta_url":"\/contact","tone":null}}]}}', '2026-11-18 06:43:44', '2026-11-18 06:43:44'),
