ile":null,"url":null,"meta":null},{"title":"Notarized legal Undertaking","file":null,"url":null,"meta":null},{"title":"Details of the proposed academic and physical infrastructure","file":null,"url":null,"meta":null},{"title":"Other common and recreational facilities (proposed)","file":null,"url":null,"meta":null},{"title":"Faculty Details (as per format)","file":null,"url":null,"meta":null},{"title":"Diversity, Equity, & Inclusion Policy at NAMTECH","file":null,"url":null,"meta":null}],"layout":"grid","body":null,"tone":null}},{"type":"documents","label":null,"anchor":null,"is_visible":true,"data":{"eyebrow":null,"heading":"Annual Reports","items":[{"title":"2024-2025","file":null,"url":null,"meta":null},{"title":"2023-2024","file":null,"url":null,"meta":null},{"title":"2022-2023","file":null,"url":null,"meta":null}],"layout":"list","body":null,"tone":"light"}}]}}', '2026-11-18 06:43:45', '2026-11-18 06:43:45'),
(110, 'page', 7, NULL, 'snapshot', 'Initial content', '{"attributes":{"parent_id":2,"title":"Ranks & Accreditations","slug":"ranks-and-accreditations","template":"default","excerpt":null,"sort_order":0,"meta_title":null,"meta_description":null,"og_image_id":null,"canonical_url":null,"noindex":false},"relations":{"sections":[{"type":"page_hero","label":null,"anchor":null,"is_visible":true,"data":{"eyebrow":"About us","title":"Ranks & Accreditations","body":null,"image":97,"cta_label":null,"cta_url":null,"secondary_label":null,"secondary_url":null,"statistics_group":null,"layout":null,"meta":[]}},{"type":"subnav","label":null,"anchor":null,"is_visible":true,"data":{"items":[{"label":"About Us","url":"\/about"},{"label":"Board of Directors","url":"\/about\/board-of-directors"},{"label":"Advisory Council","url":"\/about\/advisory-council"},{"label":"Management Team","url":"\/about\/management-team"},{"label":"Mandatory Disclosures","url":"\/about\/mandatory-disclosures"},{"label":"Ranks And Accreditations","url":"\/about\/ranks-and-accreditations"}]}},{"type":"intro","label":null,"anchor":null,"is_visible":true,"data":{"eyebrow":null,"heading":"Ranks & Accreditations","body":"<p>NAMTECH is recognized by premier regulatory and academic bodies in India and globally, holding Letters of Intent, university affiliations, and global certifications that attest to our world-class educational standards. Our programs and platforms are benchmarked against international standards from MIT, TUM Asia, and WorldSkills.<\/p>","cta_label":null,"cta_url":null,"icon":"award","tone":null}}]}}', '2026-11-18 06:43:45', '2026-11-18 06:43:45'),
(111, 'page', 8, NULL, 'snapshot', 'Initial content', '{"attributes":{"parent_id":null,"title":"Academics","slug":"academics","template":"default","excerpt":null,"sort_order":0,"meta_title":null,"meta_description":null,"og_image_id":null,"canonical_url":null,"noindex":false},"relations":{"sections":[{"type":"page_hero","label":null,"anchor":null,"is_visible":true,"data":{"eyebrow":"Academics","title":"Transforming Education Through Innovation & Industry Integration","body":null,"image":100,"cta_label":null,"cta_url":null,"secondary_label":null,"secondary_url":null,"statistics_group":null,"layout":null,"meta":[]}},{"type":"intro","label":null,"anchor":null,"is_visible":true,"data":{"eyebrow":null,"heading":"Our Educational Philosophy","body":"<p>We believe engineering education must be rooted in active practice. Our problem-led pedagogy places learners directly in simulated factory environments and state-of-the-art labs, ensuring they build, test, and iterate with real industry machines rather than passive textbook learning.<\/p>","cta_label":null,"cta_url":null,"icon":"lightbulb","tone":null}},{"type":"media_cards","label":null,"anchor":null,"is_visible":true,"data":{"eyebrow":null,"heading":"Our Learning Model","body":null,"items":[{"image":98,"logo":null,"icon":"graduation","tag":null,"date":null,"title":"Competency-Based Learning","subtitle":null,"body":"We focus on mastering skills, not just completing courses. Learners progress through personalized pathways, acquiring technical, professional, and leadership competencies at their own pace. This ensures deep understanding, measurable skill development, and real-world readiness.","meta":null,"link_url":null},{"image":99,"logo":null,"icon":"gear","tag":null,"date":null,"title":"Project-Based Learning","subtitle":null,"body":"Every learner solves real-world problems through hands-on projects co-designed with industry partners. This immersive approach bridges theory with practice and transforms learners into solution-oriented technologists capable of delivering impact from day one.","meta":null,"link_url":null},{"image":94,"logo":null,"icon":"award","tag":null,"date":null,"title":"Competition-Based Learning","subtitle":null,"body":"To spark innovation and critical thinking, learners engage in challenges and competitions that mirror global industry scenarios. These experiences encourage healthy competition, collaboration, and creativity-pushing learners to raise the bar continuously.","meta":null,"link_url":null}],"layout":"horizontal","tone":null,"cta_label":null,"cta_url":null,"footer_label":null,"footer_url":null,"card_link_label":null}},{"type":"academics_tabs","label":null,"anchor":null,"is_visible":true,"data":{"eyebrow":"Schools, Centres, and Programs","heading":"NAMTECH\u2019s Innovation Schools for the Future of Manufacturing","schools_label":"Schools","centres_label":"Centres","programs_label":"Programs","schools_heading":null,"schools_body":null,"centres_heading":null,"centres_body":null,"programs_heading":null,"programs_body":null,"default_tab":"schools","featured_only":false}},{"type":"cta_band","label":null,"anchor":null,"is_visible":true,"data":{"heading":"Ready to Transform Your Future?","body":null,"cta_label":"View all programs","cta_url":"\/programs","tone":null}}]}}', '2026-11-18 06:43:45', '2026-11-18 06:43:45'),
(112, 'page', 9, NULL, 'snapshot', 'Initial content', '{"attributes":{"parent_id":8,"title":"Pedagogy","slug":"pedagogy","template":"default","excerpt":null,"sort_order":0,"meta_title":null,"meta_description":null,"og_image_id":null,"canonical_url":null,"noindex":false},"relations":{"sections":[{"type":"page_hero","label":null,"anchor":null,"is_visible":true,"data":{"eyebrow":"Pedagogy","title":"Transforming Education Through Innovation & Industry Integration","body":null,"image":100,"cta_label":null,"cta_url":null,"secondary_label":null,"secondary_url":null,"statistics_group":null,"layout":null,"meta":[]}},{"type":"intro","label":null,"anchor":null,"is_visible":true,"data":{"eyebrow":null,"heading":"Our Educational Philosophy","body":"<p>We believe engineering education must be rooted in active practice. Our problem-led pedagogy places learners directly in simulated factory environments and state-of-the-art labs, ensuring they build, test, and iterate with real industry machines rather than passive textbook learning.<\/p>","cta_label":null,"cta_url":null,"icon":"lightbulb","tone":null}},{"type":"media_cards","label":null,"anchor":null,"is_visible":true,"data":{"eyebrow":null,"heading":"Our Learning Model","body":null,"items":[{"image":98,"logo":null,"icon":"graduation","tag":null,"date":null,"title":"Competency-Based Learning","subtitle":null,"body":"We focus on mastering skills, not just completing courses. Learners progress through personalized pathways, acquiring technical, professional, and leadership competencies at their own pace. This ensures deep understanding, measurable skill development, and real-world readiness.","meta":null,"link_url":null},{"image":99,"logo":null,"icon":"gear","tag":null,"date":null,"title":"Project-Based Learning","subtitle":null,"body":"Every learner solves real-world problems through hands-on projects co-designed with industry partners. This immersive approach bridges theory with practice and transforms learners into solution-oriented technologists capable of delivering impact from day one.","meta":null,"link_url":null},{"image":94,"logo":null,"icon":"award","tag":null,"date":null,"title":"Competition-Based Learning","subtitle":null,"body":"To spark innovation and critical thinking, learners engage in challenges and competitions that mirror global industry scenarios. These experiences encourage healthy competition, collaboration, and creativity-pushing learners to raise the bar continuously.","meta":null,"link_url":null}],"layout":"horizontal","tone":null,"cta_label":null,"cta_url":null,"footer_label":null,"footer_url":null,"card_link_label":null}},{"type":"stat_cards","label":null,"anchor":null,"is_visible":true,"data":{"eyebrow":null,"heading":"Outcomes","body":"Real-world labs designed to move you from theory to application, where you work on live systems, industry tools, and future-ready technologies shaping energy, infrastructure, and sustainable cities.","tone":"lavender","items":[{"icon":"trend","value":"100%","label":"Placement","text":null},{"icon":"people","value":"500+","label":"Students","text":null},{"icon":"handshake","value":"121+","label":"Recruiters","text":null}]}},{"type":"media_cards","label":null,"anchor":null,"is_visible":true,"data":{"eyebrow":null,"heading":"Labs and Facilities","body":null,"items":[{"image":85,"logo":null,"icon":null,"tag":null,"date":null,"title":"Additive Manufacturing & Precision Engineering Lab","subtitle":null,"body":null,"meta":null,"link_url":"\/academics\/labs-and-infrastructure\/additive-manufacturing-and-precision-engineering-lab"},{"image":83,"logo":null,"icon":null,"tag":null,"date":null,"title":"Hydrogen Innovation Lab","subtitle":null,"body":"Explore the full hydrogen ecosystem, from production to storage to fuel cell applications.","meta":null,"link_url":null},{"image":84,"logo":null,"icon":null,"tag":null,"date":null,"title":"Water Stewardship Lab","subtitle":null,"body":"Solve water challenges through smart monitoring, filtration, and climate-resilient systems.","meta":null,"link_url":null}],"layout":"tall","tone":null,"cta_label":"View All","cta_url":"\/academics\/labs-and-infrastructure","footer_label":null,"footer_url":null,"card_link_label":"Know More"}},{"type":"cta_band","label":null,"anchor":null,"is_visible":true,"data":{"heading":"Ready to Transform Your Future?","body":null,"cta_label":"Apply Now","cta_url":"\/admissions","tone":null}}]}}', '2026-11-18 06:43:45', '2026-11-18 06:43:45'),
(113, 'page', 10, NULL, 'snapshot', 'Initial content', '{"attributes":{"parent_id":8,"title":"Labs & Infrastructure","slug":"labs-and-infrastructure","template":"default","excerpt":null,"sort_order":0,"meta_title":null,"meta_description":null,"og_image_id":null,"canonical_url":null,"noindex":false},"relations":{"sections":[{"type":"page_hero","label":null,"anchor":null,"is_visible":true,"data":{"eyebrow":"Labs & Infrastructure","title":"NAMTECH\u2019s State-of-the-Art Infrastructure & Laboratories","body":null,"image":101,"cta_label":"Schedule a Campus Tour","cta_url":"\/contact","secondary_label":null,"secondary_url":null,"statistics_group":null,"layout":null,"meta":[]}},{"type":"media_cards","label":null,"anchor":null,"is_visible":true,"data":{"eyebrow":null,"heading":"Labs","body":null,"items":[{"image":85,"logo":null,"icon":null,"tag":null,"date":null,"title":"Additive Manufacturing & Precision Engineering Lab","subtitle":null,"body":null,"meta":null,"link_url":"\/academics\/labs-and-infrastructure\/additive-manufacturing-and-precision-engineering-lab"},{"image":33,"logo":null,"icon":null,"tag":null,"date":null,"title":"Sustainable Energy Labs","subtitle":null,"body":"Work on real-world renewable systems, from generation to consumption, using IoT-driven optimisation.","meta":null,"link_url":null},{"image":83,"logo":null,"icon":null,"tag":null,"date":null,"title":"Hydrogen Innovation Lab","subtitle":null,"body":"Explore the full hydrogen ecosystem, from production to storage to fuel cell applications.","meta":null,"link_url":null},{"image":84,"logo":null,"icon":null,"tag":null,"date":null,"title":"Water Stewardship Lab","subtitle":null,"body":"Solve water challenges through smart monitoring, filtration, and climate-resilient systems.","meta":null,"link_url":null},{"image":35,"logo":null,"icon":null,"tag":null,"date":null,"title":"Smart Grid & Energy Systems Lab","subtitle":null,"body":"Build and optimise intelligent energy networks with automation, efficiency, and grid analytics.","meta":null,"link_url":null},{"image":82,"logo":null,"icon":null,"tag":null,"date":null,"title":"ESG Analytics Lab","subtitle":null,"body":"Turn sustainability data into action using reporting tools, automation, and compliance frameworks.","meta":null,"link_url":null},{"image":78,"logo":null,"icon":null,"tag":null,"date":null,"title":"Urban Digitalisation Lab","subtitle":null,"body":"Use AI, IoT, and data to design smarter, more efficient urban environments.","meta":null,"link_url":null}],"layout":"tall","tone":null,"cta_label":null,"cta_url":null,"footer_label":null,"footer_url":null,"card_link_label":"Know More"}},{"type":"tabs","label":null,"anchor":null,"is_visible":true,"data":{"eyebrow":null,"heading":"Campus & Facilities","body":null,"tabs":[{"label":"Campus","title":"Campus","body":"<p>Our world-class campus combines modern architecture with state-of-the-art experiential learning facilities. Designed for active collaboration, students interact with advanced machinery, collaborative robots, and high-performance computing clusters in an environment that mirrors premier global factories.<\/p>","image":91},{"label":"Classrooms","title":"Classrooms","body":"<p>Our interactive lecture theatres and smart classrooms feature collaborative seating, high-definition digital smart boards, and live simulation capabilities, allowing faculty and industry experts to seamlessly blend conceptual teaching with real-time digital factory demonstrations.<\/p>","image":95},{"label":"Hostel","title":"Hostel","body":"<p>Well-appointed student residences offer modern amenities, high-speed connectivity, communal recreation spaces, and round-the-clock security, fostering a vibrant residential learning community where ideas and peer collaboration thrive.<\/p>","image":55},{"label":"Library","title":"Library","body":"<p>The NAMTECH Knowledge Centre provides extensive physical collections and 24\/7 digital access to global technical publications, research journals, standard engineering codes, and international manufacturing case studies.<\/p>","image":102}],"layout":"standard","tone":null}},{"type":"cta_band","label":null,"anchor":null,"is_visible":true,"data":{"heading":"Experience NAMTECH Campus","body":null,"cta_label":"Take the 360\u00b0 tour","cta_url":"\/campus\/virtual-tour","tone":null}}]}}', '2026-11-18 06:43:46', '2026-11-18 06:43:46'),
