(115, 'page', 12, NULL, 'snapshot', 'Initial content', '{"attributes":{"parent_id":null,"title":"All Programs","slug":"programs","template":"default","excerpt":null,"sort_order":0,"meta_title":null,"meta_description":null,"og_image_id":null,"canonical_url":null,"noindex":false},"relations":{"sections":[{"type":"page_hero","label":null,"anchor":null,"is_visible":true,"data":{"eyebrow":"Academics","title":"Building India\u2019s Next Manufacturing & Technology Leaders","body":"Aligned with national manufacturing priorities, NAMTECH delivers world-class, industry-integrated undergraduate, postgraduate, and technical programs designed to build tomorrow\u2019s engineering visionaries.","image":7,"cta_label":null,"cta_url":null,"secondary_label":null,"secondary_url":null,"statistics_group":null,"layout":null,"meta":[]}},{"type":"programs_list","label":null,"anchor":null,"is_visible":true,"data":{"eyebrow":"Undergraduate","heading":"Bachelors Programmes","level":"undergraduate","school":null}},{"type":"programs_list","label":null,"anchor":null,"is_visible":true,"data":{"eyebrow":"Postgraduate","heading":"Masters Programmes","level":"postgraduate","school":null}},{"type":"programs_list","label":null,"anchor":null,"is_visible":true,"data":{"eyebrow":"Technical & Executive","heading":"Executive & Technical Programmes","level":"technical","school":null}},{"type":"media_cards","label":null,"anchor":null,"is_visible":true,"data":{"eyebrow":"Living Labs","heading":"World-Class Labs & Infrastructure","body":"With state-of-the-art infrastructure and experiential labs, students gain hands-on experience on real-industry equipment designed for the future of manufacturing.","items":[{"image":33,"logo":null,"icon":null,"tag":null,"date":null,"title":"Sustainable Energy Labs","subtitle":null,"body":"Work on real-world renewable systems, from generation to consumption, using IoT-driven optimisation.","meta":null,"link_url":null},{"image":83,"logo":null,"icon":null,"tag":null,"date":null,"title":"Hydrogen Innovation Lab","subtitle":null,"body":"Explore the full hydrogen ecosystem, from production to storage to fuel cell applications.","meta":null,"link_url":null},{"image":84,"logo":null,"icon":null,"tag":null,"date":null,"title":"Water Stewardship Lab","subtitle":null,"body":"Solve water challenges through smart monitoring, filtration, and climate-resilient systems.","meta":null,"link_url":null},{"image":35,"logo":null,"icon":null,"tag":null,"date":null,"title":"Smart Grid & Energy Systems Lab","subtitle":null,"body":"Build and optimise intelligent energy networks with automation, efficiency, and grid analytics.","meta":null,"link_url":null},{"image":82,"logo":null,"icon":null,"tag":null,"date":null,"title":"ESG Analytics Lab","subtitle":null,"body":"Turn sustainability data into action using reporting tools, automation, and compliance frameworks.","meta":null,"link_url":null},{"image":78,"logo":null,"icon":null,"tag":null,"date":null,"title":"Urban Digitalisation Lab","subtitle":null,"body":"Use AI, IoT, and data to design smarter, more efficient urban environments.","meta":null,"link_url":null}],"layout":"tall","tone":null,"cta_label":"Explore Labs","cta_url":"\/academics\/labs-and-infrastructure","footer_label":null,"footer_url":null,"card_link_label":null}},{"type":"faq","label":null,"anchor":null,"is_visible":true,"data":{"heading":"Frequently Asked Questions","body":"Find answers to common questions about our academic programs, admissions process, and career pathways.","items":[{"question":"What makes NAMTECH\u2019s undergraduate programs different from traditional B.Tech degrees?","answer":"<p>NAMTECH\u2019s B.Tech programs are built on an experiential, 100% applied learning model. Instead of passive lecture-based instruction, learners spend extensive hours in living factories, collaborative robotics cells, and simulation environments solving real industry challenges.<\/p>"},{"question":"How does the industry co-creation model work?","answer":"<p>Our curricula are co-designed and co-delivered with global manufacturing giants including ArcelorMittal Nippon Steel India, Siemens, Cisco, and Schneider Electric, ensuring skills match exact operational requirements.<\/p>"},{"question":"Are scholarships available for undergraduate and master programs?","answer":"<p>Yes. The India MET Scholarship program offers up to 75% fee waivers for women candidates, GATE\/INI qualifiers, and merit-cum-means applicants across all eligible degree tracks.<\/p>"},{"question":"What is the placement record of NAMTECH graduates?","answer":"<p>NAMTECH maintains a 100% placement track record with an average CTC of \u20b912 LPA and highest offers reaching \u20b924 LPA from top multinational industrial leaders.<\/p>"}],"layout":"centered"}},{"type":"cta_band","label":null,"anchor":null,"is_visible":true,"data":{"heading":"Have Questions? Get in touch with us","body":"We partner with the best of industry, academia, and technology to co-create curriculum and align training with workforce needs. Partner with us to shape a skilled workforce for India\u2019s future.","cta_label":"Contact us","cta_url":"\/contact","tone":null}}]}}', '2026-11-18 06:43:46', '2026-11-18 06:43:46'),
(116, 'page', 13, NULL, 'snapshot', 'Initial content', '{"attributes":{"parent_id":null,"title":"Schools & Centres","slug":"schools","template":"default","excerpt":null,"sort_order":0,"meta_title":null,"meta_description":null,"og_image_id":null,"canonical_url":null,"noindex":false},"relations":{"sections":[{"type":"page_hero","label":null,"anchor":null,"is_visible":true,"data":{"eyebrow":"Schools, Centres, and Programs","title":"NAMTECH\u2019s Innovation Schools for the Future of Manufacturing","body":"Interdisciplinary, industry-led academic units designed to accelerate India\u2019s industrial transformation through experiential learning, applied research, and cutting-edge technology.","image":11,"cta_label":null,"cta_url":null,"secondary_label":null,"secondary_url":null,"statistics_group":null,"layout":null,"meta":[]}},{"type":"academics_tabs","label":null,"anchor":null,"is_visible":true,"data":{"eyebrow":"Schools, Centres, and Programs","heading":"Explore Academic Disciplines","schools_label":"Innovation Schools","centres_label":"Innovation Centres","programs_label":"Programs","schools_heading":null,"schools_body":null,"centres_heading":null,"centres_body":null,"programs_heading":null,"programs_body":null,"default_tab":"schools","featured_only":false}},{"type":"media_cards","label":null,"anchor":null,"is_visible":true,"data":{"eyebrow":"Academic Schools","heading":"MET Innovation Schools","body":"Each school converges core engineering disciplines with smart technologies, offering hands-on learning inside state-of-the-art labs.","items":[{"image":7,"logo":null,"icon":null,"tag":null,"date":null,"title":"School of Manufacturing Technologies (SoMT)","subtitle":null,"body":"Equips engineers to operate, optimize, and revolutionize modern production environments across CNC machining, lean manufacturing, IoT, and digital manufacturing.","meta":null,"link_url":"\/schools\/school-of-manufacturing-technologies"},{"image":3,"logo":null,"icon":null,"tag":null,"date":null,"ti