(129, 'page', 26, NULL, 'snapshot', 'Initial content', '{"attributes":{"parent_id":24,"title":"Consultancy","slug":"consultancy","template":"default","excerpt":null,"sort_order":0,"meta_title":null,"meta_description":null,"og_image_id":null,"canonical_url":null,"noindex":false},"relations":{"sections":[{"type":"page_hero","label":null,"anchor":null,"is_visible":true,"data":{"eyebrow":"Consultancy Services","title":"Research and Consultancy","body":null,"image":22,"cta_label":"Explore Partnerships","cta_url":"\/partnerships\/corporate","secondary_label":null,"secondary_url":null,"statistics_group":null,"layout":null,"meta":[]}},{"type":"subnav","label":null,"anchor":null,"is_visible":true,"data":{"items":[{"label":"Research @NAMTECH","url":"\/research-and-consultancy\/research"},{"label":"Consultancy Services","url":"\/research-and-consultancy\/consultancy"},{"label":"Publications","url":"\/research-and-consultancy\/publications"}]}},{"type":"card_grid","label":null,"anchor":null,"is_visible":true,"data":{"eyebrow":null,"heading":"Our Approach","body":null,"columns":"4","tone":"white","cards":[{"icon":"factory","title":"Tailored to the sector and businesses","body":null,"link_url":null},{"icon":"chart","title":"Built on deep critical evaluation","body":null,"link_url":null},{"icon":"handshake","title":"Co-created for practical implementations","body":null,"link_url":null},{"icon":"trend","title":"Long term approach","body":null,"link_url":null}],"style":"joined","cta_label":null,"cta_url":null}},{"type":"tabs","label":null,"anchor":null,"is_visible":true,"data":{"eyebrow":null,"heading":"Industrial Sectors we serve","body":null,"tabs":[{"label":"Energy & Resources","title":"Energy & Resources","body":"<p>Accelerating decarbonization, renewable energy grid integration, and circular resource management across mining, metallurgy, and utility sectors.<\/p>","image":null},{"label":"Industrials & Mobility","title":"Industrials & Mobility","body":"<p>Engineering connected factory environments, EV powertrain optimization, collaborative robotics deployment, and lean production workflows for modern manufacturing.<\/p>","image":null},{"label":"Financial Services","title":"Financial Services","body":"<p>Enabling ESG compliance frameworks, green capital financing assessments, and data-driven risk modeling for industrial assets.<\/p>","image":null},{"label":"MET Sector","title":"MET Sector","body":"<p>Pioneering manufacturing engineering &amp; technology breakthroughs, heavy industry automation, digital twins, and advanced materials engineering.<\/p>","image":null},{"label":"Health & Life Sciences","title":"Health & Life Sciences","body":"<p>Consulting on precision cleanroom automation, medical device rapid prototyping, and pharmaceutical manufacturing supply chain resilience.<\/p>","image":null},{"label":"Infrastructure & Built Environment","title":"Infrastructure & Built Environment","body":"<p>Advising on smart city infrastructure, sustainable building materials, low-carbon construction methods, and industrial estate optimization.<\/p>","image":null}],"layout":"centered","tone":"light"}},{"type":"intro","label":null,"anchor":null,"is_visible":true,"data":{"eyebrow":null,"heading":"Our Consulting Services","body":"<p>NAMTECH\u2019s Consultancy division partners with industrial enterprises to drive operational excellence, digital transformation, AI adoption, and sustainable green manufacturing practices. Leveraging state-of-the-art labs and distinguished faculty, we help organizations accelerate productivity and engineer tomorrow''s industrial capabilities.<\/p>","cta_label":null,"cta_url":null,"icon":null,"tone":null}},{"type":"contact_cards","label":null,"anchor":null,"is_visible":true,"data":{"eyebrow":null,"heading":"Leadership Team","body":null,"items":[{"region":null,"name":"Rakesh Tiwari","phone":null,"email":"rakesh.tiwari@namtech.ac"}]}},{"type":"cta_band","label":null,"anchor":null,"is_visible":true,"data":{"heading":"Have Questions? Get in touch with us","body":"We partner with the best of industry, academia, and technology to co-create curriculum and align training with workforce needs. Partner with us to shape a skilled workforce for India\u2019s future.","cta_label":"Contact us","cta_url":"\/contact","tone":null}}]}}', '2026-11-18 06:43:47', '2026-11-18 06:43:47'),
