(131, 'page', 28, NULL, 'snapshot', 'Initial content', '{"attributes":{"parent_id":null,"title":"School of Technical Education","slug":"school-of-technical-education","template":"default","excerpt":null,"sort_order":0,"meta_title":null,"meta_description":null,"og_image_id":null,"canonical_url":null,"noindex":false},"relations":{"sections":[{"type":"page_hero","label":null,"anchor":null,"is_visible":true,"data":{"eyebrow":"School of Technical Education","title":"School of Technical Education: Building Industry 4.0\u2013Ready Technologists","body":null,"image":87,"cta_label":"Explore Programs","cta_url":"#programs","secondary_label":null,"secondary_url":null,"statistics_group":null,"layout":null,"meta":[]}},{"type":"intro","label":null,"anchor":null,"is_visible":true,"data":{"eyebrow":null,"heading":"Overview","body":"<p>The School of Technical Education (STE) is dedicated to preparing technician-engineers for the demanding realities of Industry 4.0. Through intensive hands-on curricula, simulation labs, and industry co-delivered modules, STE transforms diploma holders and technical learners into world-class automation and robotics technologists.<\/p>","cta_label":null,"cta_url":null,"icon":"cap","tone":null}},{"type":"card_grid","label":null,"anchor":null,"is_visible":true,"data":{"eyebrow":"Talking Points","heading":"Transforming India\u2019s technical workforce","body":null,"columns":"4","tone":"white","cards":[{"icon":"people","title":"Transforming India\u2019s Technician Workforce","body":null,"link_url":null},{"icon":"robot","title":"Experiential Learning Through Advanced Technology","body":null,"link_url":null},{"icon":"factory","title":"Industry-integrated, applied learning models","body":null,"link_url":null},{"icon":"globe","title":"Scaling Skills Access Across India","body":null,"link_url":null}],"style":"joined","cta_label":null,"cta_url":null}},{"type":"programs_list","label":null,"anchor":"programs","is_visible":true,"data":{"eyebrow":null,"heading":"Explore Programs @ School of Technical Education","level":"technical","school":null}},{"type":"video_feature","label":null,"anchor":null,"is_visible":true,"data":{"layout":"overlay","eyebrow":null,"heading":"Here\u2019s What the Dean Says","body":"At the School of Technical Education, our focus is squarely on transforming India\u2019s technical workforce through immersive, shop-floor learning. We don\u2019t just teach theory\u2014we empower technicians and engineers with the exact hands-on skills global manufacturers are looking for.","name":"Mr. Sandeep Achantani","role":"Director, School of Technical Education","image":70,"video_url":null}},{"type":"people","label":null,"anchor":null,"is_visible":true,"data":{"eyebrow":"Faculty","heading":"Featured Faculty","body":null,"members":[],"school":null,"limit":8,"cta_label":null,"cta_url":null,"layout":"carousel","tone":null}},{"type":"media_cards","label":null,"anchor":null,"is_visible":true,"data":{"eyebrow":null,"heading":"Labs & Infrastructure","body":null,"items":[{"image":35,"logo":null,"icon":null,"tag":null,"date":null,"title":"Advanced Manufacturing Labs","subtitle":null,"body":null,"meta":null,"link_url":null},{"image":32,"logo":null,"icon":null,"tag":null,"date":null,"title":"Digital Learning Centers","subtitle":null,"body":null,"meta":null,"link_url":null},{"image":84,"logo":null,"icon":null,"tag":null,"date":null,"title":"Water Stewardship Lab","subtitle":null,"body":null,"meta":null,"link_url":null}],"layout":"tall","tone":null,"cta_label":"View All","cta_url":"\/academics\/labs-and-infrastructure","footer_label":null,"footer_url":null,"card_link_label":null}},{"type":"partners_showcase","label":null,"anchor":null,"is_visible":true,"data":{"eyebrow":"Industry & Academic","heading":"Partnerships at NAMTECH","body":null,"cta_label":null,"cta_url":null,"cta2_label":null,"cta2_url":null,"cta3_label":null,"cta3_url":null,"category":null,"show_stories":true,"stories_cta_label":null,"stories_cta_url":null}},{"type":"events_carousel","label":null,"anchor":null,"is_visible":true,"data":{"eyebrow":null,"heading":"Upcoming Events","body":"Join us at our upcoming events as we collaborate, learn, and drive meaningful change for a sustainable future.","cta_label":"View All Events","cta_url":"\/events","tone":null,"category":null,"school":null}},{"type":"news_carousel","label":null,"anchor":null,"is_visible":true,"data":{"heading":"News & Insights","post_type":"news","limit":8,"cta_label":"View all insights","cta_url":"\/media"}},{"type":"contact_band","label":null,"anchor":null,"is_visible":true,"data":{"heading":"Connect with our Team","body":null,"cta_label":"Contact us","cta_url":"\/contact","contacts_label":"For More Information","contacts":[{"name":"Dr. Ravi Shankar","role":"Associate Director","email":"dvravi.shankar@namtech.ac"},{"name":"Vibha Desai","role":"Associate Director","email":"vibha.desai@namtech.ac"}]}}]}}', '2026-11-18 06:43:47', '2026-11-18 06:43:47'),
(132, 'page', 29, NULL, 'snapshot', 'Initial content', '{"attributes":{"parent_id":28,"title":"Outreach","slug":"outreach","template":"default","excerpt":null,"sort_order":0,"meta_title":null,"meta_description":null,"og_image_id":null,"canonical_url":null,"noindex":false},"relations":{"sections":[{"type":"page_hero","label":null,"anchor":null,"is_visible":true,"data":{"eyebrow":"Outreach","title":"The Blueprint for India\u2019s ITI Force","body":null,"image":81,"cta_label":null,"cta_url":null,"secondary_label":null,"secondary_url":null,"statistics_group":null,"layout":null,"meta":[]}},{"type":"image_text","label":null,"anchor":null,"is_visible":true,"data":{"eyebrow":null,"heading":"Our Vision","body":"<p>To empower 3 million youth with advancement in the MET sector and position India as a global hub for manufacturing excellence.<\/p>","image":105,"image_position":"left","cta_label":null,"cta_url":null,"layout":"staggered","tone":null}},{"type":"image_text","label":null,"anchor":null,"is_visible":true,"data":{"eyebrow":null,"heading":"Our Mission","body":"<p>To empower 3 million youth with advancement in the MET sector and position India as a global hub for manufacturing excellence.<\/p>","image":106,"image_position":"right","cta_label":null,"cta_url":null,"layout":"staggered","tone":null}},{"type":"accordion_media","label":null,"anchor":null,"is_visible":true,"data":{"eyebrow":null,"heading":"Current Gaps in Tech-Vocational Education","items":[{"title":"A growing skills gap","text":"Vocational education focuses on routine skills, but Industry 4.0 requires more. Digital systems and collaboration are now essential. Without updated training, many students risk being left behind.","image":47},{"title":"Infrastructure hasn\u2019t kept up","text":"Most ITIs aren\u2019t designed for advanced manufacturing. They lack smart labs and real tools, limiting hands-on learning and exposure to modern production.","image":61},{"title":"From operators to future leaders","text":"Many students are trained to operate machines. Tomorrow\u2019s industry needs technicians who can adapt and lead on the shop floor.","image":87}]}},{"type":"card_tabs","label":null,"anchor":null,"is_visible":true,"data":{"eyebrow":null,"heading":"NAMTECH\u2019s Hubs and Spokes Model","body":null,"cta_label":"Read Case Study","cta_url":"\/impact\/stories","tone":"lavender","tabs":[{"label":"Overview","cards":[{"icon":"building","title":"Infrastructure of the hubs","text":null},{"icon":"globe","title":"Spokes\u2019 ITI Network","text":null},{"icon":"code","title":"Learning Delivery Model","text":null},{"icon":"trend","title":"Student Impact & Career Pathways","text":null}]},{"label":"Infrastructure","cards":[{"icon":"building","title":"State-of-the-Art Training Hubs","text":"Equipped with mobile training units, specialized robotic work cells, and cloud-connected phygital simulation stations deployed across regional centers."},{"icon":"gear","title":"Mobile Campuses & Labs on Wheels","text":"Bringing high-technology manufacturing equipment and certified training directly to remote ITIs and technical institutions."}]},{"label":"Locations","cards":[{"icon":"pin","title":"Key Industrial Clusters","text":"Expanding across major manufacturing corridors in Gujarat, Maharashtra, Tamil Nadu, Andhra Pradesh, and Northern industrial hubs."},{"icon":"globe","title":"Pan-India Reach","text":"Partnering with state technical boards and central agencies to scale reach to over 500 partner polytechnics and ITIs."}]},{"label":"Impact Stories","cards":[{"icon":"trend","title":"Social Upliftment & Employability","text":"Empowering youth from tier-2 and tier-3 towns with immediate placement pathways in high-growth automation roles."},{"icon":"award","title":"Career Acceleration","text":"Over 90% of certified technicians report a 2x increase in starting salaries upon completing the phygital skill pathways."}]}]}},{"type":"numbered_list","label":null,"anchor":null,"is_visible":true,"data":{"eyebrow":null,"heading":"NAMTECH\u2019s Scaling Strategies","body":"NAMTECH is scaling its Hub-and-Spoke Model by partnering with Central & State Departments, Government ITIs and institutions for large-scale program implementation and with Industry to upskill their existing workforce.","list_label":"Our expansion focuses on:","items":[{"text":"Collaborating with Central & State Government for effective program implementation across technical institutions"},{"text":"Partnering with Industry for customized upskilling, apprenticeships, and placements"},{"text":"Replicating proven infrastructure and phygital learning solutions"},{"text":"Strengthening faculty development and industry-aligned curriculum"}],"footer":"Through this collaborative approach, NAMTECH aims to empower nearly 3 million learners across India with future-ready technical skills and sustainable employment opportunities."}},{"type":"card_grid","label":null,"anchor":null,"is_visible":true,"data":{"eyebrow":"Partnerships Opportunities","heading":"Support & Partnership Opportunities","body":"NAMTECH School of Technical Education invites industry leaders, corporates, and CSR foundations to partner with us in transforming technical education and empowering underprivileged youth across India. We offer multiple meaningful collaboration models that deliver measurable social impact while providing strategic value to your organization.","columns":"3","tone":"white","cards":[{"icon":"building","title":"Infrastructure & labs Sponsorship","body":"Support the development of advanced labs, smart classrooms, EV training facilities, and Lab on Wheels to provide students with industry-relevant, hands-on learning experiences.","link_url":null},{"icon":"code","title":"Phygital Training Program","body":"Sponsor student cohorts through NAMTECH\u2019s Phygital Learning Program, enabling access to digital learning platforms, simulations, and practical training.","link_url":null},{"icon":"people","title":"Serve India Fellowship","body":"Fund fellowships for professionals working with government ITIs to mentor faculty, strengthen institutions, and improve student learning outcomes.","link_url":null},{"icon":"graduation","title":"Skill Development & Employability Programs","body":"Support specialized training, industry immersion, placement readiness initiatives, and soft skills programs that prepare students for successful careers.","link_url":null},{"icon":"handshake","title":"Adopt-an-ITI \/ Hub & Spoke Model","body":"Partner with one or more ITIs to strengthen infrastructure, faculty capability, and student outcomes through NAMTECH\u2019s Hub & Spoke model.","link_url":null},{"icon":"leaf","title":"Corporate CSR Projects & Impact Funding","body":"Collaborate on customized CSR initiatives with measurable outcomes, transparent reporting, and long-term community impact.","link_url":null}],"style":"outlined","cta_label":null,"cta_url":null}},{"type":"tabs_media","label":null,"anchor":null,"is_visible":true,"data":{"eyebrow":null,"heading":"Partnership Models","body":"Through the innovative Hub-and-Spoke model, the program proudly supports an impressive 1,800 ITI learners each year. This initiative not only connects them to essential industry-ready skills but also provides invaluable mentorship and diverse career pathways.","tone":null,"tabs":[{"label":"Infrastructure & labs","image":35,"title":"Infrastructure & labs Sponsorship","text":"Support the development of advanced labs, smart classrooms, EV training facilities, and Lab on Wheels to provide students with industry-relevant, hands-on learning experiences.","points":[],"links":[]},{"label":"Phygital Training Program","image":32,"title":"Phygital Training Program","text":"Sponsor student cohorts through NAMTECH\u2019s Phygital Learning Program, enabling access to digital learning platforms, simulations, and practical training.","points":[],"links":[]},{"label":"Serve India Fellowship","image":100,"title":"Serve India Fellowship","text":"Fund fellowships for professionals working with government ITIs to mentor faculty, strengthen institutions, and improve student learning outcomes.","points":[],"links":[]},{"label":"Skill Development","image":47,"title":"Skill Development & Employability Programs","text":"Support specialized training, industry immersion, placement readiness initiatives, and soft skills programs that prepare students for successful careers.","points":[],"links":[]},{"label":"Hub & Spoke Model","image":92,"title":"Adopt-an-ITI \/ Hub & Spoke Model","text":"Partner with one or more ITIs to strengthen infrastructure, faculty capability, and student outcomes through NAMTECH\u2019s Hub & Spoke model.","points":[],"links":[]},{"label":"CSR & Impact","image":59,"title":"Corporate CSR Projects & Impact Funding","text":"Collaborate on customized CSR initiatives with measurable outcomes, transparent reporting, and long-term community impact.","points":[],"links":[]}]}},{"type":"feature_list","label":null,"anchor":null,"is_visible":true,"data":{"eyebrow":null,"heading":"Why Partner with NAMTECH?","body":null,"tabs":[{"label":null,"items":[{"icon":"people","text":"Industry-ready Talent Pipeline"},{"icon":"handshake","text":"Employee Engagement"},{"icon":"trend","text":"High-impact Social Outcomes"},{"icon":"sparkle","text":"Brand Visibility & Recognition"},{"icon":"document","text":"CSR & ESG Reporting"}]}]}},{"type":"contact_band","label":null,"anchor":null,"is_visible":true,"data":{"heading":"Connect with our Team","body":null,"cta_label":"Contact us","cta_url":"\/contact","contacts_label":"For More Information","contacts":[{"name":"Dr. Ravi Shankar","role":"Associate Director","email":"dvravi.shankar@namtech.ac"},{"name":"Vibha Desai","role":"Associate Director","email":"vibha.desai@namtech.ac"}]}}]}}', '2026-11-18 06:43:48', '2026-11-18 06:43:48'),
(133, 'page', 30, NULL, 'snapshot', 'Initial content', '{"attributes":{"parent_id":28,"title":"International Professional Technologist Program (iPTP)","slug":"iptp","template":"default","excerpt":null,"sort_order":0,"meta_title":null,"meta_description":null,"og_image_id":null,"canonical_url":null,"noindex":false},"relations":{"sections":[{"type":"page_hero","label":null,"anchor":null,"is_visible":true,"data":{"eyebrow":"School of Technical Education","title":"International Professional Technologist Program (iPTP)","body":"An intensive 1-year immersion program bridging technical diplomas and high-demand Industry 4.0 shop-floor careers, co-designed with ITE Education Services (ITEES), Singapore.","image":87,"cta_label":"Apply for iPTP","cta_url":"\/admissions#enquire","secondary_label":null,"secondary_url":null,"statistics_group":null,"layout":null,"meta":[]}},{"type":"stat_cards","label":null,"anchor":null,"is_visible":true,"data":{"eyebrow":"Outcomes","heading":"Why Choose iPTP?","body":null,"tone":"lavender","items":[{"icon":"check","value":"100%","label":"Placement Track Record","text":null},{"icon":"people","value":"500+","label":"Certified Technologists","text":null},{"icon":"globe","value":"ITEES","label":"Singapore Co-Certification","text":null},{"icon":"rupee","value":"2.5x","label":"Average Salary Uplift","text":null}]}},{"type":"intro","label":null,"anchor":null,"is_visible":true,"data":{"eyebrow":null,"heading":"Program Overview","body":"<p>The International Professional Technologist Program (iPTP) transforms ITI and polytechnic diploma holders into high-productivity shop-floor engineers. Through 1,200+ hours of hands-on training on industrial-grade CNC machines, mechatronics stations, and collaborative robotics cells, graduates enter the workforce Day-Zero Ready.<\/p>","cta_label":null,"cta_url":null,"icon":"cap","tone":null}},{"type":"timeline","label":null,"anchor":null,"is_visible":true,"data":{"eyebrow":"Curriculum Pathway","heading":"Program Structure","body":"Four progressive terms of rigorous technical training and industry immersion.","items":[{"year":"Term 1","title":"Foundations of Advanced Manufacturing","text":"Core mechanical, electrical, and pneumatic systems, safety standards, and engineering precision.","image":null},{"year":"Term 2","title":"Automation, CNC & PLC Systems","text":"Programming and operation of modern industrial automation rigs, PLC ladders, and CNC machining centers.","image":null},{"year":"Term 3","title":"Robotics & Industry 4.0 Integration","text":"Cobot deployment, sensor integration, IoT telemetry, and digital maintenance practices.","image":null},{"year":"Term 4","title":"Paid Industry Internship & Capstone","text":"Full-time immersion inside top partner manufacturing facilities with guaranteed placement transition.","image":null}]}},{"type":"eligibility","label":null,"anchor":null,"is_visible":true,"data":{"eyebrow":"Admission","heading":"Eligibility & Selection","body":null,"criteria":[{"text":"Diploma in Mechanical, Electrical, Mechatronics, or Automobile Engineering, or ITI certificate."},{"text":"Minimum 55% marks in qualifying technical examination."},{"text":"Candidate must pass NAMTECH Technical Aptitude & Practical Hands-on Assessment."}],"list_heading":null,"items":[]}},{"type":"faq","label":null,"anchor":null,"is_visible":true,"data":{"heading":"Frequently Asked Questions","body":null,"items":[{"question":"Who is eligible for the iPTP program?","answer":"<p>Candidates holding a diploma in engineering or ITI certificate in relevant mechanical, electrical, or automation disciplines are eligible.<\/p>"},{"question":"Is placement guaranteed after completing iPTP?","answer":"<p>NAMTECH provides comprehensive placement support, with a 100% placement track record across our previous cohorts in leading manufacturing plants.<\/p>"},{"question":"What certificate do graduates receive?","answer":"<p>Graduates receive a joint certification from NAMTECH and ITE Education Services (ITEES), Singapore.<\/p>"}],"layout":"centered"}},{"type":"cta_band","label":null,"anchor":null,"is_visible":true,"data":{"heading":"Have Questions? Get in touch with us","body":"We partner with the best of industry, academia, and technology to co-create curriculum and align training with workforce needs. Partner with us to shape a skilled workforce for India\u2019s future.","cta_label":"Contact us","cta_url":"\/contact","tone":null}}]}}', '2026-11-18 06:43:48', '2026-11-18 06:43:48'),
