(147, 'page', 44, NULL, 'snapshot', 'Initial content', '{"attributes":{"parent_id":null,"title":"Privacy Policy","slug":"privacy-policy","template":"legal","excerpt":null,"sort_order":0,"meta_title":null,"meta_description":null,"og_image_id":null,"canonical_url":null,"noindex":false},"relations":{"sections":[{"type":"rich_text","label":null,"anchor":null,"is_visible":true,"data":{"heading":"Privacy Policy","body":"<p>NAMTECH is committed to protecting your privacy. This Privacy Policy explains how we collect, use, disclose, and safeguard your personal information when you visit our website or interact with our educational services.<\/p><h3>Information We Collect<\/h3><p>We may collect personal details such as your name, email address, phone number, academic records, and resume when you submit an enquiry, apply for admissions, register for events, or subscribe to our newsletters.<\/p><h3>How We Use Your Information<\/h3><p>We use your information to process admissions applications, respond to inquiries, send administrative updates, and provide academic notifications. We do not sell or rent your personal data to third parties.<\/p><h3>Data Security<\/h3><p>We implement strict administrative, technical, and physical security measures to safeguard your personal data against unauthorized access, disclosure, or misuse.<\/p>","toc":false,"width":null}}]}}', '2026-11-18 06:43:49', '2026-11-18 06:43:49'),
(148, 'page', 45, NULL, 'snapshot', 'Initial content', '{"attributes":{"parent_id":null,"title":"Terms of Use","slug":"terms-of-use","template":"legal","excerpt":null,"sort_order":0,"meta_title":null,"meta_description":null,"og_image_id":null,"canonical_url":null,"noindex":false},"relations":{"sections":[{"type":"rich_text","label":null,"anchor":null,"is_visible":true,"data":{"heading":"Terms of Use","body":"<p>Welcome to the official website of NAMTECH. By accessing or using this website, you agree to be bound by these Terms of Use and all applicable laws and regulations.<\/p><h3>Intellectual Property<\/h3><p>All content, branding, trademarks, logos, and materials published on this website are the property of NAMTECH or its academic and industry partners. You may not reproduce, distribute, or modify any materials without prior written consent.<\/p><h3>User Conduct<\/h3><p>You agree to use the site only for lawful educational purposes and in a manner that does not infringe on the rights of others or restrict their use and enjoyment of the website.<\/p>","toc":false,"width":null}}]}}', '2026-11-18 06:43:49', '2026-11-18 06:43:49'),
(149, 'page', 46, NULL, 'snapshot', 'Initial content', '{"attributes":{"parent_id":null,"title":"Sitemap","slug":"sitemap","template":"legal","excerpt":null,"sort_order":0,"meta_title":null,"meta_description":null,"og_image_id":null,"canonical_url":null,"noindex":false},"relations":{"sections":[{"type":"rich_text","label":null,"anchor":null,"is_visible":true,"data":{"heading":"Sitemap","body":"<p>Browse the main sections of the website using the links below.<\/p><ul><li><a href=\"\/about\">About NAMTECH<\/a><\/li><li><a href=\"\/academics\">Academics<\/a><\/li><li><a href=\"\/programs\">Programs<\/a><\/li><li><a href=\"\/schools\">Schools &amp; Centres<\/a><\/li><li><a href=\"\/admissions\">Admissions<\/a><\/li><li><a href=\"\/faculty\">Faculty<\/a><\/li><li><a href=\"\/partnerships\">Partnerships<\/a><\/li><li><a href=\"\/research-and-consultancy\">Research &amp; Consultancy<\/a><\/li><li><a href=\"\/school-of-technical-education\">School of Technical Education<\/a><\/li><li><a href=\"\/impact\">Impact<\/a><\/li><li><a href=\"\/placements\">Placements<\/a><\/li><li><a href=\"\/life-at-namtech\">Life @ NAMTECH<\/a><\/li><li><a href=\"\/campus\">Campus<\/a><\/li><li><a href=\"\/media\">Media<\/a><\/li><li><a href=\"\/events\">Events<\/a><\/li><li><a href=\"\/blogs\">Blogs<\/a><\/li><li><a href=\"\/careers\">Careers<\/a><\/li><li><a href=\"\/contact\">Contact<\/a><\/li><\/ul>","toc":false,"width":null}}]}}', '2026-11-18 06:43:49', '2026-11-18 06:43:49');
