INSERT INTO `announcements` VALUES
(1, 'New', 'Deemed-to-be University - LOI Received', NULL, 1, NULL, NULL, 0, '2026-11-18 06:43:36', '2026-11-18 06:43:36');
INSERT INTO `schools` VALUES
(1, 'School of Manufacturing Technologies', 'school-of-manufacturing-technologies', NULL, 'NAMTECH empowers the next-generation of engineers to build, code, and operate the intelligent, connected factories of tomorrow.', NULL, 7, 0, 'published', NULL, '2026-11-18 06:42:36', NULL, NULL, NULL, '2026-11-18 06:43:36', '2026-11-18 06:43:43', NULL, NULL, NULL, NULL, 0, NULL),
(2, 'School of Manufacturing Design & AI', 'school-of-manufacturing-design-ai', NULL, 'The School of Manufacturing Design & AI focuses on the convergence of design, engineering, computation, and artificial intelligence to shape the next generation of products, systems, and industrial innovation. Through an industry-first and experiential approach, the school prepares learners to work at the intersection of technology and human needs, translating emerging capabilities into solutions with real-world impact.', NULL, 3, 1, 'published', NULL, '2026-11-18 06:42:36', NULL, NULL, NULL, '2026-11-18 06:43:36', '2026-11-18 06:43:36', NULL, NULL, NULL, NULL, 0, NULL),
(3, 'School of Robotics', 'school-of-robotics', NULL, 'The School of Robotics prepares the next generation of professionals to design, develop, and deploy intelligent machines and autonomous systems that will transform industry and society. By combining engineering, emerging technologies, hands-on experimentation, and real-world application, the school equips learners to build the future of human–machine collaboration and intelligent automation.', NULL, 10, 2, 'published', NULL, '2026-11-18 06:42:36', NULL, NULL, NULL, '2026-11-18 06:43:36', '2026-11-18 06:43:36', NULL, NULL, NULL, NULL, 0, NULL),
(4, 'School of Sustainability', 'school-of-sustainability', NULL, 'NAMTECH’s School of Sustainability prepares the next generation to engineer a cleaner, more resilient, and resource-efficient industrial future.', NULL, 11, 3, 'published', NULL, '2026-11-18 06:42:36', NULL, NULL, NULL, '2026-11-18 06:43:36', '2026-11-18 06:43:43', NULL, NULL, NULL, NULL, 0, NULL),
(5, 'School of Technical Education', 'school-of-technical-education', NULL, 'The School of Technical Education enables ITI and diploma-qualified learners to build on their technical foundations and progress into higher levels of technological capability. Through practical, industry-oriented learning and curriculum designed in collaboration with ITE Education Services, Singapore, the School creates pathways for skilled technicians to evolve into confident, industry-ready technologists capable of contributing to the future of modern industry.', NULL, 21, 4, 'published', NULL, '2026-11-18 06:42:36', NULL, NULL, NULL, '2026-11-18 06:43:36', '2026-11-18 06:43:36', NULL, NULL, NULL, NULL, 0, NULL);
INSERT INTO `centres` VALUES
(1, NULL, 'Center of Excellence in Automotive Engineering', 'coe-in-automotive-engineering', NULL, 'The Center of Excellence in Automotive Engineering advances the future of mobility by bringing together engineering, technology, design, and industry expertise. The Center enables learners and industry to explore emerging opportunities, address real-world mobility challenges, and develop solutions that contribute to a more intelligent, connected, and sustainable automotive ecosystem.', NULL, 2, 0, 'published', NULL, '2026-11-18 06:42:36', NULL, NULL, NULL, '2026-11-18 06:43:36', '2026-11-18 06:43:36', NULL, NULL, NULL, NULL, 0, NULL),
(2, NULL, 'Center of Advanced Computing & AI', 'centre-of-advanced-computing-ai', NULL, 'The Center for Advanced Computing & AI focuses on harnessing computing and artificial intelligence to address complex challenges across industry and society. By connecting advanced technology with real-world application, the Center enables learners, researchers, and industry to develop intelligent solutions and unlock new possibilities for technology-led transformation.', NULL, 21, 1, 'published', NULL, '2026-11-18 06:42:37', NULL, NULL, NULL, '2026-11-18 06:43:36', '2026-11-18 06:43:37', NULL, NULL, NULL, NULL, 0, NULL),
(3, NULL, 'Center of Management Studies', 'center-of-management', NULL, 'The Center of Management Studies helps NAMTECH graduates develop the strategic, business, and managerial capabilities required to navigate an increasingly technology-driven economy. By bringing together design thinking, strategic intelligence, and business & professional communication, the Center prepares professionals to bridge technology and enterprise, drive transformation, and drive organizational value.', NULL, 22, 2, 'published', NULL, '2026-11-18 06:42:37', NULL, NULL, NULL, '2026-11-18 06:43:37', '2026-11-18 06:43:37', NULL, NULL, NULL, NULL, 0, NULL),
(4, NULL, 'Experiential Learning Center for Sustainable Energy & Circularity', 'experiential-learning-center-for-sustainable-energy-circularity', NULL, 'Co-created with IIT Roorkee and supported by NTPC, The Experiential Learning Center for Sustainable Energy & Circularity (ELC:SEC) focuses on enabling the transition towards more sustainable, resource-efficient, and resilient industrial systems. The Center addresses the interconnected challenges of energy, resources, and industrial growth through convergence of technology, innovation, and systems thinking, for a low-carbon and circular future.', NULL, 20, 3, 'published', NULL, '2026-11-18 06:42:37', NULL, NULL, NULL, '2026-11-18 06:43:37', '2026-11-18 06:43:37', NULL, NULL, NULL, NULL, 0, NULL);
INSERT INTO `programs` VALUES
(1, 1, 'B.Tech. Mechanical Engineering (Smart Manufacturing)', 'btech-mechanical-engineering-smart-manufacturing', 'undergraduate', 'B.Tech', 'A forward-looking undergraduate degree integrating core mechanical engineering with cyber-physical systems, additive manufacturing, industrial IoT, and digital twin simulation to engineer next-generation smart factories.', NULL, 'On-Campus', 'Ahmedabad', 'August, 2026', '2026-07-30 00:00:00', '4 years', '8 Semesters', '/admissions#enquire', 7, 1, 0, 'published', NULL, '2026-11-18 06:42:37', NULL, NULL, NULL, '2026-11-18 06:43:37', '2026-11-18 06:43:37', NULL, NULL, NULL, NULL, 0, NULL, NULL),
(2, 1, 'B.Tech. Mechanical Engineering (Automotive)', 'btech-mechanical-engineering-automotive', 'undergraduate', 'B.Tech', 'Focuses on modern vehicle architecture, powertrain electrification, autonomous driving dynamics, and advanced materials engineering designed in collaboration with leading automotive OEMs.', NULL, 'On-Campus', 'Ahmedabad', 'August, 2026', '2026-07-30 00:00:00', '4 years', '8 Semesters', '/admissions#enquire', 3, 1, 1, 'published', NULL, '2026-11-18 06:42:37', NULL, NULL, NULL, '2026-11-18 06:43:37', '2026-11-18 06:43:37', NULL, NULL, NULL, NULL, 0, NULL, NULL),
(3, 3, 'B.Tech. Robotics & AI', 'btech-robotics-and-ai', 'undergraduate', 'B.Tech', 'Brings together mechanical kinematics, sensor fusion, computer vision, and machine learning to build autonomous robotic systems, collaborative cobots, and intelligent automation platforms.', NULL, 'On-Campus', 'Ahmedabad', 'August, 2026', '2026-07-30 00:00:00', '4 years', '8 Semesters', '/admissions#enquire', 11, 1, 2, 'published', NULL, '2026-11-18 06:42:37', NULL, NULL, NULL, '2026-11-18 06:43:37', '2026-11-18 06:43:37', NULL, NULL, NULL, NULL, 0, NULL, NULL),
(4, 4, 'B.Tech. Smart & Sustainable Energy', 'btech-smart-and-sustainable-energy', 'undergraduate', 'B.Tech', 'Prepares engineers to pioneer clean energy transitions, renewable grid integration, hydrogen storage systems, and circular manufacturing frameworks to achieve net-zero industrial targets.', NULL, 'On-Campus', 'Ahmedabad', 'August, 2026', '2026-07-30 00:00:00', '4 years', '8 Semesters', '/admissions#enquire', 2, 1, 3, 'published', NULL, '2026-11-18 06:42:37', NULL, NULL, NULL, '2026-11-18 06:43:37', '2026-11-18 06:43:37', NULL, NULL, NULL, NULL, 0, NULL, NULL),
(5, 2, 'B.Tech. Computer Science Engineering', 'btech-computer-science-engineering', 'undergraduate', 'B.Tech', 'Focuses on high-performance computing, distributed cloud architectures, industrial cybersecurity, and data-driven systems powering mission-critical manufacturing and enterprise environments.', NULL, 'On-Campus', 'Ahmedabad', 'August, 2026', '2026-07-30 00:00:00', '4 years', '8 Semesters', '/admissions#enquire', 21, 1, 4, 'published', NULL, '2026-11-18 06:42:37', NULL, NULL, NULL, '2026-11-18 06:43:37', '2026-11-18 06:43:37', NULL, NULL, NULL, NULL, 0, NULL, NULL),
(6, 1, 'B.Tech. Electronics Engineering (Semiconductor Technology)', 'btech-electronics-engineering-semiconductor-technology', 'undergraduate', 'B.Tech', 'Equips engineers with expertise in VLSI design, semiconductor fabrication processes, cleanroom operations, and microelectronics packaging aligned with India’s national semiconductor mission.', NULL, 'On-Campus', 'Ahmedabad', 'August, 2026', '2026-07-30 00:00:00', '4 years', '8 Semesters', '/admissions#enquire', 20, 1, 5, 'published', NULL, '2026-11-18 06:42:37', NULL, NULL, NULL, '2026-11-18 06:43:37', '2026-11-18 06:43:37', NULL, NULL, NULL, NULL, 0, NULL, NULL),
(7, 1, 'B.Tech. Electronics Engineering (Space Technology)', 'btech-electronics-engineering-space-technology', 'undergraduate', 'B.Tech', 'Explores satellite payload engineering, telemetry communications, high-reliability aerospace avionics, and space-grade materials for emerging commercial space missions.', NULL, 'On-Campus', 'Ahmedabad', 'August, 2026', '2026-07-30 00:00:00', '4 years', '8 Semesters', '/admissions#enquire', 7, 1, 6, 'published', NULL, '2026-11-18 06:42:37', NULL, NULL, NULL, '2026-11-18 06:43:37', '2026-11-18 06:43:37', NULL, NULL, NULL, NULL, 0, NULL, NULL),
(8, 1, 'Master in Smart Manufacturing Technology & Management', 'master-in-smart-manufacturing-technology-and-management', 'postgraduate', 'Master', 'Develop advanced expertise in smart manufacturing, Industry 4.0 and 5.0, intelligent automation, digital production systems, and technology management to lead the transformation of modern manufacturing enterprises.', '<p>The Master Program in Smart Manufacturing Technology and Management is a two-year residential program to build industry-ready techno-managers for Manufacturing Engineering Technology (MET) sectors. Offered in collaboration with Technical University of Munich (TUM Asia, Singapore) and incorporating MIT’s landmark 2.008 Design and Manufacturing II framework customized for NAMTECH (2.008 N), the curriculum delivers deep, hands-on expertise in additive manufacturing, mechatronics, industrial robotics, smart automation and digital twin ecosystems, complemented by executive-level management training.</p><p>Using globally benchmarked, WorldSkills-aligned platforms, students solve high-impact and live industrial challenges with guidance from world-class faculty and global industry leaders. Students graduate fully prepared to build, integrate and lead the manufacturing transformation of India.</p>', 'Full-time, residential', 'Ahmedabad', 'August 2027', NULL, '24 Months', '4 Semesters', '/admissions#enquire', 3, 1, 7, 'published', NULL, '2026-11-18 06:42:37', NULL, NULL, NULL, '2026-11-18 06:43:37', '2026-11-18 06:43:51', NULL, NULL, NULL, NULL, 0, NULL, '{"brochure":{"file":null},"snapshot":{"start_date":null,"deadline":null,"eligibility":"B.E.\/ B.Tech. across engineering branches","eligibility_note":"Minimum score of 60% in 10th, 12th & graduation"},"why_choose":{"heading":null,"items":[{"icon":"lightbulb","title":"Future-Ready Techno-Managerial Focus","text":"NAMTECH fuses cutting-edge engineering and smart factory technology with executive leadership, data-driven technologies and sustainability, shaping graduates for next-generation careers."},{"icon":"gear","title":"Built on MIT\u2019s Hands-On Philosophy","text":"The curriculum integrates MIT\u2019s gold-standard 2.008 Design and Manufacturing framework customized for NAMTECH (2.008N), establishing a true \u201cexperiential\u201d foundation essential for Industry 4.0."},{"icon":"globe","title":"Learn from Global Experts","text":"Learn directly from distinguished international faculty from Technical University of Munich, Asia (TUM Asia), Carnegie Mellon University and other leading universities alongside industry experts from Siemens, Schneider Electric, Cisco, Festo and L&T."},{"icon":"trend","title":"Proven Placement Track Record","text":"100% placement record for eligible students across top-tier recruiters including AM\/NS India, Micron, Festo and Schneider Electric among others."},{"icon":"rupee","title":"Scholarships and Financial Support","text":"Access merit-based scholarships of up to 100% on tuition, plus education loan support from leading banks, making our advanced programs accessible to aspiring engineers."},{"icon":"handshake","title":"Co-Designed with Industry Giants","text":"Developed and delivered collaboratively with industry leaders and academic experts to ensure that graduates are industry-ready from day one."}]},"class_profile":{"heading":"Class of 2026","intro":null,"image":null,"mix_label":null,"mix":[],"stats":[{"icon":"trend","value":"96%","text":"Placement Rate"},{"icon":"rupee","value":"\u20b912L","text":"Average Salary"},{"icon":"handshake","value":"14+","text":"Hiring Partners"},{"icon":"award","value":"100%","text":"Experiential Learning"}]},"partners":{"heading":"Program Partners","items":[{"image":null,"tag":"Academic Partner","date":null,"logo":null,"title":"Technical University of Munich (TUM Asia, Singapore)","text":"A globally top-ranked technical university, TUM Asia has co-designed the curriculum with NAMTECH and offers deep academic collaboration, embedding world-class German technical education standards into NAMTECH.","link_url":null},{"image":null,"tag":"Academic Partner","date":null,"logo":null,"title":"Department of Mechanical Engineering, Massachusetts Institute of Technology (USA)","text":"Blending rigorous theory with intensive hands-on making, MIT\u2019s Department of Mechanical Engineering provides the foundational 2.008 Design & Manufacturing II framework, customized for NAMTECH (2.008N) that guides NAMTECH\u2019s \u201cexperiential learning\u201d ethos.","link_url":null},{"image":null,"tag":"Academic Partner","date":null,"logo":null,"title":"Carnegie Mellon University (USA)","text":"Carnegie Mellon University, an internationally renowned research institution, enables faculty exchange and advanced research pedagogy transfer to NAMTECH.","link_url":null},{"image":null,"tag":"Academic Partner","date":null,"logo":null,"title":"Purdue University Northwest (USA)","text":"Purdue University Northwest offers an exclusive 1+1 pathway to a Master of Science in Mechanical Engineering for eligible students, unlocking global academic acceleration.","link_url":null},{"image":null,"tag":"Industry and Technology Partners","date":null,"logo":null,"title":"Siemens, ABB, FANUC, Rockwell Automation, Festo, Schneider Electric, Cisco and Analog Devices","text":"Global automation and technology leaders supporting Industry 4.0 laboratories and the curriculum with equipment, platforms, and training.","link_url":null},{"image":null,"tag":"Industry Partners","date":null,"logo":null,"title":"AMNS India and L&T Heavy Engineering","text":"Anchor industry partners providing industrial mentorship, live manufacturing projects and recruitment.","link_url":null}]},"structure":{"heading":"Program Structure","intro":"The Master Program in Smart Manufacturing Technology and Management spans four 16-week semesters, equipping learners with technical mastery, hands-on laboratory experience, live industry capstone projects and management expertise required to power the future of smart manufacturing.","semesters":[{"title":"Semester 1","columns":null,"courses":"Precision Engineering and Manufacturing Processes\nMachine Systems and Industrial Mechatronics\nFoundations of Smart Manufacturing Systems\nIndustrial Automation\nManagement: Operational Excellence through Lean Principles\nManagement: Environment, Health, Safety and Sustainability (EHSS)\nProfessional Skills: Communication and Leadership Skills"},{"title":"Semester 2","columns":null,"courses":"Design for Manufacturing (2.008N) 1 & 2\nDigitization, IIoT and Edge Computing\nAI and Data Analytics for Manufacturing\nManagement: Project Management and Product Lifecycle Management\nManagement: Supply Chain Management\nProfessional Skills: Design Thinking and Innovation"},{"title":"Semester 3","columns":null,"courses":"Industrial Robotics\nProcess Automation and Control Systems\nDigital Twin and Immersive Technologies\nCyber-Physical and Manufacturing Execution Systems\nReliability Engineering and Asset Health Intelligence\nManagement: Financial Analysis and Management\nProfessional Skills: Entrepreneurship and New Venture Creation"},{"title":"Semester 4","columns":null,"courses":"Industry Internship \/ Capstone Project"}]},"learning_model":{"heading":null,"intro":null,"cards":[],"mix":[],"notes":"<p>At NAMTECH, we believe learning is best driven through immersive, experiential education, which is why core technical courses at NAMTECH follow a 1-0-4 model, with one hour of theory to four hours of laboratory work, reflecting a strong practical orientation.<\/p><p>This inverted approach places practical application at the heart of education at NAMTECH.<\/p><table><thead><tr><th>Learning Component<\/th><th>Approximate Share<\/th><\/tr><\/thead><tbody><tr><td>Practical \/ Laboratory work<\/td><td>~40\u201355%<\/td><\/tr><tr><td>Theory \/ Lectures<\/td><td>~35\u201340%<\/td><\/tr><tr><td>Projects, Internship &amp; Capstone<\/td><td>~5\u201310%<\/td><\/tr><tr><td>Assessments \/ Examinations<\/td><td>~5%<\/td><\/tr><\/tbody><\/table><p><strong>Competency-Based Learning:<\/strong> Students focus on mastering skills and expertise rather than simply applying concepts in the classroom to ensure real-world industrial readiness.<\/p><p><strong>Project-Based Learning:<\/strong> Every student solves real-world problems through projects co-designed with NAMTECH\u2019s industry partners, turning theory into impact right from the start.<\/p><p><strong>Competition-Based Learning:<\/strong> Challenges and competitions modeled on global industry scenarios and standards push students to collaborate, innovate and raise the bar for industry excellence.<\/p>"},"labs":{"heading":null,"intro":null,"items":[]},"admission_steps":{"heading":"Admission Process","intro":null,"steps":[{"text":"Apply online at admissions.namtech.ac & pay \u20b91000\/- application fee."},{"text":"Complete your application and submit all required documents."},{"text":"If shortlisted, attend a personal interview."},{"text":"Receive your admission offer."},{"text":"Confirm your seat & pay tuition fee."}]},"eligibility":{"heading":"Eligibility Criteria","intro":null,"criteria":[],"branches_heading":null,"branches":[{"icon":"gear","text":"Mechanical Engineering"},{"icon":"bolt","text":"Electrical Engineering"},{"icon":"chip","text":"Electronics Engineering"},{"icon":"code","text":"Computer Science Engineering"},{"icon":"factory","text":"Industrial Engineering"},{"icon":"flask","text":"Material Science Engineering"},{"icon":"gear","text":"Automobile Engineering"},{"icon":"chart","text":"Data Science & AI"},{"icon":"drone","text":"Aeronautical Engineering"},{"icon":"magnet","text":"Instrumentation & Control Engineering"}]},"documents":{"heading":"Required Documents","intro":null,"items":[{"icon":"graduation","title":"Academic records","text":"10th and 12th mark sheet, ITI mark sheets and Final Certificate (if applicable), Diploma mark sheets and Degree Certificate"},{"icon":"id","title":"Identity and other documents","text":"ID Proof (Aadhaar Card), Income Certificate, Employment and Experience Certificate (if applicable)"}]},"outcomes":{"heading":"Key Outcomes and Impact","intro":"100% placements for eligible students across previous batches. The highest package was \u20b916 LPA and the average package was \u20b98.49 LPA, with recruiters including AMNS India, Micron, Festo, Schneider Electric and others.","stats":[{"icon":"trend","value":"100%","label":"Placements for eligible students across previous batches","text":null},{"icon":"rupee","value":"\u20b916 LPA","label":"Highest package","text":null},{"icon":"chart","value":"\u20b98.49 LPA","label":"Average package","text":null}],"brochure":null,"logos_heading":null,"logos":[]},"roles":{"heading":"Labs and Infrastructure","intro":"NAMTECH\u2019s specialized labs feature industry-grade laboratory infrastructure designed for students to master operational expertise and efficiency in real smart manufacturing environments.","items":[{"icon":"lightbulb","title":"Additive Manufacturing Lab","text":"Metal and polymer 3D printing, rapid prototyping and design for additive manufacturing."},{"icon":"chip","title":"Mechatronics Lab","text":"Integrated mechanical, electronic and control systems for smart machinery."},{"icon":"robot","title":"Industrial Robotics Lab","text":"Industrial robots, robotic cells and automation integration."},{"icon":"factory","title":"Smart Automation Lab","text":"PLC, SCADA, sensors and control systems for discrete and process automation."},{"icon":"gear","title":"Precision Engineering Lab","text":"Precision machining, metrology and dimensional inspection."},{"icon":"code","title":"CAD \/ CAM Lab","text":"Computer-aided design and manufacturing, digital modeling and toolpaths."},{"icon":"sparkle","title":"Digital Twin and Immersive Lab","text":"Digital twins, AR\/VR\/XR simulation and connected operations."},{"icon":"chart","title":"AI and Data Analytics Lab","text":"Manufacturing data analytics, cloud computing and AI applications."}]},"alumni":{"heading":null,"items":[]},"recruiter_quotes":{"heading":null,"items":[]},"innovations":{"heading":null,"intro":null,"cta_url":null,"items":[]},"awards":{"heading":null,"intro":null,"items":[]},"fees":{"heading":"Fees and Scholarships","intro":null,"fee_label":"Course Fee","total":null,"rows":[{"label":"Tuition (Inclusive of 18% GST) \u2013 Course Fee","value":"\u20b910,00,000\/-"},{"label":"Tuition \u2013 First Year (2027\u20132028)","value":"\u20b95,00,000\/-"},{"label":"Tuition \u2013 Second Year (2028\u20132029)","value":"\u20b95,00,000\/-"},{"label":"Residence (Inclusive of 5% GST) \u2013 Course Fee","value":"\u20b94,00,000\/-"},{"label":"Residence \u2013 First Year (2027\u20132028)","value":"\u20b92,00,000\/-"},{"label":"Residence \u2013 Second Year (2028\u20132029)","value":"\u20b92,00,000\/-"}],"scholarships":[{"title":"Up to 75% on tuition fees","text":"NAMTECH offers a scholarship of up to 75% on tuition fees, based on student academic performance, interview process and family income. Please note that seats are limited and the final decision rests with the admissions & scholarships committee."}],"scholarships_url":"\/admissions#faq","scholarships_label":"Know more about scholarships","notes":[{"icon":"bank","title":"Admissions\/Seat Blocking Fee","text":"A refundable fee of \u20b925,000\/- is payable on acceptance of the offer to confirm admission within the time stated in the LOI, subject to seat availability."},{"icon":"check","title":"Security Deposit & Refunds","text":"This amount doubles as your refundable security deposit. It will be fully refunded upon graduation, minus any outstanding dues. This amount will also be refunded if you withdraw from the program."}]},"loans":{"heading":"Education Loan Assistance","intro":"Invest in your future with confidence. NAMTECH has partnered with leading banks and education finance providers to make funding your master\u2019s program simple and accessible. Eligible students can avail loans covering up to 100% of tuition, hostel and other education-related expenses, with flexible repayment options and collateral-free schemes available through select partners.","providers":[{"name":null,"items":[{"icon":"rupee","text":"Loan coverage of up to 100% of the cost of education (including tuition and hostel fees through select lenders)"},{"icon":"check","text":"Collateral-free loan options available for eligible applicants"},{"icon":"calendar","text":"Repayment tenure of up to 15 years"},{"icon":"document","text":"Tax benefits on interest paid under Section 80E"},{"icon":"bank","text":"Partnerships with ICICI Bank, Axis Bank, Credila and EDUAID for streamlined financing support"},{"icon":"people","text":"Dedicated admissions guidance to help students through the loan application process"}]}]},"life_video":{"heading":"Student Life","intro":"Students have access to a wide array of campus clubs and societies that shape their perspectives inside and outside the classroom. Some of NAMTECH\u2019s best inventions and collaborations are the result of our clubs and societies.","image":null,"video_url":null,"title":null,"text":null},"clubs":{"image":null,"title":null,"items":[{"text":"ASM International Club"},{"text":"IEEE (Institute of Electrical and Electronics Engineers) Club"},{"text":"ISTE (Indian Society of Technical Education) Club"},{"text":"NAMTECH 3D Printing Club"},{"text":"NAMTECH Alumni Club"},{"text":"NAMTECH Entrepreneurship and Innovation Club"},{"text":"NAMTECH NSS (National Service Scheme) Club"},{"text":"NAMTECH Sports Club"},{"text":"NAMTECH Sustainability Club"},{"text":"Robotics Club"},{"text":"SAEINDIA (Society of Automotive Engineers) Collegiate Club"},{"text":"SPICES (Scheme for Promoting Interests, Creativity and Ethics) Cultural Club"},{"text":"Stagemaster\u2019s Club"}],"link_url":null},"life_alumni":{"heading":null,"items":[]},"testimonials":{"heading":null,"items":[]},"faqs":{"heading":"Frequently Asked Questions","intro":null,"items":[{"question":"What is the NAMTECH Master Program in Smart Manufacturing Technology & Management?","answer":"<p>A two-year residential program preparing engineers as techno-managers in smart manufacturing, integrating MIT\u2019s 2.008 hands-on design and manufacturing approach customized for NAMTECH (2.008N) with management depth.<\/p>"},{"question":"What is the eligibility?","answer":"<p>B.E.\/ B.Tech. with minimum 60% in 10th, 12th and graduation, no active backlog. CAT, XAT, GMAT, GRE, or GATE preferred.<\/p>"},{"question":"How is the program delivered?","answer":"<p>On campus at NAMTECH, IIT Gandhinagar, Gujarat, over four 16-week semesters.<\/p>"},{"question":"What are the placement outcomes?","answer":"<p>100% placement for eligible students across previous three batches, with a highest package of \u20b916 LPA and an average of \u20b98.49 LPA.<\/p>"},{"question":"Do I need a background in smart manufacturing to apply?","answer":"<p>No, the program is designed for engineering graduates from electronics, electrical, mechanical, materials, instrumentation and allied disciplines.<\/p>"},{"question":"What is the medium of instruction?","answer":"<p>All instruction, coursework and assessments are conducted in English.<\/p>"},{"question":"Is on-campus accommodation available?","answer":"<p>Yes, the program is residential, with accommodation available on-campus. The details and fees are outlined in the Fees &amp; Scholarship section.<\/p>"},{"question":"Are scholarships available?","answer":"<p>Yes, merit-based scholarships of up to 75% on tuition, based on academic performance, interview and family income.<\/p>"},{"question":"Is a loan facility available?","answer":"<p>Yes, through partnerships with ICICI Bank, Axis Bank, Credila and EDUAID.<\/p>"}]}}'),
(9, 1, 'Master in Heavy Industry Engineering & Management', 'master-in-heavy-industry-engineering-and-management', 'postgraduate', 'Master', 'Developed in collaboration with the ArcelorMittal Design and Engineering Center (AMDEC), this program prepares engineers for heavy industries like steel manufacturing, mining and mineral processing, ports, and capital infrastructure. It combines a rigorous engineering foundation with three specialization tracks and an extended paid industry residency at AMDEC.', NULL, 'On-Campus', 'Ahmedabad', 'August, 2026', '2026-07-30 00:00:00', '2 years', '4 Semesters', '/admissions#enquire', 11, 1, 8, 'published', NULL, '2026-11-18 06:42:37', NULL, NULL, NULL, '2026-11-18 06:43:37', '2026-11-18 06:43:37', NULL, NULL, NULL, NULL, 0, NULL, NULL),
(10, 1, 'Master in Semiconductor Manufacturing Technology & Management', 'master-in-semiconductor-manufacturing-technology-and-management', 'postgraduate', 'Master', 'Master Industrial AI and semiconductor technologies, designing intelligent products and next-generation systems that integrate advanced computing, human-centered design, and emerging technologies to shape the future of manufacturing.', NULL, 'On-Campus', 'Ahmedabad', 'August, 2026', '2026-07-30 00:00:00', '2 years', '4 Semesters', '/admissions#enquire', 2, 1, 9, 'published', NULL, '2026-11-18 06:42:37', NULL, NULL, NULL, '2026-11-18 06:43:37', '2026-11-18 06:43:37', NULL, NULL, NULL, NULL, 0, NULL, NULL),
(11, 3, 'Master in Robotics Engineering & Management', 'master-in-robotics-engineering-and-management', 'postgraduate', 'Master', 'Build hands-on expertise in aerial and legged robotics, collaborative robots, and autonomous systems to engineer connected, adaptive, and human-centric factories of the future.', NULL, 'On-Campus', 'Ahmedabad', 'August, 2026', '2026-07-30 00:00:00', '2 years', '4 Semesters', '/admissions#enquire', 21, 1, 10, 'published', NULL, '2026-11-18 06:42:37', NULL, NULL, NULL, '2026-11-18 06:43:37', '2026-11-18 06:43:37', NULL, NULL, NULL, NULL, 0, NULL, NULL),
(12, 4, 'Master in Sustainability Engineering & Management', 'master-in-sustainability-engineering-and-management', 'postgraduate', 'Master', 'Develop industrial frameworks and technical strategies to build industries that balance innovation and performance with long-term environmental responsibility while working toward net-zero emissions.', '<p>The Master Program in Sustainability Engineering and Management is a two-year, full-time, residential master’s degree crafted to shape the next generation of green industrial leaders. Co-created with industrial and academic powerhouses like KPMG in India and TUM Asia, this program blends engineering, management and sustainability, equipping graduates with skills and technical expertise to drive a climate-resilient industrial transformation.</p><p>Delivered through interactive sessions, the program features real-world projects addressing sustainability challenges, industry-led sessions offering global perspectives and a capstone project applying interdisciplinary learning in a hands-on setting.</p><p>The program is organized into Core Courses and Electives. Core Courses (~60% of the program curricula) are mandatory foundational and advanced subjects in sustainability, while electives are specialized tracks in ESG, policy, entrepreneurship and digital transformation, which account for ~40% of the program curricula.</p>', 'Full-time, On-campus', 'Ahmedabad', 'August 2027', NULL, '24 Months', '4 Semesters', '/admissions#enquire', 20, 1, 11, 'published', NULL, '2026-11-18 06:42:37', NULL, NULL, NULL, '2026-11-18 06:43:37', '2026-11-18 06:43:51', NULL, NULL, NULL, NULL, 0, NULL, '{"brochure":{"file":null},"snapshot":{"start_date":null,"deadline":null,"eligibility":"B.Tech. \/B.E. or Master in Science\/Math in relevant engineering specializations","eligibility_note":"Minimum score of 60% or equivalent CGPA"},"why_choose":{"heading":null,"items":[{"icon":"handshake","title":"Co-Created with Global Leaders","text":"A first-of-its-kind master program co-developed with TUM Asia and KPMG in India, combining world-class academics with industry-led learning."},{"icon":"lightbulb","title":"Future-Ready Interdisciplinary Curriculum","text":"Master emerging domains like AI, data analytics, digital twins, sustainable finance and circular design, converging engineering, sustainability and management."},{"icon":"flask","title":"Experiential Learning in Advanced Labs","text":"Train in NAMTECH\u2019s experiential sustainability Labs through live projects, simulations and industry immersion."},{"icon":"chart","title":"KPMG in India Advantage","text":"Learn from an industry leader strengthening ESG frameworks, driving decarbonization strategies and solving systems transformation challenges across industry sectors."},{"icon":"globe","title":"Global Immersion Opportunity","text":"Experience global academic and industrial standards at TUM Asia and TUM, connecting with international sustainability ecosystems and faculty."},{"icon":"leaf","title":"Gateway to a Green Economy","text":"Enter a high-growth sustainability sector contributing to the growing green economy, driving India\u2019s low-carbon transformation."}]},"class_profile":{"heading":"Class of 2026","intro":null,"image":null,"mix_label":null,"mix":[],"stats":[{"icon":"people","value":"50%","text":"Gender Diversity"},{"icon":"trend","value":"100%","text":"Placement Record"},{"icon":"graduation","value":"70%","text":"Batch Profile"}]},"partners":{"heading":"Program Partners","items":[{"image":null,"tag":"Academic Partner","date":null,"logo":null,"title":"Technical University of Munich (TUM) Asia","text":"TUM Asia is TUM\u2019s Singapore-based teaching campus. Having co-designed the curriculum with NAMTECH, TUM Asia is dedicated to delivering a world-class sustainability engineering education along with embedding international academic excellence and research in Asia.","link_url":null},{"image":null,"tag":"Industry and Technology Partner","date":null,"logo":null,"title":"KPMG in India","text":"KPMG in India is part of a global network of firms providing audit, tax, and advisory services. KPMG in India is a recognized leader in ESG and sustainability consulting, helping organizations transition to climate-responsible and resilient business models. Their partnership with NAMTECH equips students with advanced industrial skills and provides exposure to global sustainability standards.","link_url":null}]},"structure":{"heading":"Program Curriculum","intro":null,"semesters":[{"title":"Semester \u2013 1","columns":null,"courses":"Digital Platforms for ESG - Reporting, Measurement and Certification\nIndustrial Emission Modeling and Decarbonization Pathways\nLCA & Circular Economy \u2013 Digital Tools\nSustainability Tech and AI\nOperational Excellence through Lean Principles\nEnvironment, Health, Safety and Sustainability (EHSS)\nProfessional Skills \u2013 1: Communication and Leadership Skills"},{"title":"Semester \u2013 2","columns":null,"courses":"Renewable Energy & Sustainability Strategies for Conventional Energy\nAI and Simulation for Energy Conversion Systems\nEnergy Storage and Management Solutions\n3D Simulation and Modeling, Digital Urban Transformation\nProject Management and Product Lifecycle Management\nSupply Chain Management\nProfessional Skills \u2013 2: Design Thinking and Innovation"},{"title":"Semester \u2013 3","columns":null,"courses":"Industrial Water Management Technologies\nSustainable Infrastructure, Transport and Value Chains\nEnvironmental and Resource Economics\nCapstone Project (A)\nFinancial Analysis and Management\nStrategic Leadership and Management\nProfessional Skills \u2013 3: Entrepreneurship and New Venture Creation"},{"title":"Semester \u2013 4","columns":null,"courses":"Industry Internship \/ Capstone Project (B)"}]},"learning_model":{"heading":null,"intro":null,"cards":[],"mix":[],"notes":"<p>We believe learning is best driven through immersive, experiential education, which is why core technical courses at NAMTECH follow a 1-0-4 model, with one hour of theory to four hours of laboratory work, reflecting a strong practical orientation.<\/p><table><thead><tr><th>Learning Component<\/th><th>Approximate Share<\/th><\/tr><\/thead><tbody><tr><td>Practical \/ Laboratory work<\/td><td>~40\u201355%<\/td><\/tr><tr><td>Theory \/ Lectures<\/td><td>~35\u201340%<\/td><\/tr><tr><td>Projects, Internship &amp; Capstone<\/td><td>~5\u201310%<\/td><\/tr><tr><td>Assessments \/ Examinations<\/td><td>~5%<\/td><\/tr><\/tbody><\/table><p><strong>Competency-Based Learning:<\/strong> Students focus on mastering skills and expertise rather than simply applying concepts in the classroom to ensure real-world industrial readiness.<\/p><p><strong>Project-Based Learning:<\/strong> Every student solves real-world problems through projects that are co-designed with NAMTECH\u2019s industry partners, turning theory into impact right from the start.<\/p><p><strong>Competition-Based Learning:<\/strong> Challenges and competitions modeled on global industry scenarios and standards push students to collaborate, innovate and raise the bar of industry excellence.<\/p>"},"labs":{"heading":"Labs & Infrastructure","intro":null,"items":[{"image":82,"title":"Green Energy Lab","text":"A hands-on environment focused on solar energy systems and smart management, enabling learners to analyze photovoltaic performance and test practical clean-energy solutions in campus facilities."},{"image":83,"title":"Hydrogen Innovation Lab","text":"A dedicated platform for exploring hydrogen technologies and their role in the future energy transition, providing an experiential foundation for understanding emerging clean-energy systems."},{"image":84,"title":"Water Stewardship Lab","text":"Built around real water-management infrastructure including a Sewage Treatment Plant (STP) and wetland systems, enabling learners to understand water treatment, resource management and sustainable water practices."},{"image":79,"title":"Waste-to-Resource Lab","text":"A demonstrated approach for converting waste into useful resources through technologies, including a bioreactor, waste-plastic-to-fuel unit and carbon-sequestration systems. The lab enables learners to explore practical pathways toward resource recovery and waste reduction."},{"image":85,"title":"Circularity Lab","text":"A hands-on environment for exploring circular production and resource efficiency concepts, supported by 3D printing and analytical equipment that enable experimentation, prototyping and material-focused learning."},{"image":33,"title":"Sustainable Energy Lab","text":"An experiential lab platform spanning wind, solar, and hydrogen technologies, giving learners analytical exposure to multi-source renewable systems and the technologies enabling the broader energy transition."},{"image":35,"title":"Water Management Lab","text":"A dedicated environment for exploring water technologies and process automation, including FESTO-based systems that allow learners to understand automated water-management processes and industrial control."},{"image":80,"title":"ESG Analytics Lab","text":"A computer-based learning environment focused on sustainability analytics, life cycle assessment, project management, and digital sustainability tools. Learners work with platforms including SimaPro, IBM Envizi, Revit, and Microsoft Project Professional."},{"image":78,"title":"Urban Infrastructure Lab","text":"An immersive platform connecting sustainability with built environments and urban systems. The lab incorporates IoT, sensors, BIM, AR\/VR, and related digital technologies to explore smarter, more efficient, and resilient sustainable infrastructure."}]},"admission_steps":{"heading":"Admission Process","intro":null,"steps":[{"text":"Apply online at admissions.namtech.ac & pay \u20b91,000\/- application fee."},{"text":"Complete your application and submit all required documents."},{"text":"Get shortlisted and step into a personal interview."},{"text":"Receive your admission offer."},{"text":"Confirm your seat & pay tuition fee."}]},"eligibility":{"heading":"Eligibility Criteria","intro":null,"criteria":[],"branches_heading":null,"branches":[{"icon":"building","text":"B.E.\/B.Tech. Civil Engineering"},{"icon":"flask","text":"B.E.\/B.Tech. Chemical Engineering"},{"icon":"bolt","text":"B.E.\/B.Tech. Energy Systems Engineering"},{"icon":"leaf","text":"B.E.\/B.Tech. Environmental Engineering"},{"icon":"bolt","text":"B.E.\/B.Tech. Electrical Engineering"},{"icon":"chip","text":"B.E.\/B.Tech. Electrical & Electronics Engineering"},{"icon":"gear","text":"B.E.\/B.Tech. Mechanical Engineering"},{"icon":"flask","text":"B.E.\/B.Tech. Materials Science and Engineering"},{"icon":"factory","text":"B.E.\/B.Tech. Metallurgy Engineering"},{"icon":"factory","text":"B.E.\/B.Tech. Petroleum Engineering"},{"icon":"building","text":"B.Arch Architecture"},{"icon":"lightbulb","text":"B.Des Industrial Design"},{"icon":"flask","text":"M.Sc.\/M.Tech. Science"},{"icon":"chart","text":"M.Sc.\/M.Tech. Mathematics"}]},"documents":{"heading":"Required Documents","intro":null,"items":[{"icon":"graduation","title":"Academic records","text":"10th and 12th mark sheets, ITI mark sheets and final certificate, Diploma mark sheets and degree certificate"},{"icon":"id","title":"Identity and other documents","text":"ID proof (Aadhaar Card), Income certificate, Employment and experience certificate (if applicable)"}]},"outcomes":{"heading":"Key Outcomes and Impact","intro":"NAMTECH has achieved a 100% placement record for its learners over the last three years. The highest package was INR 16 LPA and the average package was INR 8.49 LPA, with recruiters including AM\/NS India, Micron, Festo, Schneider Electric and others.","stats":[{"icon":"trend","value":"100%","label":"Placement record over the last three years","text":null},{"icon":"rupee","value":"INR 16 LPA","label":"Highest package","text":null},{"icon":"chart","value":"INR 8.49 LPA","label":"Average package","text":null}],"brochure":null,"logos_heading":null,"logos":[]},"roles":{"heading":"Build your future in these roles","intro":null,"items":[{"icon":"flask","title":"Environmental Scientist","text":"Research and protect natural ecosystems and resources by analyzing pollution sources, regulatory compliance and ecological impact."},{"icon":"bolt","title":"Renewable Energy Analyst","text":"Evaluate, design and optimize clean power systems to maximize efficiency and commercial viability."},{"icon":"people","title":"Corporate Social Responsibility Manager","text":"Spearhead corporate sustainability strategies, green initiatives and climate-ethical business practices."},{"icon":"chart","title":"Climate Change Analyst","text":"Understand and model environmental trends, carbon metrics and risk factors to assess climate change and inform policy decisions."},{"icon":"leaf","title":"Sustainable Agriculture Specialist","text":"Drive adoption of eco-friendly tech, push resource-efficient farming methods and increase awareness of regenerative agriculture practices."},{"icon":"trend","title":"Social Impact Analyst","text":"Measure and scale the long-term community and environmental value of sustainable investments."},{"icon":"gear","title":"Environmental Engineer","text":"Design and execute green infrastructure, waste management networks and pollution control systems."},{"icon":"building","title":"Urban Planner","text":"Design smart, climate-resilient and energy-optimized cities for sustainable modern living."},{"icon":"graduation","title":"Sustainability Educator","text":"Educate and guide the next generation of green leaders through cutting-edge environmental research."}]},"alumni":{"heading":null,"items":[]},"recruiter_quotes":{"heading":null,"items":[]},"innovations":{"heading":null,"intro":null,"cta_url":null,"items":[]},"awards":{"heading":null,"intro":null,"items":[]},"fees":{"heading":"Fees and Scholarships","intro":null,"fee_label":"Course Fee","total":null,"rows":[{"label":"Tuition (Inclusive of 18% GST) \u2013 Course Fee","value":"\u20b910,00,000\/-"},{"label":"Tuition \u2013 First Year (2027\u201328)","value":"\u20b95,00,000\/-"},{"label":"Tuition \u2013 Second Year (2028\u201329)","value":"\u20b95,00,000\/-"},{"label":"Residence (Inclusive of 5% GST) \u2013 Course Fee","value":"\u20b94,00,000\/-"},{"label":"Residence \u2013 First Year (2027\u201328)","value":"\u20b92,00,000\/-"},{"label":"Residence \u2013 Second Year (2028\u201329)","value":"\u20b92,00,000\/-"}],"scholarships":[{"title":"Up to 75% on tuition fees","text":"NAMTECH offers a scholarship of up to 75% on tuition fees, based on student academic performance, interview performance and family income. Please note that seats are limited and the final decision rests with the Admissions and Scholarships Committee."}],"scholarships_url":"\/admissions#faq","scholarships_label":"Know more about scholarships","notes":[{"icon":"bank","title":"Admissions \/ Seat Blocking Fee","text":"The candidate is required to pay \u20b925,000\/- as acceptance of the offer and to confirm admission within the stipulated time mentioned in the LOI, subject to the availability of seats in the application cycle."},{"icon":"rupee","title":"Adjusted against Security Deposit","text":"The amount of \u20b925,000\/- shall be adjusted against the Security Deposit (refundable)."},{"icon":"check","title":"Refundable Security Deposit","text":"The security deposit is refundable at the time of graduation, adjusted against any outstanding dues."}]},"loans":{"heading":"Education Loan Assistance","intro":"Invest in your future with confidence. NAMTECH has partnered with leading banks and education finance providers to make funding your master\u2019s program simple and accessible. Eligible students can obtain loans covering up to 100% of tuition, hostel and other education-related expenses, with flexible repayment options and collateral-free schemes available through select partners.","providers":[{"name":null,"items":[{"icon":"rupee","text":"Loan coverage of up to 100% of the cost of education (including tuition and hostel fees through select lenders)"},{"icon":"check","text":"Collateral-free loan options available for eligible applicants"},{"icon":"calendar","text":"Repayment tenure of up to 15 years"},{"icon":"document","text":"Tax benefits on interest paid under Section 80E"},{"icon":"bank","text":"Partnerships with ICICI Bank, Axis Bank, Credila and EDUAID for streamlined financing support"},{"icon":"people","text":"Dedicated admissions guidance to help students through the loan application process"}]}]},"life_video":{"heading":"Student Life","intro":"Students have access to a wide array of campus clubs and societies that shape their perspectives inside and outside the classroom. Some of NAMTECH\u2019s best inventions and collaborations are the result of our clubs and societies.","image":null,"video_url":null,"title":null,"text":null},"clubs":{"image":null,"title":null,"items":[{"text":"ASM International Club"},{"text":"IEEE (Institute of Electrical and Electronics Engineers) Club"},{"text":"ISTE (Indian Society of Technical Education) Club"},{"text":"NAMTECH 3D Printing Club"},{"text":"NAMTECH Alumni Club"},{"text":"NAMTECH Entrepreneurship and Innovation Club"},{"text":"NAMTECH NSS (National Service Scheme) Club"},{"text":"NAMTECH Sports Club"},{"text":"NAMTECH Sustainability Club"},{"text":"Robotics Club"},{"text":"SAEINDIA (Society of Automotive Engineers) Collegiate Club"},{"text":"SPICES (Scheme for Promoting Interests, Creativity and Ethics) Cultural Club"},{"text":"Stagemaster\u2019s Club"}],"link_url":null},"life_alumni":{"heading":null,"items":[]},"testimonials":{"heading":null,"items":[]},"faqs":{"heading":"Frequently Asked Questions","intro":null,"items":[{"question":"Who should enroll in the program?","answer":"<p>Engineering, B.Arch., B.Des., or M.Sc. graduates, with or without work experience, as well as MBA graduates who meet the eligibility criteria and are seeking expertise in sustainable manufacturing and ESG leadership, are welcome to apply.<\/p>"},{"question":"Is this program suitable for working professionals?","answer":"<p>Yes. Its residential structure is designed to accommodate both fresh graduates and working professionals.<\/p>"},{"question":"Can I transition from another engineering field?","answer":"<p>Yes. The interdisciplinary curriculum helps professionals from diverse engineering backgrounds move into sustainability careers.<\/p>"},{"question":"What practical skills will I gain?","answer":"<p>Skills include ESG strategy, circular economy, industrial decarbonization, smart manufacturing and hands-on project experience.<\/p>"},{"question":"How quickly can I apply these skills?","answer":"<p>The industry-focused curriculum and real-world projects enable learners to apply concepts immediately in professional settings.<\/p>"},{"question":"Does the program include hands-on learning?","answer":"<p>Yes. Students participate in industry projects, laboratories, case studies and experiential learning modules.<\/p>"},{"question":"How does the program incorporate emerging technologies?","answer":"<p>It integrates AI, digital twins, simulation, analytics, ESG platforms and other advanced sustainability technologies.<\/p>"},{"question":"What labs and infrastructure are available?","answer":"<p>Students have access to modern laboratories and advanced manufacturing and sustainability learning facilities at NAMTECH.<\/p>"},{"question":"How does the program prepare me for industry demands?","answer":"<p>It prepares students through collaboration with KPMG in India and TUM Asia, live industry case studies, and mentorship aligned with current sustainability challenges.<\/p>"},{"question":"What career opportunities can I expect?","answer":"<p>Roles include Sustainability Consultant, ESG Analyst, Renewable Energy Engineer, Circular Economy Strategist and other emerging green careers.<\/p>"},{"question":"Will this program make me job-ready?","answer":"<p>Yes. The curriculum aligns with India\u2019s green manufacturing and sustainability initiatives to develop industry-ready graduates.<\/p>"},{"question":"How is industry integration maintained?","answer":"<p>Industry integration is maintained through continuous collaboration with KPMG in India and manufacturing partners, industry case studies, and expert mentorship.<\/p>"},{"question":"How is this different from other sustainability programs?","answer":"<p>It uniquely combines advanced manufacturing, ESG and circular economy with strong industry integration and practical learning.<\/p>"},{"question":"What mentorship and industry exposure are provided?","answer":"<p>Students learn from sustainability experts through guest lectures, mentorship and industry-led case studies.<\/p>"},{"question":"What financial support is available?","answer":"<p>Flexible payment plans and education loan assistance are available for eligible students.<\/p>"}]}}'),
(13, 1, 'Master in Automotive Technology & Management', 'master-in-automotive-technology-and-management', 'postgraduate', 'Master', 'Advance the future of mobility through the integration of advanced design, engineering and industry expertise to develop next-generation automotive solutions, intelligent vehicle systems, and emerging mobility technologies.', NULL, 'On-Campus', 'Ahmedabad', 'August, 2026', '2026-07-30 00:00:00', '2 years', '4 Semesters', '/admissions#enquire', 7, 1, 12, 'published', NULL, '2026-11-18 06:42:37', NULL, NULL, NULL, '2026-11-18 06:43:37', '2026-11-18 06:43:37', NULL, NULL, NULL, NULL, 0, NULL, NULL),
