(15, 1, 'iPMPX Smart Manufacturing', 'ipmpx-smart-manufacturing', 'executive', 'iPMPX', 'An executive leadership program for senior engineering professionals and factory managers seeking to master digital transformation, Industry 5.0 strategies, and smart operations management.', NULL, 'On-Campus', 'Ahmedabad', 'August, 2026', '2026-07-30 00:00:00', '1 year', 'Executive Mode', '/admissions#enquire', 11, 1, 14, 'published', NULL, '2026-11-18 06:42:37', NULL, NULL, NULL, '2026-11-18 06:43:37', '2026-11-18 06:43:37', NULL, NULL, NULL, NULL, 0, NULL, NULL),
(16, 5, 'iPTP Automation', 'iptp-automation', 'technical', 'iPTP', 'Build upon your ITI or diploma foundation with advanced expertise in industrial automation, control systems, instrumentation, and connected production technologies to configure, integrate, and optimize automated manufacturing systems.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '/admissions#enquire', 2, 1, 15, 'published', NULL, '2026-11-18 06:42:37', NULL, NULL, NULL, '2026-11-18 06:43:37', '2026-11-18 06:43:37', NULL, NULL, NULL, NULL, 0, NULL, NULL),
(17, 5, 'iPTP Semiconductor Manufacturing', 'iptp-semiconductor-manufacturing', 'technical', 'iPTP', 'Gain specialized expertise in semiconductor manufacturing, precision processes, cleanroom practices, and advanced production technologies to build the capabilities needed for India’s growing semiconductor ecosystem.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '/admissions#enquire', 21, 1, 16, 'published', NULL, '2026-11-18 06:42:38', NULL, NULL, NULL, '2026-11-18 06:43:38', '2026-11-18 06:43:38', NULL, NULL, NULL, NULL, 0, NULL, NULL),
(18, 5, 'iPTP Industrial Robotics', 'iptp-industrial-robotics', 'technical', 'iPTP', 'Strengthen your ITI or diploma foundation with specialized expertise in industrial robotics, robotic programming, machine vision, and robot–machine integration to evolve from a skilled technician into an industry-ready technologist.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '/admissions#enquire', 20, 1, 17, 'published', NULL, '2026-11-18 06:42:38', NULL, NULL, NULL, '2026-11-18 06:43:38', '2026-11-18 06:43:38', NULL, NULL, NULL, NULL, 0, NULL, NULL);
