(1, 1, 'Dr. Meera Iyer', 'dr-meera-iyer', 'Dean of Research, School of Manufacturing Technologies', NULL, NULL, NULL, NULL, '<p>Distinguished academic and industry expert with decades of experience in engineering education, advanced automation, and manufacturing technology. Actively involved in pioneering applied research, mentoring cohorts, and driving industry collaborations at NAMTECH.</p>', '[{"period":"1994 \u2013 1997","title":"PhD","institution":"The Queen\u2019s University of Belfast, United Kingdom","text":null},{"period":"1985 \u2013 1987","title":"MTech","institution":"University of Delhi, Delhi","text":null}]', 'Robotics & Autonomous Systems', NULL, 36, 0, 5, 'published', NULL, '2026-11-18 06:42:39', NULL, NULL, NULL, '2026-11-18 06:43:39', '2026-11-18 06:43:39', NULL, NULL, NULL, NULL, 0, 'residential', NULL, NULL, NULL, NULL, NULL),
