INSERT INTO `partnership_categories` VALUES
(1, 'Academic partners', 'academic', 0, '2026-11-18 06:43:38', '2026-11-18 06:43:38'),
(2, 'Industry partners', 'industry', 1, '2026-11-18 06:43:38', '2026-11-18 06:43:38');
INSERT INTO `partners` VALUES
(1, 1, 'Massachusetts Institute of Technology', 'mit', 'In collaboration with MIT’s Department of Mechanical Engineering, NAMTECH brings the renowned MIT 2.008 Manufacturing course to India — combining core manufacturing principles with hands-on application, from product design and process planning to production systems and optimization.', '<p>In collaboration with MIT’s Department of Mechanical Engineering, NAMTECH brings the renowned MIT 2.008 Manufacturing course to India — combining core manufacturing principles with hands-on application, from product design and process planning to production systems and optimization.</p><p>Through this strategic alliance, NAMTECH and our partner collaborate on curriculum co-development, industry-grade experiential learning facilities, faculty training, and direct recruitment pipelines to accelerate India’s manufacturing competitiveness.</p>', NULL, NULL, NULL, 31, 1, 0, 'published', NULL, '2026-11-18 06:42:38', NULL, NULL, NULL, '2026-11-18 06:43:38', '2026-11-18 06:43:38', NULL, NULL, NULL, NULL, 0),
(2, 1, 'Carnegie Mellon University', 'carnegie-mellon-university', 'Through its collaboration with Carnegie Mellon University, NAMTECH leverages CMU’s expertise in learning science, digital education, and technology-enabled learning to develop and share advanced learning resources and methodologies with ITIs, strengthening the quality and reach of technical education. The collaboration also supports faculty training and learning science research.', '<p>Through its collaboration with Carnegie Mellon University, NAMTECH leverages CMU’s expertise in learning science, digital education, and technology-enabled learning to develop and share advanced learning resources and methodologies with ITIs, strengthening the quality and reach of technical education. The collaboration also supports faculty training and learning science research.</p><p>Through this strategic alliance, NAMTECH and our partner collaborate on curriculum co-development, industry-grade experiential learning facilities, faculty training, and direct recruitment pipelines to accelerate India’s manufacturing competitiveness.</p>', NULL, NULL, NULL, 32, 1, 1, 'published', NULL, '2026-11-18 06:42:38', NULL, NULL, NULL, '2026-11-18 06:43:38', '2026-11-18 06:43:38', NULL, NULL, NULL, NULL, 0),
(3, 1, 'Indian Institute of Technology (IIT), Roorkee', 'iit-roorkee', 'Together with IIT Roorkee, and supported by National Thermal Power Corporation (NTPC), NAMTECH has established the Experiential Learning Center for Sustainable Energy & Circularity (ELC:SEC) to advance applied research, industry-focused learning, and technology-led solutions for a more energy-efficient and resource-resilient industrial future.', '<p>Together with IIT Roorkee, and supported by National Thermal Power Corporation (NTPC), NAMTECH has established the Experiential Learning Center for Sustainable Energy &amp; Circularity (ELC:SEC) to advance applied research, industry-focused learning, and technology-led solutions for a more energy-efficient and resource-resilient industrial future.</p><p>Through this strategic alliance, NAMTECH and our partner collaborate on curriculum co-development, industry-grade experiential learning facilities, faculty training, and direct recruitment pipelines to accelerate India’s manufacturing competitiveness.</p>', NULL, NULL, NULL, 33, 1, 2, 'published', NULL, '2026-11-18 06:42:38', NULL, NULL, NULL, '2026-11-18 06:43:38', '2026-11-18 06:43:38', NULL, NULL, NULL, NULL, 0),
(4, 2, 'AM/NS India', 'amns-india', NULL, '<p>NAMTECH has partnered with AMNS India, a leading integrated steel manufacturer and a joint venture between ArcelorMittal and Nippon Steel. This collaboration focuses on advancing skill development, industry-aligned education, and research in manufacturing and materials technologies.</p><p>Through joint initiatives in curriculum design, experiential learning, and applied research, NAMTECH and AMNS India aim to bridge the gap between academia and industry, nurturing a new generation of engineers equipped with cutting-edge technical and managerial capabilities.</p><p>AMNS India’s leadership in sustainable steelmaking and advanced manufacturing complements NAMTECH’s vision of shaping future-ready talent for India’s manufacturing and engineering sectors. Together, this partnership enables real-world exposure, access to industry infrastructure, and career opportunities that empower students to contribute to India’s industrial transformation and global competitiveness.</p>', NULL, NULL, 23, NULL, 0, 3, 'published', NULL, '2026-11-18 06:42:38', NULL, NULL, NULL, '2026-11-18 06:43:38', '2026-11-18 06:43:38', NULL, NULL, NULL, NULL, 0),
(5, 1, 'TUM Asia', 'tum-asia', NULL, NULL, NULL, NULL, 24, NULL, 0, 4, 'published', NULL, '2026-11-18 06:42:38', NULL, NULL, NULL, '2026-11-18 06:43:38', '2026-11-18 06:43:38', NULL, NULL, NULL, NULL, 0),
(6, 2, 'Siemens', 'siemens', 'NAMTECH’s strategic partnership with Siemens strengthens learning in smart manufacturing, automation, and technical education. The collaboration focuses on experiential learning, hands-on training, co-developed curricula, and advanced learning infrastructure to prepare learners for Industry 4.0.', '<p>NAMTECH has forged a strategic partnership with Siemens to revolutionize education in smart manufacturing, automation, and advanced technical education. This collaboration aims to integrate cutting-edge industry expertise into NAMTECH’s academic framework, introducing new electives and dedicated courses within the Master’s, Executive and iPTP programmes.</p><p>The partnership emphasizes experiential learning, hands-on industry training, and the co-development of dynamic course curricula. A key highlight is the establishment of a robust industry attachment programme for both faculty and students, fostering deeper industry-academic integration.</p><p>Additionally, NAMTECH and Siemens will collaborate on developing state-of-the-art infrastructure, creating continuous knowledge-sharing platforms, and designing advanced learning modules to prepare learners for the challenges of Industry 4.0 and beyond.</p><p>Through this partnership, NAMTECH and Siemens are shaping a future-ready workforce equipped with the skills and expertise to drive innovation in manufacturing and automation.</p>', NULL, NULL, 29, 8, 1, 5, 'published', NULL, '2026-11-18 06:42:38', NULL, NULL, NULL, '2026-11-18 06:43:38', '2026-11-18 06:43:38', NULL, NULL, NULL, NULL, 0),
(7, 2, 'Cisco', 'cisco', NULL, '<p>NAMTECH has partnered with Cisco, a global leader in networking and technology solutions. This partnership brings together expertise in manufacturing technologies and digital innovation to enhance our academic programmes and industry relevance.</p><p>This strategic collaboration reflects NAMTECH’S commitment to delivering industry-relevant education and empowering students to excel in the dynamic fields of Cybersecurity and Networking in the field of manufacturing.</p><p>The partnership with industry leaders like CISCO to co-design curriculum, co-invest in learning infrastructure, and participate in recruitment drives helps is highly beneficial for our young professionals. Moreover, by working closely with partners, NAMTECH ensures that its curriculum is aligned with industry needs, providing students with hands-on experience, cutting-edge infrastructure, and pathways to meaningful careers.</p>', NULL, NULL, 26, NULL, 0, 6, 'published', NULL, '2026-11-18 06:42:38', NULL, NULL, NULL, '2026-11-18 06:43:38', '2026-11-18 06:43:38', NULL, NULL, NULL, NULL, 0),
(8, 2, 'Micron', 'micron', NULL, '<p>NAMTECH has partnered with Micron, a global leader in semiconductor solutions. This collaboration spans across academic development, infrastructure setup, student training, and recruitment initiatives.</p><p>Micron is leading the semiconductor manufacturing foray in India and establishing a state-of-the-art facility in Sanand, which lies in close proximity to our campus. By working closely with industry leaders, NAMTECH ensures that its programmes are aligned with industry demands, providing students with hands-on experience, cutting-edge infrastructure, and opportunities for career advancement.</p><p>This holistic approach to the partnership enhances the educational experience and prepares students for successful careers. This synergistic partnership is in line with the steadily growing ecosystem in India and South-East Asia and students stand to benefit from faculty with industry expertise and the skills exposure, as well as employment opportunities in India and abroad.</p>', NULL, NULL, 27, NULL, 0, 7, 'published', NULL, '2026-11-18 06:42:38', NULL, NULL, NULL, '2026-11-18 06:43:38', '2026-11-18 06:43:38', NULL, NULL, NULL, NULL, 0),
(9, 2, 'Festo', 'festo', NULL, '<p>NAMTECH has forged a strategic partnership with Festo, a global leader in automation technology. Festo will design and supply cutting-edge labs at NAMTECH interim campus at Research Park, IIT Gandhinagar, Gujarat, India.</p><p>Festo’s role as a strategic partner for lab equipment and curriculum development ensures that our students have access to state-of-the-art facilities and industry-aligned learning experiences. NAMTECH work with the didactic team at Festo with an aim to offer students insights into leading Industry 4.0 technology.</p><p>This partnership not only enriches our academic programmes but also empowers students with practical skills and knowledge that are highly relevant in today’s manufacturing landscape. Together, we are shaping the future of manufacturing education, preparing students to excel in their careers and contribute meaningfully to the industry.</p>', NULL, NULL, 28, NULL, 0, 8, 'published', NULL, '2026-11-18 06:42:38', NULL, NULL, NULL, '2026-11-18 06:43:38', '2026-11-18 06:43:38', NULL, NULL, NULL, NULL, 0),
(10, 2, 'ABB', 'abb', 'In collaboration with ABB, NAMTECH advances robotics education and supports India’s transition towards automation. The collaboration bridges the skills gap through industry-grade equipment, experiential learning, knowledge sharing via ABB’s experts, applied research, and immersive industry exposure, equipping learners with practical expertise in robotics and automation.', '<p>NAMTECH and ABB have partnered to create a School of Robotics, setting a benchmark in robotics and automation education in India.</p><p>This visionary collaboration bridges the education gap in automation, advancing robotics skills and fostering seamless industry integration.</p><p>At the NAMTECH School of Robotics, ABB Robotics will play a pivotal role in designing, supporting, and executing various programmes. The programmes will be hands-on and industry-focused, supported by world-class infrastructure and guided by global industry leaders like ABB. The goal is to cultivate a highly skilled talent pool for the industrial sector, ensuring students are ready to meet the demands of a rapidly evolving technological landscape.</p><p>ABB’s robotics experts will drive knowledge-sharing initiatives, spearhead cutting-edge research, and facilitate immersive industry exposure, offering unparalleled opportunities for students to gain practical expertise.</p><p>In 2023, India achieved a new milestone with the installation of 8,510 industrial robots, a 59% increase from the previous year. This growth positions India as the seventh-largest global market for annual robot installations and underscores its burgeoning potential in automation. As this trend accelerates through 2024 and 2025, job opportunities in the robotics sector are booming, particularly in roles such as Robotics Engineers, Robot Design Engineers, Application Engineers, and Smart Factory Designers.</p><p>With ABB’s partnership, NAMTECH is at the forefront of shaping the future of robotics education and driving India’s automation revolution.</p>', NULL, NULL, NULL, 34, 1, 9, 'published', NULL, '2026-11-18 06:42:38', NULL, NULL, NULL, '2026-11-18 06:43:38', '2026-11-18 06:43:38', NULL, NULL, NULL, NULL, 0),
(11, 2, 'Schneider Electric', 'schneider-electric', 'Through its partnership with Schneider Electric, NAMTECH advances smart manufacturing education through industry-grade infrastructure, advanced training labs, and experiential learning.', '<p>Schneider Electric is a global leader in energy management, automation, and digitization, providing sustainable solutions for industries, infrastructure, data centres, buildings, and homes. The company focuses on electrification, industrial IoT, automation, smart grid technologies, and digital twin platforms to help organizations enhance reliability, safety, efficiency, and environmental performance. Operating in over 100 countries, Schneider Electric has a substantial presence in India, serving as a key global hub with multiple manufacturing sites, robust R&amp;D capabilities, and significant investments in sustainable and digital technologies.</p><p>NAMTECH’s partnership with Schneider Electric is both strategic and transformative. This collaboration allows us to develop a world-class smart campus and advanced training labs at our temporary Gandhinagar site and the upcoming Ahmedabad campus. Students gain hands-on experience with state-of-the-art lab infrastructure, industry-relevant learning, and direct apprenticeships with experts. Beyond infrastructure, we integrate Schneider’s expertise into our curriculum, particularly for the International Professional Master’s Programme in Smart Manufacturing, ensuring our graduates are prepared for Industry 4.0.</p><p>This partnership offers NAMTECH students employment opportunities in India and internationally, while faculty members benefit from exposure to global best practices. The collaboration supports India’s goals to modernize manufacturing, enhance competitiveness, and bridge the gap between industry and academia. As a result, our graduates are technically skilled, innovative, and prepared to lead in the digital industrial era.</p>', NULL, NULL, 25, 35, 1, 10, 'published', NULL, '2026-11-18 06:42:38', NULL, NULL, NULL, '2026-11-18 06:43:38', '2026-11-18 06:43:38', NULL, NULL, NULL, NULL, 0),
(12, 2, 'L&T Heavy Engineering', 'lt-heavy-engineering', NULL, '<p>NAMTECH has partnered with L&amp;T Heavy Engineering, a prominent leader in the industrial and manufacturing sector. This partnership brings together expertise in advanced manufacturing technologies and digital innovation to enhance our academic programmes and industry relevance.</p><p>This strategic collaboration reflects NAMTECH’S commitment to delivering industry-relevant education and empowering students to excel in the dynamic fields of AI/ML, automation, and advanced manufacturing operations.</p><p>The partnership with industry leaders like L&amp;T Heavy Engineering to co-design capstone projects, tackle real-world challenges like drone surveillance, and provide direct industry certification is highly beneficial for our young professionals.</p>', NULL, NULL, 30, NULL, 0, 11, 'published', NULL, '2026-11-18 06:42:38', NULL, NULL, NULL, '2026-11-18 06:43:38', '2026-11-18 06:43:38', NULL, NULL, NULL, NULL, 0);
