INSERT INTO `initiatives` VALUES
(1, 'Bridging Education and Industry', 'By 2035, we aim to empower 3 million youth with MET skills through education and partnerships to build India’s manufacturing workforce.', 'graduate', 1, 0, '2026-11-18 06:43:43', '2026-11-18 06:43:43'),
(2, 'Expanding Access Without Diluting Quality', 'Students graduate with real-world MET skills from smart factory labs, automation tools, AR/VR, and precision engineering.', 'book', 1, 1, '2026-11-18 06:43:43', '2026-11-18 06:43:43'),
(3, 'Building The Future Manufacturing Workforce', 'A scalable hub-and-spoke model with high-tech centres, connected ITIs, digital learning, and live industry exposure.', 'people', 1, 2, '2026-11-18 06:43:43', '2026-11-18 06:43:43');
