INSERT INTO `page_sections` VALUES
(1, 'page_hero', NULL, NULL, 1, 0, '{"eyebrow":"Schools","title":"School of Sustainability","body":"NAMTECH\u2019s School of Sustainability prepares the next generation to engineer a cleaner, more resilient, and resource-efficient industrial future.","image":78,"cta_label":"Explore Programs","cta_url":"#programs","secondary_label":null,"secondary_url":null,"statistics_group":null,"layout":null,"meta":[]}', '2026-11-18 06:43:43', '2026-11-18 06:43:43', 'school', 4),
(2, 'intro', NULL, NULL, 1, 1, '{"eyebrow":null,"heading":"Overview","body":"<p>NAMTECH\u2019s School of Sustainability integrates engineering, technology, and sustainability to address India\u2019s industrial challenges. Our interdisciplinary, industry-integrated approach combines academic foundations with hands-on learning through living and experiential labs and live projects.<\/p><p>Learners build expertise in ESG, circularity, energy transition, and decarbonization using industry-standard tools. By connecting policy, technology, and implementation, the School prepares professionals to move beyond understanding sustainability challenges to designing and deploying solutions that drive sustainable environmental and social impact across industry and infrastructure.<\/p>","cta_label":null,"cta_url":null,"icon":"leaf","tone":null}', '2026-11-18 06:43:43', '2026-11-18 06:43:43', 'school', 4),
(3, 'pillars', NULL, NULL, 1, 2, '{"eyebrow":null,"heading":"Key Pillars","body":"The School of Sustainability focuses on five interconnected disciplines that are central to India\u2019s transition toward a cleaner, more resilient, and resource-efficient economy.","items":[{"title":"Energy","text":"Focusing on India\u2019s energy transition, NAMTECH\u2019s focus on energy has built expertise in renewable integration, smart management, and industrial efficiency, equipping professionals to optimize operations and ensure energy security.","image":33},{"title":"Circularity","text":"Rethinking linear production through recycling, reuse, and life cycle assessment, NAMTECH is focused on the discipline of circularity to design closed-loop systems for the manufacturing sector for waste minimization and creation of economic value.","image":79},{"title":"Decarbonization","text":"Targeting high-emission sectors like steel and cement, NAMTECH\u2019s decarbonization pillar translates climate ambition into industrial action. Learners master carbon accounting and emission-reduction strategies aligned with global climate goals.","image":76},{"title":"ESG","text":"Developing expertise in sustainability reporting, risk assessment, and data analytics, this pillar is focused on preparing professionals to integrate ESG metrics into business strategy for long-term competitiveness and value creation.","image":80},{"title":"Sustainable Infrastructure","text":"Combining engineering with AI and digital tools, sustainable infrastructure at NAMTECH addresses green buildings, smart cities, and resilient transportation, helping learners design systems that support growth while minimizing environmental impact.","image":81}]}', '2026-11-18 06:43:43', '2026-11-18 06:43:43', 'school', 4),
(4, 'media_cards', NULL, 'programs', 1, 3, '{"eyebrow":"Programs","heading":"Programs Built for Impact","body":null,"items":[{"image":20,"logo":null,"icon":null,"tag":null,"date":null,"title":"B.Tech. Smart & Sustainable Energy","subtitle":null,"body":"From understanding energy to reimagining its future. Build, experiment, and innovate across renewable energy, smart grids, energy storage, and digital technologies \u2013 developing the technical depth and systems thinking to power a cleaner, smarter world.","meta":null,"link_url":"\/programs\/btech-smart-and-sustainable-energy"},{"image":11,"logo":null,"icon":null,"tag":null,"date":null,"title":"Master Program in Sustainability Engineering & Management","subtitle":null,"body":"A flagship interdisciplinary program preparing professionals to lead sustainability transformation across industries. The program combines engineering, technology, management, and sustainability to equip graduates to translate sustainability goals into practical industrial outcomes.","meta":null,"link_url":"\/programs\/master-in-sustainability-engineering-and-management"}],"layout":"tall","tone":null,"cta_label":null,"cta_url":null,"footer_label":null,"footer_url":null,"card_link_label":"Explore program"}', '2026-11-18 06:43:43', '2026-11-18 06:43:43', 'school', 4),
(5, 'image_text', NULL, NULL, 1, 4, '{"eyebrow":"Centers","heading":"Experiential Learning Centre for Sustainable Energy & Circularity","body":"<p>The Experiential Learning Centre for Sustainable Energy and Circularity (ELC:SEC) is a joint initiative of NTPC, IIT Roorkee, and NAMTECH established to advance sustainable manufacturing, energy transition, circularity and workforce transformation. By combining IIT Roorkee\u2019s research excellence with NAMTECH\u2019s industry-integrated learning ecosystem, and NTPC\u2019s commitment to advance sustainable energy solutions the Centre aims to create a national model that connects translational research, talent development and technology deployment.<\/p>","image":20,"image_position":"left","cta_label":"Explore the Centre","cta_url":"\/centres\/experiential-learning-center-for-sustainable-energy-circularity","layout":"side","tone":"light"}', '2026-11-18 06:43:43', '2026-11-18 06:43:43', 'school', 4),
(6, 'video_feature', NULL, NULL, 1, 5, '{"layout":"split","eyebrow":null,"heading":"From the Director\u2019s Desk","body":"\u201cWe are committed to developing the next generation of sustainability-focused leaders, equipped with the engineering, digital, and AI capabilities needed to drive India\u2019s transition to a greener economy. At NAMTECH\u2019s School of Sustainability, our immersive and application-based learning model brings together advanced manufacturing, industrial sustainability, ESG, sustainable energy, and circularity.\u201d","name":"Dr. Ibrahim Hafeezur Rehman","role":"Director, School of Sustainability","image":42,"video_url":null}', '2026-11-18 06:43:43', '2026-11-18 06:43:43', 'school', 4),
(7, 'people', NULL, NULL, 1, 6, '{"eyebrow":"Faculty","heading":"The Experts Driving Your Learning","body":"Distinguished faculty at the School of Sustainability bring together expertise across engineering, sustainability, science, infrastructure, and energy systems, supported by perspectives from academia, industry, and policy.","members":[],"school":"school-of-sustainability","limit":16,"cta_label":null,"cta_url":null,"layout":"carousel","tone":null}', '2026-11-18 06:43:43', '2026-11-18 06:43:43', 'school', 4),
(8, 'media_cards', NULL, NULL, 1, 7, '{"eyebrow":"Labs & Infrastructure","heading":"World-Class Experiential & Living Labs","body":"Living and experiential laboratories bring sustainability concepts to life, allowing learners to observe, analyze, and work with real systems. The infrastructure spans energy, water, waste, circularity, ESG analytics, and urban infrastructure to test theory in real-world conditions.","items":[{"image":82,"logo":null,"icon":null,"tag":"Living Lab","date":null,"title":"Green Energy Lab","subtitle":null,"body":"A hands-on environment focused on solar energy systems and smart management, enabling learners to analyze photovoltaic performance and test practical clean-energy solutions in campus facilities.","meta":null,"link_url":null},{"image":83,"logo":null,"icon":null,"tag":"Living Lab","date":null,"title":"Hydrogen Innovation Lab","subtitle":null,"body":"A dedicated platform for exploring hydrogen technologies and their role in the future energy transition, providing an experiential foundation for understanding emerging clean-energy systems.","meta":null,"link_url":null},{"image":84,"logo":null,"icon":null,"tag":"Living Lab","date":null,"title":"Water Stewardship Lab","subtitle":null,"body":"Built around real water-management infrastructure including a Sewage Treatment Plant (STP) and wetland systems, enabling learners to understand water treatment, resource management and sustainable water practices.","meta":null,"link_url":null},{"image":79,"logo":null,"icon":null,"tag":"Living Lab","date":null,"title":"Waste-to-Resource Lab","subtitle":null,"body":"A demonstrated approach for converting waste into useful resources through technologies, including a bioreactor, waste-plastic-to-fuel unit and carbon-sequestration systems. The lab enables learners to explore practical pathways toward resource recovery and waste reduction.","meta":null,"link_url":null},{"image":85,"logo":null,"icon":null,"tag":"Living Lab","date":null,"title":"Circularity Lab","subtitle":null,"body":"A hands-on environment for exploring circular production and resource efficiency concepts, supported by 3D printing and analytical equipment that enable experimentation, prototyping and material-focused learning.","meta":null,"link_url":null},{"image":33,"logo":null,"icon":null,"tag":"Experiential Lab","date":null,"title":"Sustainable Energy Lab","subtitle":null,"body":"An experiential lab platform spanning wind, solar, and hydrogen technologies, giving learners analytical exposure to multi-source renewable systems and the technologies enabling the broader energy transition.","meta":null,"link_url":null},{"image":35,"logo":null,"icon":null,"tag":"Experiential Lab","date":null,"title":"Water Management Lab","subtitle":null,"body":"A dedicated environment for exploring water technologies and process automation, including FESTO-based systems that allow learners to understand automated water-management processes and industrial control.","meta":null,"link_url":null},{"image":80,"logo":null,"icon":null,"tag":"Experiential Lab","date":null,"title":"ESG Analytics Lab","subtitle":null,"body":"A computer-based learning environment focused on sustainability analytics, life cycle assessment, project management, and digital sustainability tools. Learners work with platforms including SimaPro, IBM Envizi, Revit, and Microsoft Project Professional.","meta":null,"link_url":null},{"image":78,"logo":null,"icon":null,"tag":"Experiential Lab","date":null,"title":"Urban Infrastructure Lab","subtitle":null,"body":"An immersive platform connecting sustainability with built environments and urban systems. The lab incorporates IoT, sensors, BIM, AR\/VR, and related digital technologies to explore smarter, more efficient, and resilient sustainable infrastructure.","meta":null,"link_url":null}],"layout":"tall","tone":null,"cta_label":"Explore Labs","cta_url":"\/academics\/labs-and-infrastructure","footer_label":null,"footer_url":null,"card_link_label":null}', '2026-11-18 06:43:43', '2026-11-18 06:43:43', 'school', 4),
(9, 'value_list', NULL, NULL, 1, 8, '{"eyebrow":null,"heading":"Industry & Academic Partnerships","body":"The School of Sustainability works with leading industry and academic institutions to ensure its programs remain connected to real industrial challenges and emerging global practices. Partnerships span curriculum development, industry projects, internships, technology-enabled learning and applied research.","items":[{"icon":"bolt","title":"Industry: National Thermal Power Corporation (NTPC)","text":"NTPC Limited, India\u2019s largest integrated power utility, is supporting the establishment of the Centre for Sustainable Energy and Circularity through its Corporate Social Responsibility (CSR) initiative, enabling the development of experiential learning infrastructure, capacity-building programs and outreach initiatives focused on sustainable energy and circularity."},{"icon":"handshake","title":"Industry: KPMG India","text":"KPMG in India is part of a global network of professional services firms providing audit, tax, and advisory services, with expertise in ESG and sustainability consulting. Its collaboration with NAMTECH brings industry perspectives into sustainability learning, helping students develop practical capabilities and global exposure relevant to India\u2019s manufacturing transformation."},{"icon":"graduation","title":"Academic: IIT Roorkee","text":"IIT Roorkee, an Institute of National Importance and a pioneer in engineering and technical education, brings its academic and research expertise to NAMTECH through the Experiential Learning Centre for Sustainable Energy & Circularity. The partnership is focused on research and innovation, setup of joint labs, development of academic programs, and faculty development to help advance solutions for India\u2019s sustainable energy and circular economy ambitions."},{"icon":"globe","title":"Academic: TUM Asia","text":"TUM Asia is Technical University of Munich (TUM) Singapore-based teaching campus. Our academic collaboration with TUM Asia brings global engineering perspectives and international academic expertise into NAMTECH\u2019s sustainability ecosystem."}]}', '2026-11-18 06:43:43', '2026-11-18 06:43:43', 'school', 4),
(10, 'events_carousel', NULL, NULL, 1, 9, '{"eyebrow":null,"heading":"Upcoming Events","body":null,"cta_label":"View all events","cta_url":"\/events","tone":null,"category":null,"school":"school-of-sustainability"}', '2026-11-18 06:43:43', '2026-11-18 06:43:43', 'school', 4),
(11, 'achievements', NULL, 'awards', 1, 10, '{"eyebrow":null,"heading":"Awards and Achievements","body":null,"tone":null,"layout":"awards","items":[{"logo":null,"value":null,"title":"Excellence in Sustainable Engineering Education 2025","text":"Recognized for innovative experiential curriculum in industrial sustainability and decarbonization.","icon":null},{"logo":null,"value":null,"title":"Pioneering Industry-Academia Collaborative Lab 2024","text":"Awarded for state-of-the-art living labs established in partnership with global clean-tech leaders.","icon":null},{"logo":null,"value":null,"title":"Best Green Campus & Clean Energy Initiative 2024","text":"Honored for comprehensive circular economy practices and energy-efficient campus operations.","icon":null}]}', '2026-11-18 06:43:43', '2026-11-18 06:43:43', 'school', 4),
(12, 'news_carousel', NULL, NULL, 1, 11, '{"heading":"News & Insights","post_type":"news","limit":8,"cta_label":"View all insights","cta_url":"\/media"}', '2026-11-18 06:43:43', '2026-11-18 06:43:43', 'school', 4),
(13, 'page_hero', NULL, NULL, 0, 0, '{"eyebrow":"School of Sustainability","title":"Master Program in Sustainability Engineering and Management","body":"Created in collaboration with KPMG in India and Technical University of Munich (TUM), Asia, students solve real-world sustainability challenges through hands-on learning and industry collaboration, combining advanced manufacturing with ESG frameworks, circular economy and climate innovations.","image":82,"cta_label":"Apply Now","cta_url":"\/admissions#enquire","secondary_label":"Enquire","secondary_url":"#enquire","statistics_group":null,"layout":null,"meta":[{"icon":"clock","text":"24 Months \u00b7 4 Semesters"},{"icon":"calendar","text":"Intake: August 2027"},{"icon":"building","text":"Full-time, On-campus"}]}', '2026-11-18 06:43:43', '2026-11-18 06:43:51', 'program', 12),
(14, 'intro', NULL, NULL, 0, 1, '{"eyebrow":null,"heading":"Program Overview","body":"<p>The Master Program in Sustainability Engineering and Management is a two-year, full-time, residential master\u2019s degree crafted to shape the next generation of green industrial leaders. Co-created with industrial and academic powerhouses like KPMG in India and TUM Asia, this program blends engineering, management and sustainability, equipping graduates with skills and technical expertise to drive a climate-resilient industrial transformation.<\/p><p>Delivered through interactive sessions, the program features real-world projects addressing sustainability challenges, industry-led sessions offering global perspectives and a capstone project applying interdisciplinary learning in a hands-on setting.<\/p><p>The program is organized into Core Courses and Electives. Core Courses (~60% of the program curricula) are mandatory foundational and advanced subjects in sustainability, while electives are specialized tracks in ESG, policy, entrepreneurship and digital transformation, which account for ~40% of the program curricula.<\/p>","cta_label":null,"cta_url":null,"icon":"leaf","tone":null}', '2026-11-18 06:43:43', '2026-11-18 06:43:51', 'program', 12),
(15, 'feature_list', NULL, NULL, 0, 2, '{"eyebrow":null,"heading":"Program Snapshot","body":null,"tabs":[{"label":null,"items":[{"icon":"clock","text":"Duration: 24 Months \u00b7 4 Semesters (Includes 10-Week Industry Internship + 24-Week Capstone Project)"},{"icon":"calendar","text":"Intake: August 2027"},{"icon":"building","text":"Mode: Full-time, On-campus"},{"icon":"graduation","text":"Eligibility: B.Tech. \/B.E. or Master in Science\/Math in relevant engineering specializations (Minimum score of 60% or equivalent CGPA)"},{"icon":"document","text":"Application Deadline: August 2027"}]}]}', '2026-11-18 06:43:43', '2026-11-18 06:43:51', 'program', 12),
(16, 'card_grid', NULL, NULL, 0, 3, '{"eyebrow":null,"heading":"The NAMTECH Advantage","body":null,"columns":"3","tone":"white","cards":[{"icon":"handshake","title":"Co-Created with Global Leaders","body":"A first-of-its-kind master program co-developed with TUM Asia and KPMG in India, combining world-class academics with industry-led learning.","link_url":null},{"icon":"lightbulb","title":"Future-Ready Interdisciplinary Curriculum","body":"Master emerging domains like AI, data analytics, digital twins, sustainable finance and circular design, converging engineering, sustainability and management.","link_url":null},{"icon":"flask","title":"Experiential Learning in Advanced Labs","body":"Train in NAMTECH\u2019s experiential sustainability Labs through live projects, simulations and industry immersion.","link_url":null},{"icon":"chart","title":"KPMG in India Advantage","body":"Learn from an industry leader strengthening ESG frameworks, driving decarbonization strategies and solving systems transformation challenges across industry sectors.","link_url":null},{"icon":"globe","title":"Global Immersion Opportunity","body":"Experience global academic and industrial standards at TUM Asia and TUM, connecting with international sustainability ecosystems and faculty.","link_url":null},{"icon":"leaf","title":"Gateway to a Green Economy","body":"Enter a high-growth sustainability sector contributing to the growing green economy, driving India\u2019s low-carbon transformation.","link_url":null}],"style":"joined","cta_label":null,"cta_url":null}', '2026-11-18 06:43:43', '2026-11-18 06:43:51', 'program', 12),
(17, 'stat_cards', NULL, NULL, 0, 4, '{"eyebrow":null,"heading":"Class of 2026","body":null,"tone":"lavender","items":[{"icon":"people","value":"50%","label":"Gender Diversity","text":"50% women"},{"icon":"trend","value":"100%","label":"Placement Record","text":"100% placement rate"},{"icon":"graduation","value":"70%","label":"Batch Profile","text":"70% of students have no work experience"}]}', '2026-11-18 06:43:43', '2026-11-18 06:43:51', 'program', 12),
(18, 'value_list', NULL, NULL, 0, 5, '{"eyebrow":null,"heading":"Program Partners","body":null,"items":[{"icon":"graduation","title":"Academic Partner: Technical University of Munich (TUM) Asia","text":"TUM Asia is TUM\u2019s Singapore-based teaching campus. Having co-designed the curriculum with NAMTECH, TUM Asia is dedicated to delivering a world-class sustainability engineering education along with embedding international academic excellence and research in Asia."},{"icon":"handshake","title":"Industry and Technology Partner: KPMG in India","text":"KPMG in India is part of a global network of firms providing audit, tax, and advisory services. KPMG in India is a recognized leader in ESG and sustainability consulting, helping organizations transition to climate-responsible and resilient business models. Their partnership with NAMTECH equips students with advanced industrial skills and provides exposure to global sustainability standards."}]}', '2026-11-18 06:43:43', '2026-11-18 06:43:51', 'program', 12),
(19, 'tabs', NULL, 'curriculum', 0, 6, '{"eyebrow":null,"heading":"Program Curriculum","body":null,"tabs":[{"label":"Semester 1","title":"Semester \u2013 1","body":"<ol><li>Digital Platforms for ESG - Reporting, Measurement and Certification<\/li><li>Industrial Emission Modeling and Decarbonization Pathways<\/li><li>LCA &amp; Circular Economy \u2013 Digital Tools<\/li><li>Sustainability Tech and AI<\/li><li>Operational Excellence through Lean Principles<\/li><li>Environment, Health, Safety and Sustainability (EHSS)<\/li><li>Professional Skills \u2013 1: Communication and Leadership Skills<\/li><\/ol>","image":null},{"label":"Semester 2","title":"Semester \u2013 2","body":"<ol><li>Renewable Energy &amp; Sustainability Strategies for Conventional Energy<\/li><li>AI and Simulation for Energy Conversion Systems<\/li><li>Energy Storage and Management Solutions<\/li><li>3D Simulation and Modeling, Digital Urban Transformation<\/li><li>Project Management and Product Lifecycle Management<\/li><li>Supply Chain Management<\/li><li>Professional Skills \u2013 2: Design Thinking and Innovation<\/li><\/ol>","image":null},{"label":"Semester 3","title":"Semester \u2013 3","body":"<ol><li>Industrial Water Management Technologies<\/li><li>Sustainable Infrastructure, Transport and Value Chains<\/li><li>Environmental and Resource Economics<\/li><li>Capstone Project (A)<\/li><li>Financial Analysis and Management<\/li><li>Strategic Leadership and Management<\/li><li>Professional Skills \u2013 3: Entrepreneurship and New Venture Creation<\/li><\/ol>","image":null},{"label":"Semester 4","title":"Semester \u2013 4","body":"<ol><li>Industry Internship \/ Capstone Project (B)<\/li><\/ol>","image":null}],"layout":"standard","tone":null}', '2026-11-18 06:43:43', '2026-11-18 06:43:51', 'program', 12),
(20, 'rich_text', NULL, NULL, 0, 7, '{"heading":"The NAMTECH Learning Model","body":"<p>We believe learning is best driven through immersive, experiential education, which is why core technical courses at NAMTECH follow a 1-0-4 model, with one hour of theory to four hours of laboratory work, reflecting a strong practical orientation.<\/p><table><thead><tr><th>Learning Component<\/th><th>Approximate Share<\/th><\/tr><\/thead><tbody><tr><td>Practical \/ Laboratory work<\/td><td>~40\u201355%<\/td><\/tr><tr><td>Theory \/ Lectures<\/td><td>~35\u201340%<\/td><\/tr><tr><td>Projects, Internship &amp; Capstone<\/td><td>~5\u201310%<\/td><\/tr><tr><td>Assessments \/ Examinations<\/td><td>~5%<\/td><\/tr><\/tbody><\/table><p><strong>Competency-Based Learning:<\/strong> Students focus on mastering skills and expertise rather than simply applying concepts in the classroom to ensure real-world industrial readiness.<\/p><p><strong>Project-Based Learning:<\/strong> Every student solves real-world problems through projects that are co-designed with NAMTECH\u2019s industry partners, turning theory into impact right from the start.<\/p><p><strong>Competition-Based Learning:<\/strong> Challenges and competitions modeled on global industry scenarios and standards push students to collaborate, innovate and raise the bar of industry excellence.<\/p>","toc":false,"width":"wide"}', '2026-11-18 06:43:43', '2026-11-18 06:43:51', 'program', 12),
(21, 'media_cards', NULL, NULL, 0, 8, '{"eyebrow":null,"heading":"Labs & Infrastructure","body":null,"items":[{"image":82,"logo":null,"icon":null,"tag":"Living Lab","date":null,"title":"Green Energy Lab","subtitle":null,"body":"A hands-on environment focused on solar energy systems and smart management, enabling learners to analyze photovoltaic performance and test practical clean-energy solutions in campus facilities.","meta":null,"link_url":null},{"image":83,"logo":null,"icon":null,"tag":"Living Lab","date":null,"title":"Hydrogen Innovation Lab","subtitle":null,"body":"A dedicated platform for exploring hydrogen technologies and their role in the future energy transition, providing an experiential foundation for understanding emerging clean-energy systems.","meta":null,"link_url":null},{"image":84,"logo":null,"icon":null,"tag":"Living Lab","date":null,"title":"Water Stewardship Lab","subtitle":null,"body":"Built around real water-management infrastructure including a Sewage Treatment Plant (STP) and wetland systems, enabling learners to understand water treatment, resource management and sustainable water practices.","meta":null,"link_url":null},{"image":79,"logo":null,"icon":null,"tag":"Living Lab","date":null,"title":"Waste-to-Resource Lab","subtitle":null,"body":"A demonstrated approach for converting waste into useful resources through technologies, including a bioreactor, waste-plastic-to-fuel unit and carbon-sequestration systems. The lab enables learners to explore practical pathways toward resource recovery and waste reduction.","meta":null,"link_url":null},{"image":85,"logo":null,"icon":null,"tag":"Living Lab","date":null,"title":"Circularity Lab","subtitle":null,"body":"A hands-on environment for exploring circular production and resource efficiency concepts, supported by 3D printing and analytical equipment that enable experimentation, prototyping and material-focused learning.","meta":null,"link_url":null},{"image":33,"logo":null,"icon":null,"tag":"Experiential Lab","date":null,"title":"Sustainable Energy Lab","subtitle":null,"body":"An experiential lab platform spanning wind, solar, and hydrogen technologies, giving learners analytical exposure to multi-source renewable systems and the technologies enabling the broader energy transition.","meta":null,"link_url":null},{"image":35,"logo":null,"icon":null,"tag":"Experiential Lab","date":null,"title":"Water Management Lab","subtitle":null,"body":"A dedicated environment for exploring water technologies and process automation, including FESTO-based systems that allow learners to understand automated water-management processes and industrial control.","meta":null,"link_url":null},{"image":80,"logo":null,"icon":null,"tag":"Experiential Lab","date":null,"title":"ESG Analytics Lab","subtitle":null,"body":"A computer-based learning environment focused on sustainability analytics, life cycle assessment, project management, and digital sustainability tools. Learners work with platforms including SimaPro, IBM Envizi, Revit, and Microsoft Project Professional.","meta":null,"link_url":null},{"image":78,"logo":null,"icon":null,"tag":"Experiential Lab","date":null,"title":"Urban Infrastructure Lab","subtitle":null,"body":"An immersive platform connecting sustainability with built environments and urban systems. The lab incorporates IoT, sensors, BIM, AR\/VR, and related digital technologies to explore smarter, more efficient, and resilient sustainable infrastructure.","meta":null,"link_url":null}],"layout":"tall","tone":null,"cta_label":"Explore Labs","cta_url":"\/academics\/labs-and-infrastructure","footer_label":null,"footer_url":null,"card_link_label":null}', '2026-11-18 06:43:43', '2026-11-18 06:43:51', 'program', 12),
(22, 'post_list', NULL, 'innovations', 0, 9, '{"heading":"Student Innovations","post_type":"story","category":null,"limit":3,"cta_label":"All stories","cta_url":"\/impact\/stories","layout":"carousel"}', '2026-11-18 06:43:43', '2026-11-18 06:43:51', 'program', 12),
(23, 'steps', NULL, NULL, 0, 10, '{"eyebrow":null,"heading":"Admission Process","body":null,"image":64,"items":[{"title":"Apply online at admissions.namtech.ac & pay \u20b91,000\/- application fee.","body":null},{"title":"Complete your application and submit all required documents.","body":null},{"title":"Get shortlisted and step into a personal interview.","body":null},{"title":"Receive your admission offer.","body":null},{"title":"Confirm your seat & pay tuition fee.","body":null}],"layout":"panel","panel_title":"Steps"}', '2026-11-18 06:43:43', '2026-11-18 06:43:51', 'program', 12),
(24, 'eligibility', NULL, NULL, 0, 11, '{"eyebrow":null,"heading":"Eligibility Criteria","body":null,"criteria":[{"text":"Candidates with B.E.\/B.Tech. or Master\u2019s degrees in Science or Mathematics. Candidates must have a minimum of 60% marks or equivalent CGPA in 10th, 12th, and graduation from a recognized Indian university or institute. (No active backlog)"},{"text":"A score in CAT\/ XAT\/GMAT\/GRE\/GATE is preferred."},{"text":"Open school students are not eligible."}],"list_heading":"Eligible Engineering Branches","items":[{"icon":"building","text":"B.E.\/B.Tech. Civil Engineering"},{"icon":"flask","text":"B.E.\/B.Tech. Chemical Engineering"},{"icon":"bolt","text":"B.E.\/B.Tech. Energy Systems Engineering"},{"icon":"leaf","text":"B.E.\/B.Tech. Environmental Engineering"},{"icon":"bolt","text":"B.E.\/B.Tech. Electrical Engineering"},{"icon":"chip","text":"B.E.\/B.Tech. Electrical & Electronics Engineering"},{"icon":"gear","text":"B.E.\/B.Tech. Mechanical Engineering"},{"icon":"flask","text":"B.E.\/B.Tech. Materials Science and Engineering"},{"icon":"factory","text":"B.E.\/B.Tech. Metallurgy Engineering"},{"icon":"factory","text":"B.E.\/B.Tech. Petroleum Engineering"},{"icon":"building","text":"B.Arch Architecture"},{"icon":"lightbulb","text":"B.Des Industrial Design"},{"icon":"flask","text":"M.Sc.\/M.Tech. Science"},{"icon":"chart","text":"M.Sc.\/M.Tech. Mathematics"}]}', '2026-11-18 06:43:43', '2026-11-18 06:43:51', 'program', 12),
(25, 'checklist_cards', NULL, NULL, 0, 12, '{"eyebrow":null,"heading":"Required Documents","body":null,"tone":"light","cards":[{"icon":"graduation","title":"Academic records","items":[{"text":"10th and 12th mark sheets"},{"text":"ITI mark sheets and final certificate"},{"text":"Diploma mark sheets and degree certificate"}]},{"icon":"id","title":"Identity and other documents","items":[{"text":"ID proof (Aadhaar Card)"},{"text":"Income certificate"},{"text":"Employment and experience certificate (if applicable)"}]}]}', '2026-11-18 06:43:43', '2026-11-18 06:43:51', 'program', 12),
(26, 'stat_cards', NULL, NULL, 0, 13, '{"eyebrow":null,"heading":"Key Outcomes and Impact","body":"NAMTECH has achieved a 100% placement record for its learners over the last three years. The highest package was INR 16 LPA and the average package was INR 8.49 LPA, with recruiters including AM\/NS India, Micron, Festo, Schneider Electric and others.","tone":"white","items":[{"icon":"trend","value":"100%","label":"Placement record over the last three years","text":null},{"icon":"rupee","value":"INR 16 LPA","label":"Highest package","text":null},{"icon":"chart","value":"INR 8.49 LPA","label":"Average package","text":null}]}', '2026-11-18 06:43:43', '2026-11-18 06:43:51', 'program', 12),
(27, 'card_grid', NULL, NULL, 0, 14, '{"eyebrow":null,"heading":"Build your future in these roles","body":null,"columns":"3","tone":"lavender","cards":[{"icon":"flask","title":"Environmental Scientist","body":"Research and protect natural ecosystems and resources by analyzing pollution sources, regulatory compliance and ecological impact.","link_url":null},{"icon":"bolt","title":"Renewable Energy Analyst","body":"Evaluate, design and optimize clean power systems to maximize efficiency and commercial viability.","link_url":null},{"icon":"people","title":"Corporate Social Responsibility Manager","body":"Spearhead corporate sustainability strategies, green initiatives and climate-ethical business practices.","link_url":null},{"icon":"chart","title":"Climate Change Analyst","body":"Understand and model environmental trends, carbon metrics and risk factors to assess climate change and inform policy decisions.","link_url":null},{"icon":"leaf","title":"Sustainable Agriculture Specialist","body":"Drive adoption of eco-friendly tech, push resource-efficient farming methods and increase awareness of regenerative agriculture practices.","link_url":null},{"icon":"trend","title":"Social Impact Analyst","body":"Measure and scale the long-term community and environmental value of sustainable investments.","link_url":null},{"icon":"gear","title":"Environmental Engineer","body":"Design and execute green infrastructure, waste management networks and pollution control systems.","link_url":null},{"icon":"building","title":"Urban Planner","body":"Design smart, climate-resilient and energy-optimized cities for sustainable modern living.","link_url":null},{"icon":"graduation","title":"Sustainability Educator","body":"Educate and guide the next generation of green leaders through cutting-edge environmental research.","link_url":null}],"style":"outlined","cta_label":null,"cta_url":null}', '2026-11-18 06:43:43', '2026-11-18 06:43:51', 'program', 12),
(28, 'testimonials', NULL, 'recruiters', 0, 15, '{"eyebrow":null,"heading":"Hear from Recruiters","items":[{"quote":null,"name":null,"role":null,"image":null},{"quote":null,"name":null,"role":null,"image":null},{"quote":null,"name":null,"role":null,"image":null}],"layout":"quotes","body":null,"tone":null}', '2026-11-18 06:43:43', '2026-11-18 06:43:51', 'program', 12),
(29, 'fees', NULL, NULL, 0, 16, '{"eyebrow":null,"heading":"Fees and Scholarships","body":null,"fee_label":"Course Fee","fee_amount":null,"rows":[{"label":"Tuition (Inclusive of 18% GST) \u2013 Course Fee","value":"\u20b910,00,000\/-"},{"label":"Tuition \u2013 First Year (2027\u201328)","value":"\u20b95,00,000\/-"},{"label":"Tuition \u2013 Second Year (2028\u201329)","value":"\u20b95,00,000\/-"},{"label":"Residence (Inclusive of 5% GST) \u2013 Course Fee","value":"\u20b94,00,000\/-"},{"label":"Residence \u2013 First Year (2027\u201328)","value":"\u20b92,00,000\/-"},{"label":"Residence \u2013 Second Year (2028\u201329)","value":"\u20b92,00,000\/-"}],"scholarships_title":"Scholarships","scholarships":[{"title":"Up to 75% on tuition fees","text":"NAMTECH offers a scholarship of up to 75% on tuition fees, based on student academic performance, interview performance and family income. Please note that seats are limited and the final decision rests with the Admissions and Scholarships Committee."}],"link_label":"Know more about scholarships","link_url":"\/admissions#faq","notes":[{"icon":"bank","title":"Admissions \/ Seat Blocking Fee","text":"The candidate is required to pay \u20b925,000\/- as acceptance of the offer and to confirm admission within the stipulated time mentioned in the LOI, subject to the availability of seats in the application cycle."},{"icon":"rupee","title":"Adjusted against Security Deposit","text":"The amount of \u20b925,000\/- shall be adjusted against the Security Deposit (refundable)."},{"icon":"check","title":"Refundable Security Deposit","text":"The security deposit is refundable at the time of graduation, adjusted against any outstanding dues."}]}', '2026-11-18 06:43:43', '2026-11-18 06:43:51', 'program', 12),
(30, 'feature_list', NULL, NULL, 0, 17, '{"eyebrow":null,"heading":"Education Loan Assistance","body":"Invest in your future with confidence. NAMTECH has partnered with leading banks and education finance providers to make funding your master\u2019s program simple and accessible. Eligible students can obtain loans covering up to 100% of tuition, hostel and other education-related expenses, with flexible repayment options and collateral-free schemes available through select partners.","tabs":[{"label":null,"items":[{"icon":"rupee","text":"Loan coverage of up to 100% of the cost of education (including tuition and hostel fees through select lenders)"},{"icon":"check","text":"Collateral-free loan options available for eligible applicants"},{"icon":"calendar","text":"Repayment tenure of up to 15 years"},{"icon":"document","text":"Tax benefits on interest paid under Section 80E"},{"icon":"bank","text":"Partnerships with ICICI Bank, Axis Bank, Credila and EDUAID for streamlined financing support"},{"icon":"people","text":"Dedicated admissions guidance to help students through the loan application process"}]}]}', '2026-11-18 06:43:43', '2026-11-18 06:43:51', 'program', 12),
(31, 'feature_list', NULL, NULL, 0, 18, '{"eyebrow":null,"heading":"Student Life","body":"Students have access to a wide array of campus clubs and societies that shape their perspectives inside and outside the classroom. Some of NAMTECH\u2019s best inventions and collaborations are the result of our clubs and societies.","tabs":[{"label":null,"items":[{"icon":"people","text":"ASM International Club"},{"icon":"people","text":"IEEE (Institute of Electrical and Electronics Engineers) Club"},{"icon":"people","text":"ISTE (Indian Society of Technical Education) Club"},{"icon":"people","text":"NAMTECH 3D Printing Club"},{"icon":"people","text":"NAMTECH Alumni Club"},{"icon":"people","text":"NAMTECH Entrepreneurship and Innovation Club"},{"icon":"people","text":"NAMTECH NSS (National Service Scheme) Club"},{"icon":"people","text":"NAMTECH Sports Club"},{"icon":"people","text":"NAMTECH Sustainability Club"},{"icon":"people","text":"Robotics Club"},{"icon":"people","text":"SAEINDIA (Society of Automotive Engineers) Collegiate Club"},{"icon":"people","text":"SPICES (Scheme for Promoting Interests, Creativity and Ethics) Cultural Club"},{"icon":"people","text":"Stagemaster\u2019s Club"}]}]}', '2026-11-18 06:43:43', '2026-11-18 06:43:51', 'program', 12),
(32, 'testimonials', NULL, 'testimonials', 0, 19, '{"eyebrow":"Student Stories","heading":"Hear From Our Students & Alumni","items":[{"quote":null,"name":"Shanti Priya","role":"Smart Manufacturing Engineer, Germany","image":86},{"quote":null,"name":"Rahul Sharma","role":"Automation & Robotics Specialist","image":55}],"layout":"portrait","body":null,"tone":null}', '2026-11-18 06:43:43', '2026-11-18 06:43:51', 'program', 12),
(33, 'faq', NULL, 'faq', 0, 20, '{"heading":"Frequently Asked Questions","body":null,"items":[{"question":"Who should enroll in the program?","answer":"<p>Engineering, B.Arch., B.Des., or M.Sc. graduates, with or without work experience, as well as MBA graduates who meet the eligibility criteria and are seeking expertise in sustainable manufacturing and ESG leadership, are welcome to apply.<\/p>"},{"question":"Is this program suitable for working professionals?","answer":"<p>Yes. Its residential structure is designed to accommodate both fresh graduates and working professionals.<\/p>"},{"question":"Can I transition from another engineering field?","answer":"<p>Yes. The interdisciplinary curriculum helps professionals from diverse engineering backgrounds move into sustainability careers.<\/p>"},{"question":"What practical skills will I gain?","answer":"<p>Skills include ESG strategy, circular economy, industrial decarbonization, smart manufacturing and hands-on project experience.<\/p>"},{"question":"How quickly can I apply these skills?","answer":"<p>The industry-focused curriculum and real-world projects enable learners to apply concepts immediately in professional settings.<\/p>"},{"question":"Does the program include hands-on learning?","answer":"<p>Yes. Students participate in industry projects, laboratories, case studies and experiential learning modules.<\/p>"},{"question":"How does the program incorporate emerging technologies?","answer":"<p>It integrates AI, digital twins, simulation, analytics, ESG platforms and other advanced sustainability technologies.<\/p>"},{"question":"What labs and infrastructure are available?","answer":"<p>Students have access to modern laboratories and advanced manufacturing and sustainability learning facilities at NAMTECH.<\/p>"},{"question":"How does the program prepare me for industry demands?","answer":"<p>It prepares students through collaboration with KPMG in India and TUM Asia, live industry case studies, and mentorship aligned with current sustainability challenges.<\/p>"},{"question":"What career opportunities can I expect?","answer":"<p>Roles include Sustainability Consultant, ESG Analyst, Renewable Energy Engineer, Circular Economy Strategist and other emerging green careers.<\/p>"},{"question":"Will this program make me job-ready?","answer":"<p>Yes. The curriculum aligns with India\u2019s green manufacturing and sustainability initiatives to develop industry-ready graduates.<\/p>"},{"question":"How is industry integration maintained?","answer":"<p>Industry integration is maintained through continuous collaboration with KPMG in India and manufacturing partners, industry case studies, and expert mentorship.<\/p>"},{"question":"How is this different from other sustainability programs?","answer":"<p>It uniquely combines advanced manufacturing, ESG and circular economy with strong industry integration and practical learning.<\/p>"},{"question":"What mentorship and industry exposure are provided?","answer":"<p>Students learn from sustainability experts through guest lectures, mentorship and industry-led case studies.<\/p>"},{"question":"What financial support is available?","answer":"<p>Flexible payment plans and education loan assistance are available for eligible students.<\/p>"}],"layout":"centered"}', '2026-11-18 06:43:43', '2026-11-18 06:43:51', 'program', 12),
(34, 'enquiry_form', NULL, 'enquire', 0, 21, '{"heading":"Enquire about this program","body":"Tell us about yourself and our admissions team will get back to you.","form_type":"program","show_contact_details":true}', '2026-11-18 06:43:43', '2026-11-18 06:43:51', 'program', 12),
(35, 'page_hero', NULL, NULL, 1, 0, '{"eyebrow":"Schools","title":"School of Manufacturing Technologies","body":"NAMTECH empowers the next-generation of engineers to build, code, and operate the intelligent, connected factories of tomorrow.","image":67,"cta_label":"Explore Programs","cta_url":"#programs","secondary_label":null,"secondary_url":null,"statistics_group":null,"layout":null,"meta":[]}', '2026-11-18 06:43:43', '2026-11-18 06:43:43', 'school', 1),
(36, 'intro', NULL, NULL, 1, 1, '{"eyebrow":null,"heading":"About the School of Manufacturing Technologies","body":"<p>The School of Manufacturing Technologies at NAMTECH develops engineers who can become leaders across the two forces shaping India\u2019s industrial future: the rise of intelligent, connected manufacturing and the scaling of the heavy industries that anchor the economy. As steel plants, ports, and mines become as data-driven as a smart factory, India\u2019s Industry 4.0 revolution requires engineers capable of integrating digital precision with large-scale industrial operations.<\/p>","cta_label":null,"cta_url":null,"icon":"factory","tone":null}', '2026-11-18 06:43:43', '2026-11-18 06:43:43', 'school', 1),
(37, 'pillars', NULL, NULL, 1, 2, '{"eyebrow":null,"heading":"Core Pillars","body":null,"items":[{"title":"Smart and Digital Manufacturing","text":"From digital intelligence to physical making. Master the technologies that connect machines, systems, and people on the factory floor.","image":34},{"title":"Heavy Industry Engineering","text":"Technology creates value when it works at scale. Build the heavy-industry mastery needed to apply smart technologies to the complex industrial assets driving the country.","image":87},{"title":"Capital Projects and Operations Management","text":"From blueprint to reality, execution is the differentiator. Build the engineering and management discipline to deliver complex industrial projects seamlessly at scale.","image":81},{"title":"Industrial Sustainability and Decarbonization","text":"The next industrial revolution must be sustainable by design. Master the technologies and practices that make manufacturing cleaner, leaner, and future-ready.","image":33}]}', '2026-11-18 06:43:43', '2026-11-18 06:43:43', 'school', 1),
(38, 'media_cards', NULL, 'programs', 1, 3, '{"eyebrow":"Programs","heading":"Programs Built for Impact","body":null,"items":[{"image":7,"logo":null,"icon":null,"tag":"UG","date":null,"title":"B.Tech. Mechanical Engineering (Smart Manufacturing)","subtitle":null,"body":"From engineering fundamentals to intelligent manufacturing. Build, experiment, and solve through hands-on learning across mechanical engineering, robotics, automation, advanced manufacturing, and digital technologies \u2013 developing the technical depth and maker mindset to lead the factories of tomorrow.","meta":null,"link_url":"\/programs\/btech-mechanical-engineering-smart-manufacturing"},{"image":3,"logo":null,"icon":null,"tag":"PG","date":null,"title":"Master in Smart Manufacturing Technology and Management","subtitle":null,"body":"Prepares engineers to build and lead the intelligent, connected factory through a maker-first approach. Students work hands-on from day one across additive manufacturing, mechatronics, industrial robotics, smart automation, and digital twins, while building management depth in supply chain, operational excellence, quality, reliability, and product lifecycle management.","meta":null,"link_url":"\/programs\/master-in-smart-manufacturing-technology-and-management"},{"image":87,"logo":null,"icon":null,"tag":"PG","date":null,"title":"Master in Heavy Industry Engineering and Management","subtitle":null,"body":"Developed in collaboration with the ArcelorMittal Design and Engineering Center (AMDEC), this program prepares engineers for heavy industries like steel manufacturing, mining and mineral processing, ports, and capital infrastructure. It combines a rigorous engineering foundation with three specialization tracks and an extended paid industry residency at AMDEC.","meta":null,"link_url":"\/programs\/master-in-heavy-industry-engineering-and-management"},{"image":21,"logo":null,"icon":null,"tag":"Executive","date":null,"title":"iPMPX (Smart Manufacturing)","subtitle":null,"body":"Develop the strategic perspective and technological depth to harness smart manufacturing, AI, automation, and connected systems to lead industrial transformation at scale.","meta":null,"link_url":"\/programs\/ipmpx-smart-manufacturing"}],"layout":"tall","tone":null,"cta_label":null,"cta_url":null,"footer_label":null,"footer_url":null,"card_link_label":"Explore program"}', '2026-11-18 06:43:44', '2026-11-18 06:43:44', 'school', 1),
(39, 'video_feature', NULL, NULL, 1, 4, '{"layout":"split","eyebrow":null,"heading":"From the Director\u2019s Desk","body":"\u201cIndia aims to lift manufacturing from around 16 percent of GDP toward 30 percent by 2047. That ambition rests on two pillars: the intelligent, connected factory, where data, automation, and AI redefine how things are made, and heavy industry; the steel plants, mines, ports, and capital projects on which everything else is built. That is why this School exists. The School is built for students who learn by making, getting hands-on with the robotics, digital twins, and AI systems that define the modern factory. Our mission is to create engineers and industry leaders who merge technology with sustainability, innovation with purpose, and productivity with resilience, and who will help carry India toward a globally competitive, self-reliant, and intelligent manufacturing future.\u201d","name":"Dr. Sanjeev Gupta","role":"Dean \u2013 Quality Assurance & Rankings; Director \u2013 School of Manufacturing Technologies","image":40,"video_url":null}', '2026-11-18 06:43:44', '2026-11-18 06:43:44', 'school', 1),
(40, 'people', NULL, NULL, 1, 5, '{"eyebrow":"Faculty","heading":"The Experts Driving Your Learning","body":"The School\u2019s residential & visiting faculty brings together global research credentials, deep technical grounding, and elite academic backgrounds to guide the next generation of industrial leaders.","members":[],"school":"school-of-manufacturing-technologies","limit":16,"cta_label":null,"cta_url":null,"layout":"carousel","tone":null}', '2026-11-18 06:43:44', '2026-11-18 06:43:44', 'school', 1),
(41, 'card_grid', NULL, NULL, 1, 6, '{"eyebrow":"Labs & Infrastructure","heading":"WorldSkills-Aligned Industry 4.0 Laboratories","body":"Our advanced laboratories give students hands-on experience with globally benchmarked platforms across the full manufacturing lifecycle.","columns":"3","tone":"white","cards":[{"icon":"gear","title":"Precision Engineering Lab","body":"Precision machining, metrology, and dimensional inspection on industry-grade equipment.","link_url":null},{"icon":"code","title":"CAD\/CAM Lab","body":"Computer-aided design and manufacturing, digital modeling, and toolpath generation.","link_url":null},{"icon":"factory","title":"Industrial Automation Lab","body":"PLC, SCADA, sensors, and control systems for discrete and process automation.","link_url":null},{"icon":"lightbulb","title":"Additive Manufacturing Lab","body":"Metal and polymer 3D printing, rapid prototyping, and design for additive manufacturing.","link_url":null},{"icon":"bolt","title":"Welding 4.0 Lab","body":"Advanced and automated welding processes with digital monitoring.","link_url":null},{"icon":"chip","title":"Mechatronics Lab","body":"Integrated mechanical, electronic, and control systems for smart machinery.","link_url":null},{"icon":"robot","title":"Industrial Robotics Lab","body":"Six-axis industrial robots, robotic cells, and automation integration.","link_url":null},{"icon":"sparkle","title":"AR\/VR Immersive Learning Lab","body":"Augmented and virtual reality for immersive training and process simulation.","link_url":null},{"icon":"magnet","title":"Hydraulics & Pneumatics Lab","body":"Fluid power systems, actuation, and industrial motion control.","link_url":null},{"icon":"chart","title":"Smart Supply Chain & Digital Lab","body":"Data-driven logistics, digital twins, and connected factory operations.","link_url":null},{"icon":"building","title":"Computer Center","body":"High-performance computing for simulation, analytics, and digital engineering.","link_url":null}],"style":"joined","cta_label":null,"cta_url":null}', '2026-11-18 06:43:44', '2026-11-18 06:43:44', 'school', 1),
(42, 'card_grid', NULL, NULL, 1, 7, '{"eyebrow":"Partnerships","heading":"Academic Partnerships and Industry Alliances","body":"Global automation leaders supporting our Smart Manufacturing labs with industrial robots, automation platforms, and didactic systems.","columns":"4","tone":"lavender","cards":[{"icon":"factory","title":"Siemens","body":null,"link_url":null},{"icon":"factory","title":"ABB","body":null,"link_url":null},{"icon":"robot","title":"FANUC","body":null,"link_url":null},{"icon":"factory","title":"Rockwell Automation","body":null,"link_url":null},{"icon":"gear","title":"Festo","body":null,"link_url":null},{"icon":"bolt","title":"Schneider Electric","body":null,"link_url":null},{"icon":"handshake","title":"ArcelorMittal Design and Engineering Center (AMDEC) and AMNS India","body":"AMNS India is a founding partner behind NAMTECH. AMDEC has co-designed and co-delivers our Master Program in Heavy Industry Engineering and Management, offering teaching, research scoping, internships, paid industry residencies, and direct career pipelines.","link_url":null},{"icon":"building","title":"L&T Heavy Engineering","body":"Provides students with real-world exposure to large-scale heavy engineering manufacturing, equipment design, and fabrication practices.","link_url":null},{"icon":"graduation","title":"TUM Asia (Technical University of Munich)","body":null,"link_url":null},{"icon":"graduation","title":"Purdue University Northwest","body":null,"link_url":null},{"icon":"graduation","title":"Carnegie Mellon University","body":null,"link_url":null},{"icon":"graduation","title":"Dept of Mechanical Engineering, Massachusetts Institute of Technology","body":null,"link_url":null}],"style":"outlined","cta_label":null,"cta_url":null}', '2026-11-18 06:43:44', '2026-11-18 06:43:44', 'school', 1),
(43, 'page_hero', NULL, NULL, 0, 0, '{"eyebrow":"School of Manufacturing Technologies","title":"Master Program in Smart Manufacturing Technology and Management","body":"NAMTECH equips graduates with the operational mastery, data-driven acumen and strategic depth needed to command the Industry 4.0 revolution. Co-created with globally leading universities and industry titans, the program transforms high-caliber engineers into skilled techno-managers who design, build and manage smart factories.","image":88,"cta_label":"Apply Now","cta_url":"\/admissions#enquire","secondary_label":"Enquire","secondary_url":"#enquire","statistics_group":null,"layout":null,"meta":[{"icon":"clock","text":"24 Months \u00b7 4 Semesters"},{"icon":"calendar","text":"Intake: August 2027"},{"icon":"building","text":"Full-time, residential"}]}', '2026-11-18 06:43:44', '2026-11-18 06:43:51', 'program', 8),
(44, 'intro', NULL, NULL, 0, 1, '{"eyebrow":null,"heading":"Program Overview","body":"<p>The Master Program in Smart Manufacturing Technology and Management is a two-year residential program to build industry-ready techno-managers for Manufacturing Engineering Technology (MET) sectors. Offered in collaboration with Technical University of Munich (TUM Asia, Singapore) and incorporating MIT\u2019s landmark 2.008 Design and Manufacturing II framework customized for NAMTECH (2.008 N), the curriculum delivers deep, hands-on expertise in additive manufacturing, mechatronics, industrial robotics, smart automation and digital twin ecosystems, complemented by executive-level management training.<\/p><p>Using globally benchmarked, WorldSkills-aligned platforms, students solve high-impact and live industrial challenges with guidance from world-class faculty and global industry leaders. Students graduate fully prepared to build, integrate and lead the manufacturing transformation of India.<\/p>","cta_label":null,"cta_url":null,"icon":"factory","tone":null}', '2026-11-18 06:43:44', '2026-11-18 06:43:51', 'program', 8),
(45, 'feature_list', NULL, NULL, 0, 2, '{"eyebrow":null,"heading":"Program Snapshot","body":null,"tabs":[{"label":null,"items":[{"icon":"clock","text":"Duration: 24 Months \u00b7 4 Semesters (16 weeks per semester + industry internship & capstone)"},{"icon":"calendar","text":"Intake: August 2027"},{"icon":"building","text":"Mode: Full-time, residential"},{"icon":"graduation","text":"Eligibility: B.E.\/ B.Tech. across engineering branches (Minimum score of 60% in 10th, 12th & graduation)"},{"icon":"document","text":"Application Deadline: August 2027"}]}]}', '2026-11-18 06:43:44', '2026-11-18 06:43:51', 'program', 8),
(46, 'card_grid', NULL, NULL, 0, 3, '{"eyebrow":null,"heading":"The NAMTECH Advantage","body":null,"columns":"3","tone":"white","cards":[{"icon":"lightbulb","title":"Future-Ready Techno-Managerial Focus","body":"NAMTECH fuses cutting-edge engineering and smart factory technology with executive leadership, data-driven technologies and sustainability, shaping graduates for next-generation careers.","link_url":null},{"icon":"gear","title":"Built on MIT\u2019s Hands-On Philosophy","body":"The curriculum integrates MIT\u2019s gold-standard 2.008 Design and Manufacturing framework customized for NAMTECH (2.008N), establishing a true \u201cexperiential\u201d foundation essential for Industry 4.0.","link_url":null},{"icon":"globe","title":"Learn from Global Experts","body":"Learn directly from distinguished international faculty from Technical University of Munich, Asia (TUM Asia), Carnegie Mellon University and other leading universities alongside industry experts from Siemens, Schneider Electric, Cisco, Festo and L&T.","link_url":null},{"icon":"trend","title":"Proven Placement Track Record","body":"100% placement record for eligible students across top-tier recruiters including AM\/NS India, Micron, Festo and Schneider Electric among others.","link_url":null},{"icon":"rupee","title":"Scholarships and Financial Support","body":"Access merit-based scholarships of up to 100% on tuition, plus education loan support from leading banks, making our advanced programs accessible to aspiring engineers.","link_url":null},{"icon":"handshake","title":"Co-Designed with Industry Giants","body":"Developed and delivered collaboratively with industry leaders and academic experts to ensure that graduates are industry-ready from day one.","link_url":null}],"style":"joined","cta_label":null,"cta_url":null}', '2026-11-18 06:43:44', '2026-11-18 06:43:51', 'program', 8),
(47, 'stat_cards', NULL, 'class-of-2026', 0, 4, '{"eyebrow":"Student Profile Mix","heading":"Class of 2026","body":"Our diverse cohort brings together high-caliber engineering talent from across India, preparing them for leadership in Industry 4.0.","tone":"lavender","items":[{"icon":"trend","value":"96%","label":"Placement Rate","text":null},{"icon":"rupee","value":"\u20b912L","label":"Average Salary","text":null},{"icon":"handshake","value":"14+","label":"Hiring Partners","text":null},{"icon":"award","value":"100%","label":"Experiential Learning","text":null}]}', '2026-11-18 06:43:44', '2026-11-18 06:43:51', 'program', 8),
(48, 'value_list', NULL, NULL, 0, 5, '{"eyebrow":null,"heading":"Program Partners","body":null,"items":[{"icon":"graduation","title":"Academic Partner: Technical University of Munich (TUM Asia, Singapore)","text":"A globally top-ranked technical university, TUM Asia has co-designed the curriculum with NAMTECH and offers deep academic collaboration, embedding world-class German technical education standards into NAMTECH."},{"icon":"graduation","title":"Academic Partner: Department of Mechanical Engineering, Massachusetts Institute of Technology (USA)","text":"Blending rigorous theory with intensive hands-on making, MIT\u2019s Department of Mechanical Engineering provides the foundational 2.008 Design & Manufacturing II framework, customized for NAMTECH (2.008N) that guides NAMTECH\u2019s \u201cexperiential learning\u201d ethos."},{"icon":"graduation","title":"Academic Partner: Carnegie Mellon University (USA)","text":"Carnegie Mellon University, an internationally renowned research institution, enables faculty exchange and advanced research pedagogy transfer to NAMTECH."},{"icon":"graduation","title":"Academic Partner: Purdue University Northwest (USA)","text":"Purdue University Northwest offers an exclusive 1+1 pathway to a Master of Science in Mechanical Engineering for eligible students, unlocking global academic acceleration."},{"icon":"factory","title":"Industry and Technology Partners: Siemens, ABB, FANUC, Rockwell Automation, Festo, Schneider Electric, Cisco and Analog Devices","text":"Global automation and technology leaders supporting Industry 4.0 laboratories and the curriculum with equipment, platforms, and training."},{"icon":"handshake","title":"Industry Partners: AMNS India and L&T Heavy Engineering","text":"Anchor industry partners providing industrial mentorship, live manufacturing projects and recruitment."}]}', '2026-11-18 06:43:44', '2026-11-18 06:43:51', 'program', 8),
(49, 'tabs', NULL, 'curriculum', 0, 6, '{"eyebrow":null,"heading":"Program Structure","body":"The Master Program in Smart Manufacturing Technology and Management spans four 16-week semesters, equipping learners with technical mastery, hands-on laboratory experience, live industry capstone projects and management expertise required to power the future of smart manufacturing.","tabs":[{"label":"Semester 1","title":"Semester 1","body":"<ul><li>Precision Engineering and Manufacturing Processes<\/li><li>Machine Systems and Industrial Mechatronics<\/li><li>Foundations of Smart Manufacturing Systems<\/li><li>Industrial Automation<\/li><li>Management: Operational Excellence through Lean Principles<\/li><li>Management: Environment, Health, Safety and Sustainability (EHSS)<\/li><li>Professional Skills: Communication and Leadership Skills<\/li><\/ul>","image":null},{"label":"Semester 2","title":"Semester 2","body":"<ul><li>Design for Manufacturing (2.008N) 1 &amp; 2<\/li><li>Digitization, IIoT and Edge Computing<\/li><li>AI and Data Analytics for Manufacturing<\/li><li>Management: Project Management and Product Lifecycle Management<\/li><li>Management: Supply Chain Management<\/li><li>Professional Skills: Design Thinking and Innovation<\/li><\/ul>","image":null},{"label":"Semester 3","title":"Semester 3","body":"<ul><li>Industrial Robotics<\/li><li>Process Automation and Control Systems<\/li><li>Digital Twin and Immersive Technologies<\/li><li>Cyber-Physical and Manufacturing Execution Systems<\/li><li>Reliability Engineering and Asset Health Intelligence<\/li><li>Management: Financial Analysis and Management<\/li><li>Professional Skills: Entrepreneurship and New Venture Creation<\/li><\/ul>","image":null},{"label":"Semester 4","title":"Semester 4","body":"<ul><li>Industry Internship \/ Capstone Project<\/li><\/ul>","image":null}],"layout":"standard","tone":null}', '2026-11-18 06:43:44', '2026-11-18 06:43:51', 'program', 8),
(50, 'rich_text', NULL, NULL, 0, 7, '{"heading":"The NAMTECH Learning Model","body":"<p>At NAMTECH, we believe learning is best driven through immersive, experiential education, which is why core technical courses at NAMTECH follow a 1-0-4 model, with one hour of theory to four hours of laboratory work, reflecting a strong practical orientation.<\/p><p>This inverted approach places practical application at the heart of education at NAMTECH.<\/p><table><thead><tr><th>Learning Component<\/th><th>Approximate Share<\/th><\/tr><\/thead><tbody><tr><td>Practical \/ Laboratory work<\/td><td>~40\u201355%<\/td><\/tr><tr><td>Theory \/ Lectures<\/td><td>~35\u201340%<\/td><\/tr><tr><td>Projects, Internship &amp; Capstone<\/td><td>~5\u201310%<\/td><\/tr><tr><td>Assessments \/ Examinations<\/td><td>~5%<\/td><\/tr><\/tbody><\/table><p><strong>Competency-Based Learning:<\/strong> Students focus on mastering skills and expertise rather than simply applying concepts in the classroom to ensure real-world industrial readiness.<\/p><p><strong>Project-Based Learning:<\/strong> Every student solves real-world problems through projects co-designed with NAMTECH\u2019s industry partners, turning theory into impact right from the start.<\/p><p><strong>Competition-Based Learning:<\/strong> Challenges and competitions modeled on global industry scenarios and standards push students to collaborate, innovate and raise the bar for industry excellence.<\/p>","toc":false,"width":"wide"}', '2026-11-18 06:43:44', '2026-11-18 06:43:51', 'program', 8);
INSERT INTO `page_sections` VALUES
(51, 'card_grid', NULL, NULL, 0, 8, '{"eyebrow":null,"heading":"Labs and Infrastructure","body":"NAMTECH\u2019s specialized labs feature industry-grade laboratory infrastructure designed for students to master operational expertise and efficiency in real smart manufacturing environments.","columns":"4","tone":"white","cards":[{"icon":"lightbulb","title":"Additive Manufacturing Lab","body":"Metal and polymer 3D printing, rapid prototyping and design for additive manufacturing.","link_url":null},{"icon":"chip","title":"Mechatronics Lab","body":"Integrated mechanical, electronic and control systems for smart machinery.","link_url":null},{"icon":"robot","title":"Industrial Robotics Lab","body":"Industrial robots, robotic cells and automation integration.","link_url":null},{"icon":"factory","title":"Smart Automation Lab","body":"PLC, SCADA, sensors and control systems for discrete and process automation.","link_url":null},{"icon":"gear","title":"Precision Engineering Lab","body":"Precision machining, metrology and dimensional inspection.","link_url":null},{"icon":"code","title":"CAD \/ CAM Lab","body":"Computer-aided design and manufacturing, digital modeling and toolpaths.","link_url":null},{"icon":"sparkle","title":"Digital Twin and Immersive Lab","body":"Digital twins, AR\/VR\/XR simulation and connected operations.","link_url":null},{"icon":"chart","title":"AI and Data Analytics Lab","body":"Manufacturing data analytics, cloud computing and AI applications.","link_url":null}],"style":"joined","cta_label":null,"cta_url":null}', '2026-11-18 06:43:44', '2026-11-18 06:43:51', 'program', 8),
(52, 'post_list', NULL, 'innovations', 0, 9, '{"heading":"Student Innovations","post_type":"story","category":null,"limit":3,"cta_label":"All stories","cta_url":"\/impact\/stories","layout":"carousel"}', '2026-11-18 06:43:44', '2026-11-18 06:43:51', 'program', 8),
(53, 'steps', NULL, NULL, 0, 10, '{"eyebrow":null,"heading":"Admission Process","body":null,"image":64,"items":[{"title":"Apply online at admissions.namtech.ac & pay \u20b91000\/- application fee.","body":null},{"title":"Complete your application and submit all required documents.","body":null},{"title":"If shortlisted, attend a personal interview.","body":null},{"title":"Receive your admission offer.","body":null},{"title":"Confirm your seat & pay tuition fee.","body":null}],"layout":"panel","panel_title":"Steps"}', '2026-11-18 06:43:44', '2026-11-18 06:43:51', 'program', 8),
(54, 'eligibility', NULL, NULL, 0, 11, '{"eyebrow":null,"heading":"Eligibility Criteria","body":null,"criteria":[{"text":"Candidates with B.E.\/B.Tech. with a minimum score of 60% in 10th, 12th, and graduation or equivalent CGPA from a recognized Indian university or institute. (No active backlog)"},{"text":"Scores on CAT, XAT, GMAT, GRE, GATE are preferred."},{"text":"Open school students are not eligible."}],"list_heading":"Eligible Engineering Branches","items":[{"icon":"gear","text":"Mechanical Engineering"},{"icon":"bolt","text":"Electrical Engineering"},{"icon":"chip","text":"Electronics Engineering"},{"icon":"code","text":"Computer Science Engineering"},{"icon":"factory","text":"Industrial Engineering"},{"icon":"flask","text":"Material Science Engineering"},{"icon":"gear","text":"Automobile Engineering"},{"icon":"chart","text":"Data Science & AI"},{"icon":"drone","text":"Aeronautical Engineering"},{"icon":"magnet","text":"Instrumentation & Control Engineering"}]}', '2026-11-18 06:43:44', '2026-11-18 06:43:51', 'program', 8),
(55, 'checklist_cards', NULL, NULL, 0, 12, '{"eyebrow":null,"heading":"Required Documents","body":null,"tone":"light","cards":[{"icon":"graduation","title":"Academic records","items":[{"text":"10th and 12th mark sheet"},{"text":"ITI mark sheets and Final Certificate (if applicable)"},{"text":"Diploma mark sheets and Degree Certificate"}]},{"icon":"id","title":"Identity and other documents","items":[{"text":"ID Proof (Aadhaar Card)"},{"text":"Income Certificate"},{"text":"Employment and Experience Certificate (if applicable)"}]}]}', '2026-11-18 06:43:44', '2026-11-18 06:43:51', 'program', 8),
(56, 'stat_cards', NULL, NULL, 0, 13, '{"eyebrow":null,"heading":"Key Outcomes and Impact","body":"100% placements for eligible students across previous batches. The highest package was \u20b916 LPA and the average package was \u20b98.49 LPA, with recruiters including AMNS India, Micron, Festo, Schneider Electric and others.","tone":"white","items":[{"icon":"trend","value":"100%","label":"Placements for eligible students across previous batches","text":null},{"icon":"rupee","value":"\u20b916 LPA","label":"Highest package","text":null},{"icon":"chart","value":"\u20b98.49 LPA","label":"Average package","text":null}]}', '2026-11-18 06:43:44', '2026-11-18 06:43:51', 'program', 8),
(57, 'card_grid', NULL, NULL, 0, 14, '{"eyebrow":null,"heading":"Build Your Future in These Roles","body":null,"columns":"3","tone":"lavender","cards":[{"icon":"factory","title":"Manufacturing Systems Engineer","body":"Design and optimize integrated production systems combining machines, automation and data.","link_url":null},{"icon":"robot","title":"Automation and Robotics Engineer","body":"Program and integrate industrial robots and automated cells.","link_url":null},{"icon":"sparkle","title":"Digital Twin Engineer","body":"Build virtual replicas of processes and plants to simulate, monitor and optimize operations.","link_url":null},{"icon":"lightbulb","title":"Additive Manufacturing Engineer","body":"Develop and run metal and polymer 3D-printing processes for prototyping and production.","link_url":null},{"icon":"check","title":"Smart Operations and Quality Lead","body":"Drive operational excellence, quality and reliability using lean and data-driven methods.","link_url":null},{"icon":"chart","title":"Industrial Data and AI Analyst","body":"Turn machine and process data into insight that improves productivity and uptime.","link_url":null}],"style":"outlined","cta_label":null,"cta_url":null}', '2026-11-18 06:43:44', '2026-11-18 06:43:51', 'program', 8),
(58, 'testimonials', NULL, 'recruiters', 0, 15, '{"eyebrow":null,"heading":"Hear from Recruiters","items":[{"quote":null,"name":null,"role":null,"image":null},{"quote":null,"name":null,"role":null,"image":null},{"quote":null,"name":null,"role":null,"image":null}],"layout":"quotes","body":null,"tone":null}', '2026-11-18 06:43:44', '2026-11-18 06:43:51', 'program', 8),
(59, 'fees', NULL, NULL, 0, 16, '{"eyebrow":null,"heading":"Fees and Scholarships","body":null,"fee_label":"Course Fee","fee_amount":null,"rows":[{"label":"Tuition (Inclusive of 18% GST) \u2013 Course Fee","value":"\u20b910,00,000\/-"},{"label":"Tuition \u2013 First Year (2027\u20132028)","value":"\u20b95,00,000\/-"},{"label":"Tuition \u2013 Second Year (2028\u20132029)","value":"\u20b95,00,000\/-"},{"label":"Residence (Inclusive of 5% GST) \u2013 Course Fee","value":"\u20b94,00,000\/-"},{"label":"Residence \u2013 First Year (2027\u20132028)","value":"\u20b92,00,000\/-"},{"label":"Residence \u2013 Second Year (2028\u20132029)","value":"\u20b92,00,000\/-"}],"scholarships_title":"Scholarships","scholarships":[{"title":"Up to 75% on tuition fees","text":"NAMTECH offers a scholarship of up to 75% on tuition fees, based on student academic performance, interview process and family income. Please note that seats are limited and the final decision rests with the admissions & scholarships committee."}],"link_label":"Know more about scholarships","link_url":"\/admissions#faq","notes":[{"icon":"bank","title":"Admissions\/Seat Blocking Fee","text":"A refundable fee of \u20b925,000\/- is payable on acceptance of the offer to confirm admission within the time stated in the LOI, subject to seat availability."},{"icon":"check","title":"Security Deposit & Refunds","text":"This amount doubles as your refundable security deposit. It will be fully refunded upon graduation, minus any outstanding dues. This amount will also be refunded if you withdraw from the program."}]}', '2026-11-18 06:43:44', '2026-11-18 06:43:51', 'program', 8),
(60, 'feature_list', NULL, NULL, 0, 17, '{"eyebrow":null,"heading":"Education Loan Assistance","body":"Invest in your future with confidence. NAMTECH has partnered with leading banks and education finance providers to make funding your master\u2019s program simple and accessible. Eligible students can avail loans covering up to 100% of tuition, hostel and other education-related expenses, with flexible repayment options and collateral-free schemes available through select partners.","tabs":[{"label":null,"items":[{"icon":"rupee","text":"Loan coverage of up to 100% of the cost of education (including tuition and hostel fees through select lenders)"},{"icon":"check","text":"Collateral-free loan options available for eligible applicants"},{"icon":"calendar","text":"Repayment tenure of up to 15 years"},{"icon":"document","text":"Tax benefits on interest paid under Section 80E"},{"icon":"bank","text":"Partnerships with ICICI Bank, Axis Bank, Credila and EDUAID for streamlined financing support"},{"icon":"people","text":"Dedicated admissions guidance to help students through the loan application process"}]}]}', '2026-11-18 06:43:44', '2026-11-18 06:43:51', 'program', 8),
(61, 'feature_list', NULL, NULL, 0, 18, '{"eyebrow":null,"heading":"Student Life","body":"Students have access to a wide array of campus clubs and societies that shape their perspectives inside and outside the classroom. Some of NAMTECH\u2019s best inventions and collaborations are the result of our clubs and societies.","tabs":[{"label":null,"items":[{"icon":"people","text":"ASM International Club"},{"icon":"people","text":"IEEE (Institute of Electrical and Electronics Engineers) Club"},{"icon":"people","text":"ISTE (Indian Society of Technical Education) Club"},{"icon":"people","text":"NAMTECH 3D Printing Club"},{"icon":"people","text":"NAMTECH Alumni Club"},{"icon":"people","text":"NAMTECH Entrepreneurship and Innovation Club"},{"icon":"people","text":"NAMTECH NSS (National Service Scheme) Club"},{"icon":"people","text":"NAMTECH Sports Club"},{"icon":"people","text":"NAMTECH Sustainability Club"},{"icon":"people","text":"Robotics Club"},{"icon":"people","text":"SAEINDIA (Society of Automotive Engineers) Collegiate Club"},{"icon":"people","text":"SPICES (Scheme for Promoting Interests, Creativity and Ethics) Cultural Club"},{"icon":"people","text":"Stagemaster\u2019s Club"}]}]}', '2026-11-18 06:43:44', '2026-11-18 06:43:51', 'program', 8),
(62, 'testimonials', NULL, 'testimonials', 0, 19, '{"eyebrow":"Student Stories","heading":"Hear From Our Students & Alumni","items":[{"quote":null,"name":"Shanti Priya","role":"Smart Manufacturing Engineer, Germany","image":86},{"quote":null,"name":"Rahul Sharma","role":"Automation & Robotics Specialist","image":55}],"layout":"portrait","body":null,"tone":null}', '2026-11-18 06:43:44', '2026-11-18 06:43:51', 'program', 8),
(63, 'faq', NULL, 'faq', 0, 20, '{"heading":"Frequently Asked Questions","body":null,"items":[{"question":"What is the NAMTECH Master Program in Smart Manufacturing Technology & Management?","answer":"<p>A two-year residential program preparing engineers as techno-managers in smart manufacturing, integrating MIT\u2019s 2.008 hands-on design and manufacturing approach customized for NAMTECH (2.008N) with management depth.<\/p>"},{"question":"What is the eligibility?","answer":"<p>B.E.\/ B.Tech. with minimum 60% in 10th, 12th and graduation, no active backlog. CAT, XAT, GMAT, GRE, or GATE preferred.<\/p>"},{"question":"How is the program delivered?","answer":"<p>On campus at NAMTECH, IIT Gandhinagar, Gujarat, over four 16-week semesters.<\/p>"},{"question":"What are the placement outcomes?","answer":"<p>100% placement for eligible students across previous three batches, with a highest package of \u20b916 LPA and an average of \u20b98.49 LPA.<\/p>"},{"question":"Do I need a background in smart manufacturing to apply?","answer":"<p>No, the program is designed for engineering graduates from electronics, electrical, mechanical, materials, instrumentation and allied disciplines.<\/p>"},{"question":"What is the medium of instruction?","answer":"<p>All instruction, coursework and assessments are conducted in English.<\/p>"},{"question":"Is on-campus accommodation available?","answer":"<p>Yes, the program is residential, with accommodation available on-campus. The details and fees are outlined in the Fees &amp; Scholarship section.<\/p>"},{"question":"Are scholarships available?","answer":"<p>Yes, merit-based scholarships of up to 75% on tuition, based on academic performance, interview and family income.<\/p>"},{"question":"Is a loan facility available?","answer":"<p>Yes, through partnerships with ICICI Bank, Axis Bank, Credila and EDUAID.<\/p>"}],"layout":"centered"}', '2026-11-18 06:43:44', '2026-11-18 06:43:51', 'program', 8),
(64, 'enquiry_form', NULL, 'enquire', 0, 21, '{"heading":"Enquire about this program","body":"Tell us about yourself and our admissions team will get back to you.","form_type":"program","show_contact_details":true}', '2026-11-18 06:43:44', '2026-11-18 06:43:51', 'program', 8),
(65, 'home_hero', NULL, NULL, 1, 0, '{"badges":[{"text":"Make in India"},{"text":"Industry 4.0"},{"text":"Viksit Bharat 2047"}],"slides":[{"title":"Powering India\u2019s Next Manufacturing Revolution","body":"NAMTECH prepares the next generation of innovators who are shaping the future of manufacturing in India.","image":1,"cta_label":null,"cta_url":null}]}', '2026-11-18 06:43:44', '2026-11-18 06:43:44', 'page', 1),
(66, 'feature_blocks', NULL, NULL, 1, 1, '{"eyebrow":"The NAMTECH Learning Model","heading":"A New Blueprint for Manufacturing Education","items":[{"title":"Specialized Labs","body":"Our labs are our classrooms. Students work with specialized, industry-grade equipment, mirroring the environments in which they will work and lead. Studying at NAMTECH is an experience rooted in practice. Students develop their capabilities by applying theoretical concepts and not just knowing them.","image":2,"link_url":"\/academics\/labs-and-infrastructure"},{"title":"Experiential Learning","body":"Learning at NAMTECH is deeply experiential. Through a problem-led approach, students apply concepts in real-world contexts to solve complex problems in modern manufacturing and engineering. Students learn by doing, building, and making.","image":3,"link_url":"\/academics\/pedagogy"},{"title":"Integrated Industry Partnerships","body":"Industry partnerships are the cornerstone of our education model, which goes far beyond textbook scenarios. At NAMTECH, students work on active industrial projects and gain expertise in real manufacturing processes and challenges.","image":67,"link_url":"\/partnerships\/corporate"},{"title":"Industry-Driven Placements","body":"Our placements are aligned with the future of industry, not just the jobs of today. With NAMTECH\u2019s strong industry partnerships, students gain access to elusive career opportunities in advanced manufacturing and technology at leading organizations.","image":4,"link_url":"\/placements"},{"title":"Global Academic Collaboration","body":"At NAMTECH, students are taught by the minds shaping modern manufacturing education. Co-created with global academic institutions and leading industry practitioners, the curriculum is built around real industry scenarios, ensuring graduates are prepared to lead from day one.","image":5,"link_url":"\/partnerships\/academic"},{"title":"Inclusivity","body":"At NAMTECH, world-class manufacturing education is designed to reach talent across every level. Through specialized learning pathways and dedicated programs for undergraduate & postgraduate engineering students, ITI & Diploma holders, faculty, and executives, we cultivate talent that can be deployed across levels of the organization.","image":6,"link_url":"\/school-of-technical-education"}]}', '2026-11-18 06:43:44', '2026-11-18 06:43:44', 'page', 1),
(67, 'academics_tabs', NULL, NULL, 1, 2, '{"eyebrow":"Schools, Centres & Programs","heading":"MET Innovation Schools: Engineering Education for Industry 5.0","schools_label":"MET Innovation Schools","centres_label":"MET Innovation Centers","programs_label":"MET Programs","schools_heading":"MET Innovation Schools: Engineering Education for Industry 5.0","schools_body":"The Manufacturing Engineering Technology (MET) Innovation Schools at NAMTECH prepare graduates to become next-generation industrial and technology leaders. Through an industry-integrated approach, experiential learning, highly practical and specialized education, and applied innovation, each school builds deep expertise in critical domains shaping the future of manufacturing.","centres_heading":"MET Innovation Centers - Shaping Innovation for Industry 5.0","centres_body":"MET Innovation Centers at NAMTECH are built around a simple principle: innovation is best learned by doing. Students work alongside faculty and industry to explore emerging technologies, tackle real-world challenges, and develop practical solutions through applied research, experimentation, and domain-specific programs co-created and co-delivered with industry.","programs_heading":"MET Programs","programs_body":"At NAMTECH, we understand that running the industries of the future will require deep technical and engineering expertise alongside strong leadership capabilities.\n\nThe programs are built in collaboration with industry experts and globally leading institutions, as well as are deeply experiential. This immersive approach helps NAMTECH graduates develop the hands-on expertise and decisive strategic thinking needed to lead tomorrow\u2019s industries and contribute to India\u2019s industrial transformation.","default_tab":"schools","featured_only":false}', '2026-11-18 06:43:44', '2026-11-18 06:43:44', 'page', 1),
(68, 'partners_showcase', NULL, NULL, 1, 3, '{"eyebrow":"Partnerships","heading":"Learning with Leading Global Universities & Industries","body":"Through strategic partnerships with global industry leaders and premier academic institutions, NAMTECH delivers education shaped by real-world insights and advanced technologies. We integrate advanced technologies, experiential learning on industry-grade equipment, and actual industry practices to offer an unparalleled learning experience.","cta_label":null,"cta_url":null,"cta2_label":"Corporate Partnership","cta2_url":"\/partnerships\/corporate","cta3_label":"Academic Partnership","cta3_url":"\/partnerships\/academic","category":null,"show_stories":true,"stories_cta_label":"Read all stories","stories_cta_url":"\/partnerships"}', '2026-11-18 06:43:44', '2026-11-18 06:43:44', 'page', 1),
(69, 'faculty_showcase', NULL, NULL, 1, 4, '{"eyebrow":"Faculty","heading":"Learn from\nGlobal Experts","body":"NAMTECH\u2019s world-class faculty includes leading academicians, industry leaders, and technology experts who bring decades of rich experience and real-world insights into the classroom to shape technically rigorous, industry-ready professionals.","cta_label":"Explore Faculty","cta_url":"\/faculty","school":null}', '2026-11-18 06:43:44', '2026-11-18 06:43:44', 'page', 1),
(70, 'labs_showcase', NULL, NULL, 1, 5, '{"eyebrow":"Labs & Infrastructure","heading":"Next-Gen Labs\n& Facilities","body":"With state-of-the-art infrastructure and experiential labs, students gain hands-on experience on real-industry equipment designed for the future of manufacturing.","cta_label":"Explore More","cta_url":"\/academics\/labs-and-infrastructure","slides":[{"image":10,"caption_start":"Learning with real machines","caption_end":"Into the real world","video_url":null},{"image":11,"caption_start":"Learning with real machines","caption_end":"Into the real world","video_url":null},{"image":21,"caption_start":"Learning with real machines","caption_end":"Into the real world","video_url":null}]}', '2026-11-18 06:43:44', '2026-11-18 06:43:44', 'page', 1),
(71, 'campus_showcase', NULL, NULL, 1, 6, '{"eyebrow":"Campus","heading":"A World-Class Industry-Integrated Campus","body":"Built to replicate the smart manufacturing ecosystems shaping today\u2019s industrial landscape, the NAMTECH campus houses advanced labs, industry-grade equipment, and AI-enabled phygital learning experiences that simulate real industrial environments. The NAMTECH campus embodies MET philosophy \u2014 enabling convergence of technology, academic experience, and industry to make learning deeply applied and relevant.","feature_title":"Advanced Manufacturing Labs & Facilities","feature_body":"This immersive approach enables students to develop hands-on expertise, adapt to evolving technologies and be industry-ready from day one.","gallery":"campus","cta_label":"Explore Campus","cta_url":"\/campus","tour_label":"Virtual tour"}', '2026-11-18 06:43:44', '2026-11-18 06:43:44', 'page', 1),
(72, 'mission', NULL, NULL, 1, 7, '{"heading":"Built to Build India - The 3 Million Mission","body":"NAMTECH is on a movement to work with ITIs across India to prepare a future-ready workforce for the era of advanced manufacturing. We hold a vision to empower 3 million young Indians in Industry 4.0 & 5.0 technologies as well as sustainability imperatives. Through this initiative, we are upgrading ITIs with advanced infrastructure, industry-aligned curricula, and training-the-trainer programs. Combined with mentorship and placement pathways, it is creating a new generation of industry-ready and globally competitive talent.","statistics_group":null,"limit":3,"cta_label":"Join Our Mission","cta_url":"\/school-of-technical-education\/outreach"}', '2026-11-18 06:43:44', '2026-11-18 06:43:44', 'page', 1),
(73, 'news_carousel', NULL, NULL, 1, 8, '{"heading":"News & Insights","post_type":"news","limit":8,"cta_label":"View all insights","cta_url":"\/media"}', '2026-11-18 06:43:44', '2026-11-18 06:43:44', 'page', 1),
(74, 'page_hero', NULL, NULL, 1, 0, '{"eyebrow":"About us","title":"About NAMTECH","body":"New Age Makers\u2019 Institute of Technology (NAMTECH), by ArcelorMittal Nippon Steel India, is India\u2019s first Manufacturing Engineering & Technology institute.","image":89,"cta_label":null,"cta_url":null,"secondary_label":null,"secondary_url":null,"statistics_group":null,"layout":null,"meta":[]}', '2026-11-18 06:43:44', '2026-11-18 06:43:44', 'page', 2),
