(76, 'image_statement', NULL, NULL, 1, 2, '{"eyebrow":null,"heading":"Our Purpose","body":"To empower 3 million youth with advancement in the MET sector and position India as a global hub for manufacturing excellence.","image":90,"position":"right"}', '2026-11-18 06:43:44', '2026-11-18 06:43:44', 'page', 2),
