(78, 'value_list', NULL, NULL, 1, 4, '{"eyebrow":null,"heading":"Our Core Values","body":"An integrated approach combining Manufacturing excellence with cutting-edge digital technologies.","items":[{"icon":"people","title":"Inclusivity & Opportunity","text":"Creating accessible, transformative technical education pathways for youth from all socio-economic backgrounds across India."},{"icon":"gear","title":"Hands-On Applied Learning","text":"Embedding learners directly in living factory simulations and cutting-edge labs where real industry problems are solved."},{"icon":"lightbulb","title":"Industry-Driven Curriculum","text":"Co-designing, co-delivering, and continuously iterating programs in lockstep with the world\u2019s leading industrial enterprises."}]}', '2026-11-18 06:43:44', '2026-11-18 06:43:44', 'page', 2),
(79, 'card_grid', NULL, NULL, 1, 5, '{"eyebrow":"What We Do","heading":"Cultivating Talent for India\u2019s Manufacturing Dominance","body":null,"columns":"4","tone":"white","cards":[{"icon":"people","title":"Transforming India\u2019s Technician Workforce","body":null,"link_url":null},{"icon":"robot","title":"Experiential Learning Through Advanced Technology","body":null,"link_url":null},{"icon":"factory","title":"Industry-integrated, applied learning models","body":null,"link_url":null},{"icon":"globe","title":"Scaling Skills Access Across India","body":null,"link_url":null}],"style":"joined","cta_label":null,"cta_url":null}', '2026-11-18 06:43:44', '2026-11-18 06:43:44', 'page', 2),
(80, 'timeline', NULL, NULL, 1, 6, '{"eyebrow":null,"heading":"Our Story","body":null,"items":[{"year":"2022","title":"June, 2022","text":"NAMTECH received the Letter of Intent from the University Grants Commission, marking a key step towards recognition as a Deemed-to-be-University.","image":92},{"year":"2023","title":"2023","text":"Inaugural cohort of International Professional Technologist Program (iPTP) commenced with 100% placement track record.","image":93},{"year":"2024","title":"2024","text":"Launched the School of Smart Manufacturing and state-of-the-art experiential learning labs in collaboration with global industry partners.","image":94},{"year":"2025","title":"2025","text":"Expanded academic and research partnerships with world-renowned technical institutes including TUM Asia and IIT Roorkee.","image":95},{"year":"2026","title":"2026","text":"Pioneering the future of manufacturing education with next-generation living labs and comprehensive industry co-creation.","image":55}]}', '2026-11-18 06:43:44', '2026-11-18 06:43:44', 'page', 2),
(81, 'video_feature', NULL, NULL, 1, 7, '{"layout":"split","eyebrow":null,"heading":"Created to aid India\u2019s growth and development.","body":"New Age Makers\u2019 Institute of Technology (NAMTECH), by ArcelorMittal Nippon Steel India, is India\u2019s first Manufacturing Engineering & Technology institute. It supports \u2018Make in India\u2019 and \u2018Viksit Bharat 2047\u2019 by offering advanced engineering programs and promoting responsible technology. NAMTECH prepares young professionals with Industry 4.0 skills and training.","name":null,"role":null,"image":93,"video_url":null}', '2026-11-18 06:43:44', '2026-11-18 06:43:44', 'page', 2),
(82, 'intro', NULL, NULL, 1, 8, '{"eyebrow":"About the Founder","heading":"About the Founder: AM\/NS India","body":"<p>ArcelorMittal Nippon Steel India (AM\/NS India) is an integrated flat carbon steel manufacturer with an ambition to drive modern industrial growth. As the founding partner of NAMTECH, AM\/NS India is committed to building a world-class manufacturing ecosystem in India through education, cutting-edge technology, and skilled talent. Created to aid India''s growth and development, this partnership ensures education is aligned directly with industrial excellence.<\/p>","cta_label":null,"cta_url":null,"icon":null,"tone":null}', '2026-11-18 06:43:44', '2026-11-18 06:43:44', 'page', 2),
(83, 'cta_band', NULL, NULL, 1, 9, '{"heading":"Have Questions? Get in touch with us","body":"We partner with the best of industry, academia, and technology to co-create curriculum and align training with workforce needs. Partner with us to shape a skilled workforce for India\u2019s future.","cta_label":"Contact us","cta_url":"\/contact","tone":null}', '2026-11-18 06:43:44', '2026-11-18 06:43:44', 'page', 2),
