(99, 'intro', NULL, NULL, 1, 2, '{"eyebrow":null,"heading":"Ranks & Accreditations","body":"<p>NAMTECH is recognized by premier regulatory and academic bodies in India and globally, holding Letters of Intent, university affiliations, and global certifications that attest to our world-class educational standards. Our programs and platforms are benchmarked against international standards from MIT, TUM Asia, and WorldSkills.<\/p>","cta_label":null,"cta_url":null,"icon":"award","tone":null}', '2026-11-18 06:43:45', '2026-11-18 06:43:45', 'page', 7),
(100, 'page_hero', NULL, NULL, 1, 0, '{"eyebrow":"Academics","title":"Transforming Education Through Innovation & Industry Integration","body":null,"image":100,"cta_label":null,"cta_url":null,"secondary_label":null,"secondary_url":null,"statistics_group":null,"layout":null,"meta":[]}', '2026-11-18 06:43:45', '2026-11-18 06:43:45', 'page', 8);
INSERT INTO `page_sections` VALUES
(101, 'intro', NULL, NULL, 1, 1, '{"eyebrow":null,"heading":"Our Educational Philosophy","body":"<p>We believe engineering education must be rooted in active practice. Our problem-led pedagogy places learners directly in simulated factory environments and state-of-the-art labs, ensuring they build, test, and iterate with real industry machines rather than passive textbook learning.<\/p>","cta_label":null,"cta_url":null,"icon":"lightbulb","tone":null}', '2026-11-18 06:43:45', '2026-11-18 06:43:45', 'page', 8),
(102, 'media_cards', NULL, NULL, 1, 2, '{"eyebrow":null,"heading":"Our Learning Model","body":null,"items":[{"image":98,"logo":null,"icon":"graduation","tag":null,"date":null,"title":"Competency-Based Learning","subtitle":null,"body":"We focus on mastering skills, not just completing courses. Learners progress through personalized pathways, acquiring technical, professional, and leadership competencies at their own pace. This ensures deep understanding, measurable skill development, and real-world readiness.","meta":null,"link_url":null},{"image":99,"logo":null,"icon":"gear","tag":null,"date":null,"title":"Project-Based Learning","subtitle":null,"body":"Every learner solves real-world problems through hands-on projects co-designed with industry partners. This immersive approach bridges theory with practice and transforms learners into solution-oriented technologists capable of delivering impact from day one.","meta":null,"link_url":null},{"image":94,"logo":null,"icon":"award","tag":null,"date":null,"title":"Competition-Based Learning","subtitle":null,"body":"To spark innovation and critical thinking, learners engage in challenges and competitions that mirror global industry scenarios. These experiences encourage healthy competition, collaboration, and creativity-pushing learners to raise the bar continuously.","meta":null,"link_url":null}],"layout":"horizontal","tone":null,"cta_label":null,"cta_url":null,"footer_label":null,"footer_url":null,"card_link_label":null}', '2026-11-18 06:43:45', '2026-11-18 06:43:45', 'page', 8),
(103, 'academics_tabs', NULL, NULL, 1, 3, '{"eyebrow":"Schools, Centres, and Programs","heading":"NAMTECH\u2019s Innovation Schools for the Future of Manufacturing","schools_label":"Schools","centres_label":"Centres","programs_label":"Programs","schools_heading":null,"schools_body":null,"centres_heading":null,"centres_body":null,"programs_heading":null,"programs_body":null,"default_tab":"schools","featured_only":false}', '2026-11-18 06:43:45', '2026-11-18 06:43:45', 'page', 8),
