(115, 'page_hero', NULL, NULL, 1, 0, '{"eyebrow":"Labs & Infrastructure","title":"Additive Manufacturing & Precision Engineering Lab","body":"NAMTECH\u2019s Additive Manufacturing & Precision Engineering Lab features industrial-grade 3D printers, SLA technologies, and metal additive manufacturing systems, enabling students and industry partners to rapidly prototype, test, and manufacture complex industrial components with micrometer precision.","image":85,"cta_label":null,"cta_url":null,"secondary_label":null,"secondary_url":null,"statistics_group":null,"layout":"plain","meta":[]}', '2026-11-18 06:43:46', '2026-11-18 06:43:46', 'page', 11),
