(117, 'card_grid', NULL, NULL, 1, 2, '{"eyebrow":null,"heading":"Why Is It Important?","body":null,"columns":"3","tone":"white","cards":[{"icon":"bolt","title":"Rapid prototyping","body":"Learn by engaging with faculty, peers, and live challenges that mirror real-world decision-making.","link_url":null},{"icon":"gear","title":"Mass customization","body":"Learning happens by building. At NAMTECH, classrooms don\u2019t have desks but machines used in the industry.","link_url":null},{"icon":"leaf","title":"Waste reduction","body":"Our curriculum is co-designed and co-delivered with academicians from global universities.","link_url":null},{"icon":"flask","title":"Education and research","body":null,"link_url":null},{"icon":"globe","title":"Sustainability","body":null,"link_url":null}],"style":"joined","cta_label":null,"cta_url":null}', '2026-11-18 06:43:46', '2026-11-18 06:43:46', 'page', 11),
