(124, 'media_cards', NULL, NULL, 1, 4, '{"eyebrow":"Living Labs","heading":"World-Class Labs & Infrastructure","body":"With state-of-the-art infrastructure and experiential labs, students gain hands-on experience on real-industry equipment designed for the future of manufacturing.","items":[{"image":33,"logo":null,"icon":null,"tag":null,"date":null,"title":"Sustainable Energy Labs","subtitle":null,"body":"Work on real-world renewable systems, from generation to consumption, using IoT-driven optimisation.","meta":null,"link_url":null},{"image":83,"logo":null,"icon":null,"tag":null,"date":null,"title":"Hydrogen Innovation Lab","subtitle":null,"body":"Explore the full hydrogen ecosystem, from production to storage to fuel cell applications.","meta":null,"link_url":null},{"image":84,"logo":null,"icon":null,"tag":null,"date":null,"title":"Water Stewardship Lab","subtitle":null,"body":"Solve water challenges through smart monitoring, filtration, and climate-resilient systems.","meta":null,"link_url":null},{"image":35,"logo":null,"icon":null,"tag":null,"date":null,"title":"Smart Grid & Energy Systems Lab","subtitle":null,"body":"Build and optimise intelligent energy networks with automation, efficiency, and grid analytics.","meta":null,"link_url":null},{"image":82,"logo":null,"icon":null,"tag":null,"date":null,"title":"ESG Analytics Lab","subtitle":null,"body":"Turn sustainability data into action using reporting tools, automation, and compliance frameworks.","meta":null,"link_url":null},{"image":78,"logo":null,"icon":null,"tag":null,"date":null,"title":"Urban Digitalisation Lab","subtitle":null,"body":"Use AI, IoT, and data to design smarter, more efficient urban environments.","meta":null,"link_url":null}],"layout":"tall","tone":null,"cta_label":"Explore Labs","cta_url":"\/academics\/labs-and-infrastructure","footer_label":null,"footer_url":null,"card_link_label":null}', '2026-11-18 06:43:46', '2026-11-18 06:43:46', 'page', 12),
(125, 'faq', NULL, NULL, 1, 5, '{"heading":"Frequently Asked Questions","body":"Find answers to common questions about our academic programs, admissions process, and career pathways.","items":[{"question":"What makes NAMTECH\u2019s undergraduate programs different from traditional B.Tech degrees?","answer":"<p>NAMTECH\u2019s B.Tech programs are built on an experiential, 100% applied learning model. Instead of passive lecture-based instruction, learners spend extensive hours in living factories, collaborative robotics cells, and simulation environments solving real industry challenges.<\/p>"},{"question":"How does the industry co-creation model work?","answer":"<p>Our curricula are co-designed and co-delivered with global manufacturing giants including ArcelorMittal Nippon Steel India, Siemens, Cisco, and Schneider Electric, ensuring skills match exact operational requirements.<\/p>"},{"question":"Are scholarships available for undergraduate and master programs?","answer":"<p>Yes. The India MET Scholarship program offers up to 75% fee waivers for women candidates, GATE\/INI qualifiers, and merit-cum-means applicants across all eligible degree tracks.<\/p>"},{"question":"What is the placement record of NAMTECH graduates?","answer":"<p>NAMTECH maintains a 100% placement track record with an average CTC of \u20b912 LPA and highest offers reaching \u20b924 LPA from top multinational industrial leaders.<\/p>"}],"layout":"centered"}', '2026-11-18 06:43:46', '2026-11-18 06:43:46', 'page', 12),
(126, 'cta_band', NULL, NULL, 1, 6, '{"heading":"Have Questions? Get in touch with us","body":"We partner with the best of industry, academia, and technology to co-create curriculum and align training with workforce needs. Partner with us to shape a skilled workforce for India\u2019s future.","cta_label":"Contact us","cta_url":"\/contact","tone":null}', '2026-11-18 06:43:46', '2026-11-18 06:43:46', 'page', 12),
