(129, 'media_cards', NULL, NULL, 1, 2, '{"eyebrow":"Academic Schools","heading":"MET Innovation Schools","body":"Each school converges core engineering disciplines with smart technologies, offering hands-on learning inside state-of-the-art labs.","items":[{"image":7,"logo":null,"icon":null,"tag":null,"date":null,"title":"School of Manufacturing Technologies (SoMT)","subtitle":null,"body":"Equips engineers to operate, optimize, and revolutionize modern production environments across CNC machining, lean manufacturing, IoT, and digital manufacturing.","meta":null,"link_url":"\/schools\/school-of-manufacturing-technologies"},{"image":3,"logo":null,"icon":null,"tag":null,"date":null,"title":"School of Manufacturing Design & AI (SoMDAI)","subtitle":null,"body":"Converges product innovation, digital engineering, and intelligent manufacturing across generative design, simulation, and semiconductor tech.","meta":null,"link_url":"\/schools\/school-of-manufacturing-design-ai"},{"image":10,"logo":null,"icon":null,"tag":null,"date":null,"title":"School of Robotics (SoR)","subtitle":null,"body":"Designs, programs, and deploys intelligent automation systems, cobots, and mechatronics in industry-grade automation cells.","meta":null,"link_url":"\/schools\/school-of-robotics"},{"image":11,"logo":null,"icon":null,"tag":null,"date":null,"title":"School of Sustainability (SoS)","subtitle":null,"body":"Accelerates India\u2019s transition to clean energy, circular economy models, and sustainable industrial growth through living labs.","meta":null,"link_url":"\/schools\/school-of-sustainability"}],"layout":"tall","tone":null,"cta_label":null,"cta_url":null,"footer_label":null,"footer_url":null,"card_link_label":"Explore School"}', '2026-11-18 06:43:46', '2026-11-18 06:43:46', 'page', 13),
(130, 'media_cards', NULL, NULL, 1, 3, '{"eyebrow":"Centers of Excellence","heading":"MET Innovation Centres","body":null,"items":[{"image":2,"logo":null,"icon":null,"tag":null,"date":null,"title":"Center of Excellence in Automotive Engineering","subtitle":null,"body":"Focal point for research and skill-building across electric vehicles, alternate fuels, ADAS, and vehicle electrification.","meta":null,"link_url":"\/centres\/coe-in-automotive-engineering"},{"image":21,"logo":null,"icon":null,"tag":null,"date":null,"title":"Center of Advanced Computing & AI (CoACAI)","subtitle":null,"body":"Hub for innovation and research in data science, generative AI, computer vision, and AI-driven industrial robotics.","meta":null,"link_url":"\/centres\/centre-of-advanced-computing-ai"},{"image":20,"logo":null,"icon":null,"tag":null,"date":null,"title":"Experiential Learning Center for Sustainable Energy & Circularity","subtitle":null,"body":"Joint initiative of NTPC, IIT Roorkee, and NAMTECH pioneering clean energy transition and sustainable manufacturing.","meta":null,"link_url":"\/centres\/experiential-learning-center-for-sustainable-energy-circularity"}],"layout":"tall","tone":"light","cta_label":null,"cta_url":null,"footer_label":null,"footer_url":null,"card_link_label":"Explore Centre"}', '2026-11-18 06:43:46', '2026-11-18 06:43:46', 'page', 13),
