(139, 'card_grid', NULL, NULL, 1, 2, '{"eyebrow":"Student Innovations","heading":"Student Accolades & Competitions","body":null,"columns":"3","tone":"white","cards":[{"icon":"award","title":"IndiaSkills Regional Champions 2025","body":"NAMTECH student technologists secured top podium finishes in CNC Machining, Industrial Robotics, and Mechatronics.","link_url":null},{"icon":"lightbulb","title":"National Smart Manufacturing Hackathon","body":"First prize awarded to student teams for deploying an AI-driven digital twin reducing machine downtime by 24%.","link_url":null},{"icon":"globe","title":"WorldSkills International Participation","body":"Student representatives selected to train alongside global technical competitors in precision automation.","link_url":null}],"style":"joined","cta_label":null,"cta_url":null}', '2026-11-18 06:43:46', '2026-11-18 06:43:46', 'page', 15),
