(141, 'page_hero', NULL, NULL, 1, 0, '{"eyebrow":"Scholarships","title":"India MET Scholarship Program","body":"The world is being rebuilt by smart factories, intelligent machines, and the makers who drive them. India intends to lead that world. The NAMTECH India MET Scholarship program exists to enable you to access world-class education and become the driving force behind the future of manufacturing and technology.","image":65,"cta_label":"Apply for Scholarship","cta_url":"\/admissions#enquire","secondary_label":null,"secondary_url":null,"statistics_group":null,"layout":null,"meta":[]}', '2026-11-18 06:43:46', '2026-11-18 06:43:46', 'page', 16),
