(144, 'eligibility', NULL, NULL, 1, 3, '{"eyebrow":null,"heading":"Eligibility Criteria","body":null,"criteria":[{"text":"Currently pursuing or completed B.Tech, B.E., or M.Tech from a recognized university."},{"text":"Minimum 60% aggregate marks in 10th standard, 12th standard, and graduation."},{"text":"Shortlisted candidates must clear the NAMTECH Design & Aptitude Interview."}],"list_heading":null,"items":[]}', '2026-11-18 06:43:46', '2026-11-18 06:43:46', 'page', 16),
