(147, 'page_hero', NULL, NULL, 1, 0, '{"eyebrow":"Admissions","title":"Admissions: Undergraduate","body":"NAMTECH\u2019s School of Sustainability drives Energy and Circularity to accelerate the MET sector toward clean, decarbonized futures. Blending modern science with India\u2019s resourceful ethos, it delivers hands-on learning that creates real-world impact.","image":65,"cta_label":"Apply Now","cta_url":"#enquire","secondary_label":"Contact Us","secondary_url":"\/contact","statistics_group":null,"layout":null,"meta":[]}', '2026-11-18 06:43:46', '2026-11-18 06:43:46', 'page', 17),
