(149, 'date_tables', NULL, NULL, 1, 2, '{"eyebrow":null,"heading":"Important Dates & Deadlines","body":null,"columns":[{"icon":"calendar","title":"Applications Deadlines","highlight":true,"rows":[{"label":"Round 1","value":"Jan 11, 2026"},{"label":"Round 2","value":"Feb 8, 2026"},{"label":"Round 3","value":"Mar 8, 2026"},{"label":"Round 4","value":"Apr 5, 2026"}]},{"icon":"people","title":"Tentative Interview Dates","highlight":false,"rows":[{"label":"Round 1","value":"3rd week of Apr"},{"label":"Round 2","value":"3rd week of Apr"},{"label":"Round 3","value":"3rd week of Apr"},{"label":"Round 4","value":"3rd week of Apr"}]},{"icon":"document","title":"Offer Roll-Out","highlight":false,"rows":[{"label":"Rounds 1 \u2013 4","value":"4th week of Apr"}]}],"footnote":"* Round 5 deadlines would be based on available seats."}', '2026-11-18 06:43:46', '2026-11-18 06:43:46', 'page', 17),
(150, 'eligibility', NULL, NULL, 1, 3, '{"eyebrow":null,"heading":"Eligibility Criteria","body":null,"criteria":[{"text":"Candidate with B.E.\/B.Tech., minimum 60% in 10th, 12th, graduation or equivalent CGPA from recognized Indian university. No active backlog."},{"text":"A score in CAT\/XAT\/GMAT\/GRE\/GATE is preferred."},{"text":"Open school students are not eligible."}],"list_heading":"Eligible Engineering Branches","items":[{"icon":"gear","text":"Mechanical Engineering"},{"icon":"bolt","text":"Electrical Engineering"},{"icon":"chip","text":"Electronics Engineering"},{"icon":"code","text":"Computer Science Engineering"},{"icon":"factory","text":"Industrial Engineering"},{"icon":"flask","text":"Material Science Engineering"},{"icon":"gear","text":"Automobile Engineering"},{"icon":"chart","text":"Data Science & AI"},{"icon":"drone","text":"Aeronautical Engineering"},{"icon":"magnet","text":"Instrumentation & Control Engineering"}]}', '2026-11-18 06:43:46', '2026-11-18 06:43:46', 'page', 17);
