(151, 'steps', NULL, NULL, 1, 4, '{"eyebrow":null,"heading":"Admission Process","body":"Your journey to becoming a sustainability leader starts here. A clear, fast-tracked process designed to identify thinkers, builders.","image":64,"items":[{"title":"Apply online at admissions.namtech.ac & pay Rs. 1000 application fee.","body":null},{"title":"Fill out the application form and submit with all the documents.","body":null},{"title":"Your application will be reviewed; if shortlisted, appear for an interview.","body":null},{"title":"If selected, you will receive the admission offer letter.","body":null},{"title":"Confirm your admission by timely payment of tuition & hostel fees as specified.","body":null}],"layout":"panel","panel_title":"Steps"}', '2026-11-18 06:43:46', '2026-11-18 06:43:46', 'page', 17),
(152, 'checklist_cards', NULL, NULL, 1, 5, '{"eyebrow":null,"heading":"Required Documents","body":null,"tone":"light","cards":[{"icon":"document","title":"Statement of purpose","items":[{"text":"Personal essay (500-1000 words)"},{"text":"Career goals & aspirations"},{"text":"Why NAMTECH"}]},{"icon":"graduation","title":"Academic Transcripts","items":[{"text":"10th & 12th mark sheets"},{"text":"Graduation degree & transcripts"},{"text":"Post-graduation (if applicable)"}]},{"icon":"id","title":"ID Proof","items":[{"text":"Aadhar Card"},{"text":"PAN Card"},{"text":"Passport size photographs"},{"text":"Domicile certificate"}]},{"icon":"portfolio","title":"Additional Documents","items":[{"text":"Entrance exam scorecard"},{"text":"Work experience certificates"},{"text":"Portfolio (for design\/marketing)"}]}]}', '2026-11-18 06:43:46', '2026-11-18 06:43:46', 'page', 17),
(153, 'fees', NULL, NULL, 1, 6, '{"eyebrow":null,"heading":"Fees and Scholarships","body":"Access World-Class Learning Without Barriers","fee_label":"Program Fee","fee_amount":"Rs. 4,50,000","rows":[{"label":"Tuition Fee","value":"Rs. 2,50,000"},{"label":"Accommodation, food, transport","value":"Rs. 2,00,000"},{"label":"Total fees","value":"Rs. 4,50,000"}],"scholarships_title":"Scholarships","scholarships":[{"title":"Tuition Fee Scholarship","text":"Up to 100% fee waiver based on academic and professional achievements"},{"title":"Accommodation, food and transport","text":"93% off for Females \u00b7 85% off for Males"},{"title":"Fees Payable (after Scholarship)","text":"Rs. 15,000 for Females \u00b7 Rs. 30,000 for Males"},{"title":"Merit-Based Scholarships","text":"Up to 100% fee waiver for students with exceptional records."},{"title":"Women in Leadership","text":"Grants cover up to 93% off accommodation, food, and transport for female candidates."},{"title":"INI-Based Awards","text":"Financial aid for graduates from Institutes of National Importance."}],"link_label":"Learn about scholarships","link_url":"#faq","notes":[{"icon":"bank","title":"Security deposit","text":"Rs. 5,000 at admission (refundable at Program end)"},{"icon":"calendar","title":"Payment Schedule","text":"First instalment before commencement of classes. Second instalment at the end of Semester 2"},{"icon":"check","title":"Inclusions","text":"Tuition, accommodation, food, and transport included"}]}', '2026-11-18 06:43:46', '2026-11-18 06:43:46', 'page', 17),
(154, 'feature_list', NULL, NULL, 1, 7, '{"eyebrow":null,"heading":"Education Loan Assistance","body":"Loan partners: EduAID, Axis Bank, Credila and ICICI Bank.","tabs":[{"label":null,"items":[{"icon":"bank","text":"Multi-bank education loan aggregator and facilitation support"},{"icon":"rupee","text":"Up to 100% coverage of tuition, hostel, and total education cost"},{"icon":"calendar","text":"Flexible repayment tenure up to 15 yrs, with Interest rates starting at 9.8% and processing fee between 0.5 - 2%"},{"icon":"building","text":"Direct disbursement to the university (as per admission letter)"},{"icon":"document","text":"Tax benefits on interest paid under Section 80(E)"},{"icon":"check","text":"Collateral-free loan options available"}]}]}', '2026-11-18 06:43:46', '2026-11-18 06:43:46', 'page', 17),
(155, 'contact_cards', NULL, NULL, 1, 8, '{"eyebrow":null,"heading":"Meet the NAMTECH Team in Your City","body":null,"items":[{"region":"Bihar, Jharkhand, Odisha, West Bengal and Karnataka","name":"Rakesh Tiwari","phone":null,"email":"rakesh.tiwari@namtech.ac"}]}', '2026-11-18 06:43:46', '2026-11-18 06:43:46', 'page', 17),
(156, 'faq', NULL, 'faq', 1, 9, '{"heading":"Frequently Asked Questions","body":"Find answers to common questions about the Program, admissions, and student life.","items":[{"question":"What are the eligibility criteria for admission?","answer":"<p>Candidates with a B.E.\/B.Tech. degree in relevant engineering disciplines with a minimum of 60% marks or equivalent CGPA are eligible to apply. Final year engineering students awaiting results are also eligible to apply conditionally.<\/p>"},{"question":"Is work experience required for this program?","answer":"<p>Work experience is not mandatory. Both fresh engineering graduates and working professionals with up to 3 years of industry experience are encouraged to apply.<\/p>"},{"question":"What is the placement record?","answer":"<p>NAMTECH has achieved a 100% placement track record for its cohorts, with an average salary package of \u20b912 LPA and highest offers up to \u20b924 LPA from top industrial recruiters like AM\/NS India, Siemens, Schneider Electric, and global manufacturing OEMs.<\/p>"},{"question":"Are there opportunities for international exposure?","answer":"<p>Yes, through our academic collaborations with premier institutions like TUM Asia (Technical University of Munich) and global industry partners, students gain international curriculum exposure, guest lectures, and opportunities for global industry residencies.<\/p>"},{"question":"What kind of projects will I work on?","answer":"<p>Students engage in hands-on industry capstone projects, living lab simulations, robotics automation cells, digital twin deployments, and real problem briefs sourced directly from manufacturing partners.<\/p>"},{"question":"How are scholarships awarded?","answer":"<p>Merit-based scholarships of up to 30% to 75% fee waivers are available for high-achieving applicants, women in manufacturing (WiM), and graduates from Institutes of National Importance (INIs).<\/p>"},{"question":"What support is available for accommodation?","answer":"<p>NAMTECH provides comprehensive residential housing facilities with modern amenities, study areas, dining, Wi-Fi, and dedicated campus shuttle connectivity in Gandhinagar.<\/p>"},{"question":"Can I pursue specializations within the program?","answer":"<p>Yes, learners can select electives and specialization tracks in cutting-edge domains such as Smart Automation, Robotics &amp; AI, Additive Manufacturing, and Sustainable Energy Systems.<\/p>"}],"layout":"centered"}', '2026-11-18 06:43:46', '2026-11-18 06:43:46', 'page', 17),
(157, 'enquiry_form', NULL, 'enquire', 1, 10, '{"heading":"Program enquiry","body":"Tell us which program you are interested in and our admissions team will get back to you.","form_type":"program","show_contact_details":true}', '2026-11-18 06:43:46', '2026-11-18 06:43:46', 'page', 17),
(158, 'page_hero', NULL, NULL, 1, 0, '{"eyebrow":"Partnerships","title":"Built with Industry. Backed by Global Expertise.","body":"Through strategic partnerships with global industry leaders and premier academic institutions, NAMTECH delivers education shaped by real-world challenges and advanced technologies.","image":5,"cta_label":null,"cta_url":null,"secondary_label":null,"secondary_url":null,"statistics_group":null,"layout":null,"meta":[]}', '2026-11-18 06:43:46', '2026-11-18 06:43:46', 'page', 18),
(159, 'logo_strip', NULL, NULL, 1, 1, '{"heading":"Our partners","category":null,"tone":null}', '2026-11-18 06:43:46', '2026-11-18 06:43:46', 'page', 18),
(160, 'media_cards', NULL, NULL, 1, 2, '{"eyebrow":null,"heading":"Collaboration for a Cause: Meet our Industry Partners","body":"Our curriculum is co-designed with leading organizations to align with evolving workforce needs and integrate Industry 4.0 standards, advanced tools, and emerging practices. These collaborations provide students with hands-on experience, expert mentorship, and strong placement opportunities.","items":[{"image":8,"logo":29,"icon":null,"tag":null,"date":null,"title":"Siemens","subtitle":null,"body":"Our collaboration with Siemens aims to revolutionize education in smart manufacturing, automation, and advanced technical education. It brings cutting-edge industry expertise and hands-on industry training into our academic framework.","meta":null,"link_url":null},{"image":21,"logo":26,"icon":null,"tag":null,"date":null,"title":"Cisco","subtitle":null,"body":"Cisco is a global leader in networking and technology solutions. Our collaboration enhances NAMTECH\u2019s academic Programs by bringing in the expertise and industry-relevant education in manufacturing technologies and digital innovation.","meta":null,"link_url":null}],"layout":"logo","tone":null,"cta_label":null,"cta_url":null,"footer_label":null,"footer_url":null,"card_link_label":null}', '2026-11-18 06:43:46', '2026-11-18 06:43:46', 'page', 18),
(161, 'partners_showcase', NULL, NULL, 1, 3, '{"eyebrow":"Partner stories","heading":"Learning with the World\u2019s Leading Universities and Industries.","body":"Our partnerships bring global expertise into the classroom. It integrates cutting-edge research, advanced technologies, and real industry practices into the learning experience.","cta_label":null,"cta_url":null,"cta2_label":null,"cta2_url":null,"cta3_label":null,"cta3_url":null,"category":null,"show_stories":true,"stories_cta_label":null,"stories_cta_url":null}', '2026-11-18 06:43:46', '2026-11-18 06:43:46', 'page', 18),
(162, 'cta_band', NULL, NULL, 1, 4, '{"heading":"Co-Create With Us","body":"We partner with the best of industry, academia, and technology to co-create curriculum and align training with workforce needs. Partner with us to shape a skilled workforce for India\u2019s future.","cta_label":"Partner with us","cta_url":"#enquiry:partnership","tone":"lavender"}', '2026-11-18 06:43:46', '2026-11-18 06:43:46', 'page', 18),
(163, 'page_hero', NULL, NULL, 1, 0, '{"eyebrow":"Corporate Partnerships","title":"A Collaborative Platform for Industry Leaders Powering Manufacturing Innovation","body":"India\u2019s leadership in Manufacturing Engineering Technology (MET) is being driven by next generation professionals who are industry-ready and globally competitive. As a first-of-its-kind industry-academia institution, NAMTECH is bringing together industry pioneers and policymakers to build talent through co-created curricula, world-class infrastructure and industry-first learning. This mission is made possible by partners with a shared belief that the future of engineering education is built through collaboration.","image":64,"cta_label":"Partner with us","cta_url":"#enquiry:partnership","secondary_label":null,"secondary_url":null,"statistics_group":null,"layout":null,"meta":[]}', '2026-11-18 06:43:47', '2026-11-18 06:43:47', 'page', 19),
(164, 'stat_cards', NULL, NULL, 1, 1, '{"eyebrow":null,"heading":"Here\u2019s Why Leading Corporates Build with NAMTECH","body":"India stands at a defining moment in its manufacturing journey. NAMTECH offers industry partners a structured ecosystem to capitalize on this shift across three industrial opportunity areas.","tone":"lavender","items":[{"icon":"trend","value":"25%","label":"Manufacturing Contribution to India\u2019s GDP (GDP Acceleration)","text":"The national drive to scale manufacturing from 17% to 25% of GDP requires unprecedented demand for advanced manufacturing talent, innovation and industry-academia collaboration."},{"icon":"people","value":"65%","label":"Of India\u2019s Population is Below 35 Years of Age (Demographic Edge)","text":"Harnessing the world\u2019s largest demographic needs future-ready engineering education designed to empower modern manufacturing workforces with cutting-edge technical and digital skills."},{"icon":"leaf","value":"$10 Trillion","label":"Opportunity in India\u2019s Green Transition (Sustainable Development)","text":"The shift toward sustainable growth and net-zero manufacturing produces new pathways for industrial innovation and clean energy leadership and presents a new model of development."}]}', '2026-11-18 06:43:47', '2026-11-18 06:43:47', 'page', 19),
(165, 'tabs_media', NULL, NULL, 1, 2, '{"eyebrow":"Partnership Opportunities","heading":"Explore Partnership Opportunities at NAMTECH","body":"Partner with NAMTECH to create impact at scale. From establishing world-class laboratories, centers of excellence and academic infrastructure to empowering students through scholarships, NAMTECH offers diverse avenues for organizations to co-create a thriving manufacturing talent development ecosystem.","tone":null,"tabs":[{"label":"Strategic & Founding Partnership","image":89,"title":"Strategic & Founding Partnership","text":"Strategic and Founding Partnerships are NAMTECH\u2019s highest-tier of partnerships, built exclusively for organizations committed to shaping the future of engineering education in India.","points":[{"title":"Infrastructure Development","text":null},{"title":"Outreach","text":null},{"title":"Endowments","text":null}],"links":[{"label":"Explore more","url":"\/partnerships\/corporate\/strategic-and-founding-partnerships"}]},{"label":"Schools, Centers, CoEs & Lab Partnerships","image":35,"title":"Schools, Centers, CoEs & Lab Partnerships","text":"School & center partners play a defining role in shaping NAMTECH\u2019s engineering education model. From program design and delivery to its continuous evolution, working with our partners ensures that every school, lab and center is cutting-edge and aligned with the changing needs of industry.","points":[{"title":"School-level Partnerships","text":null},{"title":"Center and CoE Partnerships","text":null},{"title":"Lab Partnerships","text":null}],"links":[{"label":"Explore more","url":"\/partnerships\/corporate\/schools-centers-coes-and-lab-partnerships"}]},{"label":"Sponsored Research","image":83,"title":"Sponsored Research","text":"Our sponsored research model allows industry leaders to pilot and scale targeted research programs, access global faculty expertise and co-develop intellectual property in a collaborative and structurally sound framework.","points":[{"title":"Directed Research Projects","text":null},{"title":"Faculty Exchange & Collaborative Research","text":null},{"title":"Research Chairs & Long-Term Programs","text":null}],"links":[{"label":"Explore more","url":"\/partnerships\/corporate\/sponsored-research"}]}]}', '2026-11-18 06:43:47', '2026-11-18 06:43:47', 'page', 19),
(166, 'faq', NULL, 'industry-partners', 1, 3, '{"heading":"Meet our Industry Partners","body":null,"items":[{"question":"Siemens","answer":"<p>NAMTECH has forged a strategic partnership with Siemens to revolutionize education in smart manufacturing, automation, and advanced technical education. This collaboration aims to integrate cutting-edge industry expertise into NAMTECH\u2019s academic framework, introducing new electives and dedicated courses within the Master\u2019s, Executive and iPTP programmes.<\/p><p>The partnership emphasizes experiential learning, hands-on industry training, and the co-development of dynamic course curricula. A key highlight is the establishment of a robust industry attachment programme for both faculty and students, fostering deeper industry-academic integration.<\/p><p>Additionally, NAMTECH and Siemens will collaborate on developing state-of-the-art infrastructure, creating continuous knowledge-sharing platforms, and designing advanced learning modules to prepare learners for the challenges of Industry 4.0 and beyond.<\/p><p>Through this partnership, NAMTECH and Siemens are shaping a future-ready workforce equipped with the skills and expertise to drive innovation in manufacturing and automation.<\/p>"},{"question":"ABB","answer":"<p>NAMTECH and ABB have partnered to create a School of Robotics, setting a benchmark in robotics and automation education in India.<\/p><p>This visionary collaboration bridges the education gap in automation, advancing robotics skills and fostering seamless industry integration.<\/p><p>At the NAMTECH School of Robotics, ABB Robotics will play a pivotal role in designing, supporting, and executing various programmes. The programmes will be hands-on and industry-focused, supported by world-class infrastructure and guided by global industry leaders like ABB. The goal is to cultivate a highly skilled talent pool for the industrial sector, ensuring students are ready to meet the demands of a rapidly evolving technological landscape.<\/p><p>ABB\u2019s robotics experts will drive knowledge-sharing initiatives, spearhead cutting-edge research, and facilitate immersive industry exposure, offering unparalleled opportunities for students to gain practical expertise.<\/p><p>In 2023, India achieved a new milestone with the installation of 8,510 industrial robots, a 59% increase from the previous year. This growth positions India as the seventh-largest global market for annual robot installations and underscores its burgeoning potential in automation. As this trend accelerates through 2024 and 2025, job opportunities in the robotics sector are booming, particularly in roles such as Robotics Engineers, Robot Design Engineers, Application Engineers, and Smart Factory Designers.<\/p><p>With ABB\u2019s partnership, NAMTECH is at the forefront of shaping the future of robotics education and driving India\u2019s automation revolution.<\/p>"},{"question":"AM\/NS India","answer":"<p>NAMTECH has partnered with AMNS India, a leading integrated steel manufacturer and a joint venture between ArcelorMittal and Nippon Steel. This collaboration focuses on advancing skill development, industry-aligned education, and research in manufacturing and materials technologies.<\/p><p>Through joint initiatives in curriculum design, experiential learning, and applied research, NAMTECH and AMNS India aim to bridge the gap between academia and industry, nurturing a new generation of engineers equipped with cutting-edge technical and managerial capabilities.<\/p><p>AMNS India\u2019s leadership in sustainable steelmaking and advanced manufacturing complements NAMTECH\u2019s vision of shaping future-ready talent for India\u2019s manufacturing and engineering sectors. Together, this partnership enables real-world exposure, access to industry infrastructure, and career opportunities that empower students to contribute to India\u2019s industrial transformation and global competitiveness.<\/p>"},{"question":"Schneider Electric, Global \/ India","answer":"<p>Schneider Electric is a global leader in energy management, automation, and digitization, providing sustainable solutions for industries, infrastructure, data centres, buildings, and homes. The company focuses on electrification, industrial IoT, automation, smart grid technologies, and digital twin platforms to help organizations enhance reliability, safety, efficiency, and environmental performance. Operating in over 100 countries, Schneider Electric has a substantial presence in India, serving as a key global hub with multiple manufacturing sites, robust R&amp;D capabilities, and significant investments in sustainable and digital technologies.<\/p><p>NAMTECH\u2019s partnership with Schneider Electric is both strategic and transformative. This collaboration allows us to develop a world-class smart campus and advanced training labs at our temporary Gandhinagar site and the upcoming Ahmedabad campus. Students gain hands-on experience with state-of-the-art lab infrastructure, industry-relevant learning, and direct apprenticeships with experts. Beyond infrastructure, we integrate Schneider\u2019s expertise into our curriculum, particularly for the International Professional Master\u2019s Programme in Smart Manufacturing, ensuring our graduates are prepared for Industry 4.0.<\/p><p>This partnership offers NAMTECH students employment opportunities in India and internationally, while faculty members benefit from exposure to global best practices. The collaboration supports India\u2019s goals to modernize manufacturing, enhance competitiveness, and bridge the gap between industry and academia. As a result, our graduates are technically skilled, innovative, and prepared to lead in the digital industrial era.<\/p>"},{"question":"Festo","answer":"<p>NAMTECH has forged a strategic partnership with Festo, a global leader in automation technology. Festo will design and supply cutting-edge labs at NAMTECH interim campus at Research Park, IIT Gandhinagar, Gujarat, India.<\/p><p>Festo\u2019s role as a strategic partner for lab equipment and curriculum development ensures that our students have access to state-of-the-art facilities and industry-aligned learning experiences. NAMTECH work with the didactic team at Festo with an aim to offer students insights into leading Industry 4.0 technology.<\/p><p>This partnership not only enriches our academic programmes but also empowers students with practical skills and knowledge that are highly relevant in today\u2019s manufacturing landscape. Together, we are shaping the future of manufacturing education, preparing students to excel in their careers and contribute meaningfully to the industry.<\/p>"},{"question":"Micron","answer":"<p>NAMTECH has partnered with Micron, a global leader in semiconductor solutions. This collaboration spans across academic development, infrastructure setup, student training, and recruitment initiatives.<\/p><p>Micron is leading the semiconductor manufacturing foray in India and establishing a state-of-the-art facility in Sanand, which lies in close proximity to our campus. By working closely with industry leaders, NAMTECH ensures that its programmes are aligned with industry demands, providing students with hands-on experience, cutting-edge infrastructure, and opportunities for career advancement.<\/p><p>This holistic approach to the partnership enhances the educational experience and prepares students for successful careers. This synergistic partnership is in line with the steadily growing ecosystem in India and South-East Asia and students stand to benefit from faculty with industry expertise and the skills exposure, as well as employment opportunities in India and abroad.<\/p>"},{"question":"Cisco","answer":"<p>NAMTECH has partnered with Cisco, a global leader in networking and technology solutions. This partnership brings together expertise in manufacturing technologies and digital innovation to enhance our academic programmes and industry relevance.<\/p><p>This strategic collaboration reflects NAMTECH\u2019S commitment to delivering industry-relevant education and empowering students to excel in the dynamic fields of Cybersecurity and Networking in the field of manufacturing.<\/p><p>The partnership with industry leaders like CISCO to co-design curriculum, co-invest in learning infrastructure, and participate in recruitment drives helps is highly beneficial for our young professionals. Moreover, by working closely with partners, NAMTECH ensures that its curriculum is aligned with industry needs, providing students with hands-on experience, cutting-edge infrastructure, and pathways to meaningful careers.<\/p>"},{"question":"ASDC","answer":"<p>ASDC is the first sector skill council of India promoted by the automobile industry, with representations from leading industry associations from the automotive sector and the Government of India. ASDC is the apex body entrusted to address the skilling requirements of the entire automotive value chain.<\/p><p>NAMTECH has partnered with ASDC to support curriculum design, content development and delivery for vocational upskilling programmes under NAMTECH School for Social Impact aligned with the TVET model.<\/p>"},{"question":"ICICI Foundation","answer":"<p>NAMTECH has partnered with the ICICI Foundation for Inclusive Growth, dedicated to skill development and sustainable livelihoods for the less privileged. This partnership brings together expertise in technical training and social impact to enhance our outreach programmes and grassroots relevance.<\/p><p>This strategic collaboration reflects NAMTECH\u2019S commitment to delivering industry-relevant education and empowering underprivileged learners to excel in the dynamic fields of technical and vocational education.<\/p><p>The partnership with leaders like the ICICI Foundation to launch the NSSI outreach program, establish digital infrastructure, and deploy \"smart labs on wheels\" is highly beneficial for our learners. Moreover, by working closely with partners, NAMTECH ensures that its initiatives are aligned with societal and industry needs, providing students with hands-on experience, cutting-edge infrastructure, and pathways to meaningful careers.<\/p>"},{"question":"Rockwell Automation","answer":"<p>NAMTECH has partnered with Rockwell Automation, a global leader in industrial automation and digital transformation. This partnership brings together expertise in smart manufacturing and industrial technology to enhance our academic programmes and industry relevance.<\/p><p>This strategic collaboration reflects NAMTECH\u2019S commitment to delivering industry-relevant education and empowering students to excel in the dynamic fields of Industry 4.0 and sustainability in the field of manufacturing.<\/p><p>The partnership with industry leaders like Rockwell to co-design curriculum electives, co-invest in dedicated training facilities equipped with proprietary hardware, and participate in internship and scholarship drives is highly beneficial for our young professionals. This ensures that the curriculum is aligned with industry needs, providing students with hands-on experience, cutting-edge infrastructure, and pathways to meaningful careers.<\/p>"},{"question":"Analog Devices","answer":"<p>NAMTECH has partnered with Analog Devices, Inc. (ADI), a global semiconductor leader that bridges the physical and digital worlds. This partnership brings together expertise in semiconductor technologies and digital innovation to enhance our academic programmes and industry relevance.<\/p><p>This strategic collaboration reflects NAMTECH\u2019S commitment to delivering industry-relevant education and empowering students to excel in the dynamic fields of semiconductor manufacturing, engineering, and technology.<\/p><p>The partnership with industry leaders like ADI to co-design curriculum, support the development of a state-of-the-art semiconductor laboratory, and participate in hiring and upskilling drives is highly beneficial for our young professionals.<\/p>"},{"question":"FANUC","answer":"<p>NAMTECH has partnered with FANUC India Private Limited, a pioneer and global leader in Computer Numerical Control (CNC) and robotics technology. This partnership brings together expertise in precision engineering and industrial automation to enhance our academic programmes and industry relevance.<\/p><p>This strategic collaboration reflects NAMTECH\u2019S commitment to delivering industry-relevant education and empowering students to excel in the dynamic fields of robotics and precision engineering in the field of smart manufacturing.<\/p><p>The partnership with industry leaders like FANUC to co-design specialized curriculum electives, establish a Centre for Excellence in Robotics, and scale ITI outreach programs is highly beneficial for our young professionals.<\/p>"},{"question":"L&T Heavy Engineering","answer":"<p>NAMTECH has partnered with L&amp;T Heavy Engineering, a prominent leader in the industrial and manufacturing sector. This partnership brings together expertise in advanced manufacturing technologies and digital innovation to enhance our academic programmes and industry relevance.<\/p><p>This strategic collaboration reflects NAMTECH\u2019S commitment to delivering industry-relevant education and empowering students to excel in the dynamic fields of AI\/ML, automation, and advanced manufacturing operations.<\/p><p>The partnership with industry leaders like L&amp;T Heavy Engineering to co-design capstone projects, tackle real-world challenges like drone surveillance, and provide direct industry certification is highly beneficial for our young professionals.<\/p>"},{"question":"Hi-Tech Pipes","answer":"<p>NAMTECH has partnered with HITECH PIPES LTD, a prominent manufacturing entity committed to the advancement of smart manufacturing. This partnership brings together shared aspirations and resources to build a future-ready engineering talent pipeline and enhance our academic programmes and industry relevance.<\/p><p>This strategic collaboration reflects NAMTECH\u2019S commitment to delivering industry-relevant education and empowering students to excel in the dynamic fields of industrial AI and advanced automation in the field of manufacturing.<\/p><p>The partnership with industry leaders like HITECH PIPES to co-invest in campus infrastructure through a substantial financial grant for mutually identified projects is highly beneficial for our young professionals.<\/p>"},{"question":"Surya Roshni","answer":"<p>NAMTECH has partnered with Surya Roshni Ltd, a key industry player committed to the evolution of smart manufacturing. This partnership brings together shared goals and financial investments to build a large-scale, future-ready engineering talent pipeline and enhance our academic programmes and industry relevance.<\/p><p>This strategic collaboration reflects NAMTECH\u2019S commitment to delivering industry-relevant education and empowering students to excel in the dynamic fields of industrial AI and advanced automation in the Manufacturing, Engineering, and Technology (MET) sector.<\/p><p>The partnership with industry leaders like Surya Roshni to co-invest in developmental initiatives through targeted financial grants for campus projects is highly beneficial for our young professionals.<\/p>"},{"question":"KPMG in India","answer":"<p>KPMG in India is part of a global network of professional services firms providing Audit, Tax, and Advisory services. With a presence in over 140 countries, KPMG in India is a recognised leader in ESG and sustainability consulting, helping organisations transition to responsible and resilient business models.<\/p><p>This partnership equips students with industry-relevant skills and global sustainability exposure, preparing them for impactful careers in India\u2019s manufacturing transformation.<\/p>"},{"question":"NTPC","answer":"<p>NTPC is supporting the establishment of the Centre for Sustainable Energy and Circularity through its Corporate Social Responsibility (CSR) initiative, enabling the development of experiential learning infrastructure, capacity-building programmes and outreach initiatives focused on sustainable energy and circularity.<\/p>"}],"layout":"split"}', '2026-11-18 06:43:47', '2026-11-18 06:43:47', 'page', 19),
(167, 'logo_strip', NULL, NULL, 1, 4, '{"heading":"Industry partners","category":"industry","tone":null}', '2026-11-18 06:43:47', '2026-11-18 06:43:47', 'page', 19),
(168, 'testimonials', NULL, NULL, 1, 5, '{"eyebrow":null,"heading":"Hear from our Leaders","items":[{"quote":"The progress NAMTECH has achieved is nothing short of remarkable. We are happy to partner with NAMTECH \u2013 a beacon of technical education in India.","name":"Mr. Bruce Poh","role":"CEO, ITEES Singapore","image":null},{"quote":"NAMTECH has a visionary approach\u2026 focus on skilling at high scales for manufacturing\u2026 Posterity will acknowledge this impactful initiative and its institutional model that would bring up a future-ready high-tech workforce for India and the world.","name":"Dr. Koppillil Radhakrishnan","role":"Former Chairman \u2013 ISRO also led Mangalyaan (India\u2019s Mars mission)","image":null},{"quote":"I commend the founders and faculty of NAMTECH for creating a unique institution that is not just a center of academic excellence but also a beacon of hope for the future of engineering in India.","name":"Dr. Kamlesh Nilkanth Vyas","role":"Former Chairman \u2013 Indian Atomic Energy Commission, Distinguished Homi Bhabha Chair Professor at the Department of Atomic Energy","image":null}],"layout":"quotes","body":"Hear from industrial pioneers, visionaries and institutional heads who have experienced the approach, progress and success of the NAMTECH model.","tone":null}', '2026-11-18 06:43:47', '2026-11-18 06:43:47', 'page', 19),
(169, 'contact_band', NULL, NULL, 1, 6, '{"heading":"Co-create with us","body":"NAMTECH partners with leading industries and technology organizations to build future-ready training programs. Together, we design best-in-class learning programs and deliver 100% experiential education, building a globally competitive engineering workforce.","cta_label":"Partner with us","cta_url":"#enquiry:partnership","contacts_label":"For More Information","contacts":[{"name":"Ms. Nandini Dasgupta","role":"Director - Corporate Partnerships","email":"nandini.dasgupta@namtech.ac"},{"name":"Mr. Sridhar Kanukollu","role":"Associate Director \u2013 Corporate Partnerships","email":"sridhar.kanukollu@namtech.ac"}]}', '2026-11-18 06:43:47', '2026-11-18 06:43:47', 'page', 19),
(170, 'page_hero', NULL, NULL, 1, 0, '{"eyebrow":"Corporate Partnerships","title":"Strategic & Founding Partnerships","body":"For organizations shaping and leading the future of engineering education. Strategic and Founding Partnerships are NAMTECH\u2019s highest-tier of engagement, offering visionary organizations the opportunity to co-define the future of engineering education in India.","image":89,"cta_label":"Partner with us","cta_url":"#enquiry:partnership","secondary_label":null,"secondary_url":null,"statistics_group":null,"layout":null,"meta":[]}', '2026-11-18 06:43:47', '2026-11-18 06:43:47', 'page', 20),
(171, 'intro', NULL, NULL, 1, 1, '{"eyebrow":null,"heading":"Here\u2019s How We Work Together","body":"<p>Strategic and Founding Partnerships are designed for organizations that seek deep, long-term institutional alignment with NAMTECH\u2019s mission to build the future of engineering education in India.<\/p><p>Strategic and Founding Partners are co-architects of India\u2019s next generation of manufacturing talent. Together, we embark upon a shared mission, delivering value across talent development, innovation and social impact.<\/p>","cta_label":null,"cta_url":null,"icon":"handshake","tone":null}', '2026-11-18 06:43:47', '2026-11-18 06:43:47', 'page', 20),
(172, 'card_grid', NULL, NULL, 1, 2, '{"eyebrow":null,"heading":"Partnership Areas","body":null,"columns":"3","tone":"white","cards":[{"icon":"building","title":"Infrastructure Development","body":"Shape how the next generation engineers learn by co-creating dedicated schools, innovation centres and labs that simulate real-world industrial environments. Together, we translate technical expertise, application of emerging technologies and industry challenges into learning experiences that build more capable, deployment-ready professionals.","link_url":null},{"icon":"people","title":"Outreach & Skilling Ecosystems","body":"Engage in talent development across the manufacturing pyramid, with a focused pathway to India\u2019s technician and operator workforce through ITI outreach & upgradation. Ensure that skilled talent meets opportunity through curriculum interventions, immersive workshops and industry challenges along with hands-on training and career programs.","link_url":null},{"icon":"award","title":"Endowments","body":"Build a legacy in engineering education. Endowments allow partners to establish named scholarships, faculty chairs, research grants and innovation prizes that strengthen NAMTECH\u2019s academic ecosystem, advancing excellence and innovation for generations.","link_url":null}],"style":"joined","cta_label":null,"cta_url":null}', '2026-11-18 06:43:47', '2026-11-18 06:43:47', 'page', 20),
(173, 'contact_band', NULL, NULL, 1, 3, '{"heading":"Co-create with us","body":"NAMTECH partners with leading industries and technology organizations to build future-ready training programs. Together, we design best-in-class learning programs and deliver 100% experiential education, building a globally competitive engineering workforce.","cta_label":"Partner with us","cta_url":"#enquiry:partnership","contacts_label":"For More Information","contacts":[{"name":"Ms. Nandini Dasgupta","role":"Director - Corporate Partnerships","email":"nandini.dasgupta@namtech.ac"},{"name":"Mr. Sridhar Kanukollu","role":"Associate Director \u2013 Corporate Partnerships","email":"sridhar.kanukollu@namtech.ac"}]}', '2026-11-18 06:43:47', '2026-11-18 06:43:47', 'page', 20),
(174, 'page_hero', NULL, NULL, 1, 0, '{"eyebrow":"Corporate Partnerships","title":"Schools, Centers, CoEs & Lab Partnerships","body":"Build academic ecosystems that converge learning, research and industry practice to advance engineering education. School, Center, CoE and Lab partnerships offer industry leaders a definitive stake in how engineering education is designed, practiced, delivered and scaled at NAMTECH.","image":35,"cta_label":"Partner with us","cta_url":"#enquiry:partnership","secondary_label":null,"secondary_url":null,"statistics_group":null,"layout":null,"meta":[]}', '2026-11-18 06:43:47', '2026-11-18 06:43:47', 'page', 21),
(175, 'intro', NULL, NULL, 1, 1, '{"eyebrow":null,"heading":"Here\u2019s How We Work Together","body":"<p>School, Center, CoE and Lab partnerships offer industry leaders a definitive stake in how engineering education is designed, practiced, delivered and scaled at NAMTECH. By bringing industry expertise into curriculum, pedagogy, research and experiential learning, partners help shape an academic model built for the future of engineering.<\/p><p>Join us in redefining engineering education. By enabling technology access, mobilizing resources, building academic infrastructure, or integrating your industry expertise, partners can co-design curricula, drive applied research and power advanced training programs at NAMTECH.<\/p>","cta_label":null,"cta_url":null,"icon":"handshake","tone":null}', '2026-11-18 06:43:47', '2026-11-18 06:43:47', 'page', 21),
(176, 'tabs', NULL, NULL, 1, 2, '{"eyebrow":null,"heading":"Partnership Models","body":null,"tabs":[{"label":"School-level Partnerships","title":"School-level Partnerships","body":"<p>Co-create a school dedicated to your sector\u2019s evolving needs by shaping its academic vision, program portfolio, research methodology and industry engagement. School-level partnerships offer the deepest level of institutional co-ownership and a long-term platform to influence how the next generation of sector-specific talent is developed.<\/p>","image":7},{"label":"Center and CoE Partnerships","title":"Center and CoE Partnerships","body":"<p>Shape research agendas, deepen academic expertise and directly benefit from the intellectual output of talented graduates from NAMTECH\u2019s centers and centers of excellence (CoEs). Centers operate across broad domains like AI or sustainability, while CoEs bring concentrated academic and research depth to specific technologies or areas of strategic importance.<\/p>","image":2},{"label":"Lab Partnerships","title":"Lab Partnerships","body":"<p>Integrate advanced technology shaping modern industry into engineering education through dedicated experiential learning environments. Built around your technologies, tools and applications, lab partnerships enable meaningful hands-on exposure to industrial practice for learners while creating opportunities for technology validation, field trials and collaborative innovation.<\/p>","image":34}],"layout":"standard","tone":null}', '2026-11-18 06:43:47', '2026-11-18 06:43:47', 'page', 21),
(177, 'media_cards', NULL, NULL, 1, 3, '{"eyebrow":"Schools","heading":"Explore MET Innovation Schools","body":"NAMTECH\u2019s MET Innovation Schools are interdisciplinary, industry-led academic units that prepare graduates to shape India\u2019s industrial transformation. Each school offers structured partnership opportunities for industry leaders looking to shape the next generation of industrial engineers and professionals.","items":[{"image":7,"logo":null,"icon":null,"tag":null,"date":null,"title":"School of Manufacturing Technologies (SoMT)","subtitle":null,"body":"The School of Manufacturing Technologies (SoMT) equips engineers with the expertise to operate, optimize and revolutionize modern production environments. Students master CNC machining, lean manufacturing, industrial automation, IoT and digital manufacturing. The school has been built with support from Siemens, Schneider Electric, L&T, Rockwell Automation, Festo and Endress+Hauser for laboratories, projects and hands-on learning experiences in addition to a global academic partnership with TUM Asia.","meta":null,"link_url":"\/schools\/school-of-manufacturing-technologies"},{"image":3,"logo":null,"icon":null,"tag":null,"date":null,"title":"School of Manufacturing Design & AI (SoMDAI)","subtitle":null,"body":"The School of Manufacturing Design & AI (SoMDAI) converges at product innovation, digital engineering and intelligent manufacturing. Students master generative design, AI-driven simulation, sustainable design and cybersecurity, equipping them to lead the next wave of industrial transformation. Built in collaboration with leading semiconductor companies along with top-tier AI and cybersecurity companies, the school integrates industry-grade laboratories with advanced curricula. Graduates drive innovation across manufacturing, semiconductors, product development and Industry 4.0 environments.","meta":null,"link_url":"\/schools\/school-of-manufacturing-design-ai"},{"image":10,"logo":null,"icon":null,"tag":null,"date":null,"title":"School of Robotics (SoR)","subtitle":null,"body":"The School of Robotics (SoR) equips engineers to design, program and deploy intelligent automation systems across manufacturing, warehousing, logistics and industrial infrastructure. The curriculum builds expertise in industrial robotics, cobots, mechatronics and robotic process automation through experiential learning in industry-grade labs. Built with support from leading technology partners like Addverb for warehouse automation, ABB for robotics infrastructure and FANUC through WorldSkills and industrial automation initiatives. Students also train on Mitsubishi robotic systems already deployed across NAMTECH\u2019s facilities.","meta":null,"link_url":"\/schools\/school-of-robotics"},{"image":11,"logo":null,"icon":null,"tag":null,"date":null,"title":"School of Sustainability (SoS)","subtitle":null,"body":"The School of Sustainability (SoS) trains engineers to accelerate India\u2019s transition towards clean energy, circular economy models and sustainable industrial growth. Through experiential learning in renewable energy, energy transition and sustainable supply chains, graduates master skills required to lead India\u2019s sustainability transformation. As India\u2019s first school focused on industrial and manufacturing sustainability, it embeds sustainability principles across campus development and academia. In partnership with KPMG India, TUM Asia, Schneider Electric and Siemens, the school has created a global learning ecosystem implementing India\u2019s Net Zero and sustainable development ambitions.","meta":null,"link_url":"\/schools\/school-of-sustainability"}],"layout":"tall","tone":null,"cta_label":null,"cta_url":null,"footer_label":null,"footer_url":null,"card_link_label":"Explore school"}', '2026-11-18 06:43:47', '2026-11-18 06:43:47', 'page', 21),
(178, 'media_cards', NULL, NULL, 1, 4, '{"eyebrow":"Centers","heading":"MET Innovation Centers","body":null,"items":[{"image":2,"logo":null,"icon":null,"tag":null,"date":null,"title":"Center of Excellence in Automotive Engineering","subtitle":null,"body":"NAMTECH\u2019s Center of Excellence (CoE) in Automotive Engineering is a dynamic focal point for advanced research, skill-building and technological breakthroughs across internal combustion engines, EVs and hydrogen and fuel cell systems. By prioritizing key sectors like smart manufacturing, alternate fuels, ADAS, sustainable materials and vehicle electrification, the CoE successfully links academic learning with real-world industry demands to fuel the future of mobility. To build tomorrow\u2019s technology leaders and entrepreneurs, the center features a specialized 2-year Master Program in Automotive Technology and Management.","meta":null,"link_url":"\/centres\/coe-in-automotive-engineering"},{"image":21,"logo":null,"icon":null,"tag":null,"date":null,"title":"Center of Advanced Computing & AI (CoACAI)","subtitle":null,"body":"NAMTECH\u2019s Center of Advanced Computing & Artificial Intelligence (CoACAI) is a premier hub for innovation, research and talent development in data science, computing and intelligent systems. Specializing in high-impact domains like Generative AI, Machine Learning, Computer Vision, Cloud Computing and AI-driven robotics, the center bridges the gap between academia and industry. Through immersive, hands-on training, it equips learners to build and scale practical solutions for sectors such as healthcare, manufacturing, fintech, automotive, sustainability and smart cities.","meta":null,"link_url":"\/centres\/centre-of-advanced-computing-ai"},{"image":20,"logo":null,"icon":null,"tag":null,"date":null,"title":"Center of Sustainable Energy & Circularity (CSEC)","subtitle":null,"body":"NAMTECH, NTPC and IIT Roorkee jointly established the Center for Sustainable Energy and Circularity (CSEC) to pioneer advancements in energy transition, sustainable manufacturing, workforce transformation and circular economies. Blending IIT Roorkee\u2019s academic research with NTPC\u2019s clean energy leadership and NAMTECH\u2019s practical learning framework, the center serves as a national benchmark linking applied research, skill building and technology implementation.","meta":null,"link_url":"\/centres\/experiential-learning-center-for-sustainable-energy-circularity"}],"layout":"tall","tone":"light","cta_label":null,"cta_url":null,"footer_label":null,"footer_url":null,"card_link_label":"Explore center"}', '2026-11-18 06:43:47', '2026-11-18 06:43:47', 'page', 21),
(179, 'card_grid', NULL, 'labs-partnership', 1, 5, '{"eyebrow":null,"heading":"Labs Partnership","body":null,"columns":"3","tone":"white","cards":[{"icon":"gear","title":"Equipment Partnership","body":"Deploy cutting-edge machinery, tooling, and diagnostic hardware in our living labs, training the next generation directly on your industrial technology.","link_url":null},{"icon":"flask","title":"Full Lab Co-Branding","body":"Establish branded, dedicated Centers of Excellence and specialized laboratories addressing sector-specific manufacturing challenges.","link_url":null},{"icon":"graduation","title":"Training & Workforce Development","body":"Co-create customized skilling and upskilling programs for your current workforce and recruit pre-trained, job-ready technologists.","link_url":null}],"style":"joined","cta_label":null,"cta_url":null}', '2026-11-18 06:43:47', '2026-11-18 06:43:47', 'page', 21),
(180, 'card_grid', NULL, NULL, 1, 6, '{"eyebrow":null,"heading":"Co-Building the Ecosystem","body":"NAMTECH\u2019s Center of Excellence (CoE) and Lab partnerships are designed as collaborative ecosystems for industry leaders, researchers and government bodies to converge, solve complex industrial challenges and build shared capability.","columns":"3","tone":"white","cards":[{"icon":"book","title":"Joint Curriculum Development","body":"Co-author course modules, design project briefs and embed your organizational experience and technical expertise directly into learning modules. NAMTECH graduates enter the workforce aligned with your operational environment and industrial know-how.","link_url":null},{"icon":"people","title":"Faculty & Researcher Engagement","body":"Your technical experts become part of NAMTECH\u2019s academic community. Serving as visiting faculty, research co-supervisors and capstone mentors, this ensures your experts are at the frontier of research innovation while our faculty focuses on industrial application.","link_url":null},{"icon":"lightbulb","title":"Applied Research & IP Development","body":"Co-invest in research programs addressing your organization\u2019s most critical engineering challenges. Leverage NAMTECH\u2019s cutting-edge research infrastructure in a commercially aligned IP framework co-designed to provide business value for your enterprise.","link_url":null}],"style":"joined","cta_label":null,"cta_url":null}', '2026-11-18 06:43:47', '2026-11-18 06:43:47', 'page', 21),
(181, 'faq', NULL, 'industry-partners', 1, 7, '{"heading":"Meet our Industry Partners","body":null,"items":[{"question":"Siemens","answer":"<p>NAMTECH has forged a strategic partnership with Siemens to revolutionize education in smart manufacturing, automation, and advanced technical education. This collaboration aims to integrate cutting-edge industry expertise into NAMTECH\u2019s academic framework, introducing new electives and dedicated courses within the Master\u2019s, Executive and iPTP programmes.<\/p><p>The partnership emphasizes experiential learning, hands-on industry training, and the co-development of dynamic course curricula. A key highlight is the establishment of a robust industry attachment programme for both faculty and students, fostering deeper industry-academic integration.<\/p><p>Additionally, NAMTECH and Siemens will collaborate on developing state-of-the-art infrastructure, creating continuous knowledge-sharing platforms, and designing advanced learning modules to prepare learners for the challenges of Industry 4.0 and beyond.<\/p><p>Through this partnership, NAMTECH and Siemens are shaping a future-ready workforce equipped with the skills and expertise to drive innovation in manufacturing and automation.<\/p>"},{"question":"ABB","answer":"<p>NAMTECH and ABB have partnered to create a School of Robotics, setting a benchmark in robotics and automation education in India.<\/p><p>This visionary collaboration bridges the education gap in automation, advancing robotics skills and fostering seamless industry integration.<\/p><p>At the NAMTECH School of Robotics, ABB Robotics will play a pivotal role in designing, supporting, and executing various programmes. The programmes will be hands-on and industry-focused, supported by world-class infrastructure and guided by global industry leaders like ABB. The goal is to cultivate a highly skilled talent pool for the industrial sector, ensuring students are ready to meet the demands of a rapidly evolving technological landscape.<\/p><p>ABB\u2019s robotics experts will drive knowledge-sharing initiatives, spearhead cutting-edge research, and facilitate immersive industry exposure, offering unparalleled opportunities for students to gain practical expertise.<\/p><p>In 2023, India achieved a new milestone with the installation of 8,510 industrial robots, a 59% increase from the previous year. This growth positions India as the seventh-largest global market for annual robot installations and underscores its burgeoning potential in automation. As this trend accelerates through 2024 and 2025, job opportunities in the robotics sector are booming, particularly in roles such as Robotics Engineers, Robot Design Engineers, Application Engineers, and Smart Factory Designers.<\/p><p>With ABB\u2019s partnership, NAMTECH is at the forefront of shaping the future of robotics education and driving India\u2019s automation revolution.<\/p>"},{"question":"AM\/NS India","answer":"<p>NAMTECH has partnered with AMNS India, a leading integrated steel manufacturer and a joint venture between ArcelorMittal and Nippon Steel. This collaboration focuses on advancing skill development, industry-aligned education, and research in manufacturing and materials technologies.<\/p><p>Through joint initiatives in curriculum design, experiential learning, and applied research, NAMTECH and AMNS India aim to bridge the gap between academia and industry, nurturing a new generation of engineers equipped with cutting-edge technical and managerial capabilities.<\/p><p>AMNS India\u2019s leadership in sustainable steelmaking and advanced manufacturing complements NAMTECH\u2019s vision of shaping future-ready talent for India\u2019s manufacturing and engineering sectors. Together, this partnership enables real-world exposure, access to industry infrastructure, and career opportunities that empower students to contribute to India\u2019s industrial transformation and global competitiveness.<\/p>"},{"question":"Schneider Electric, Global \/ India","answer":"<p>Schneider Electric is a global leader in energy management, automation, and digitization, providing sustainable solutions for industries, infrastructure, data centres, buildings, and homes. The company focuses on electrification, industrial IoT, automation, smart grid technologies, and digital twin platforms to help organizations enhance reliability, safety, efficiency, and environmental performance. Operating in over 100 countries, Schneider Electric has a substantial presence in India, serving as a key global hub with multiple manufacturing sites, robust R&amp;D capabilities, and significant investments in sustainable and digital technologies.<\/p><p>NAMTECH\u2019s partnership with Schneider Electric is both strategic and transformative. This collaboration allows us to develop a world-class smart campus and advanced training labs at our temporary Gandhinagar site and the upcoming Ahmedabad campus. Students gain hands-on experience with state-of-the-art lab infrastructure, industry-relevant learning, and direct apprenticeships with experts. Beyond infrastructure, we integrate Schneider\u2019s expertise into our curriculum, particularly for the International Professional Master\u2019s Programme in Smart Manufacturing, ensuring our graduates are prepared for Industry 4.0.<\/p><p>This partnership offers NAMTECH students employment opportunities in India and internationally, while faculty members benefit from exposure to global best practices. The collaboration supports India\u2019s goals to modernize manufacturing, enhance competitiveness, and bridge the gap between industry and academia. As a result, our graduates are technically skilled, innovative, and prepared to lead in the digital industrial era.<\/p>"},{"question":"Festo","answer":"<p>NAMTECH has forged a strategic partnership with Festo, a global leader in automation technology. Festo will design and supply cutting-edge labs at NAMTECH interim campus at Research Park, IIT Gandhinagar, Gujarat, India.<\/p><p>Festo\u2019s role as a strategic partner for lab equipment and curriculum development ensures that our students have access to state-of-the-art facilities and industry-aligned learning experiences. NAMTECH work with the didactic team at Festo with an aim to offer students insights into leading Industry 4.0 technology.<\/p><p>This partnership not only enriches our academic programmes but also empowers students with practical skills and knowledge that are highly relevant in today\u2019s manufacturing landscape. Together, we are shaping the future of manufacturing education, preparing students to excel in their careers and contribute meaningfully to the industry.<\/p>"},{"question":"Micron","answer":"<p>NAMTECH has partnered with Micron, a global leader in semiconductor solutions. This collaboration spans across academic development, infrastructure setup, student training, and recruitment initiatives.<\/p><p>Micron is leading the semiconductor manufacturing foray in India and establishing a state-of-the-art facility in Sanand, which lies in close proximity to our campus. By working closely with industry leaders, NAMTECH ensures that its programmes are aligned with industry demands, providing students with hands-on experience, cutting-edge infrastructure, and opportunities for career advancement.<\/p><p>This holistic approach to the partnership enhances the educational experience and prepares students for successful careers. This synergistic partnership is in line with the steadily growing ecosystem in India and South-East Asia and students stand to benefit from faculty with industry expertise and the skills exposure, as well as employment opportunities in India and abroad.<\/p>"},{"question":"Cisco","answer":"<p>NAMTECH has partnered with Cisco, a global leader in networking and technology solutions. This partnership brings together expertise in manufacturing technologies and digital innovation to enhance our academic programmes and industry relevance.<\/p><p>This strategic collaboration reflects NAMTECH\u2019S commitment to delivering industry-relevant education and empowering students to excel in the dynamic fields of Cybersecurity and Networking in the field of manufacturing.<\/p><p>The partnership with industry leaders like CISCO to co-design curriculum, co-invest in learning infrastructure, and participate in recruitment drives helps is highly beneficial for our young professionals. Moreover, by working closely with partners, NAMTECH ensures that its curriculum is aligned with industry needs, providing students with hands-on experience, cutting-edge infrastructure, and pathways to meaningful careers.<\/p>"},{"question":"ASDC","answer":"<p>ASDC is the first sector skill council of India promoted by the automobile industry, with representations from leading industry associations from the automotive sector and the Government of India. ASDC is the apex body entrusted to address the skilling requirements of the entire automotive value chain.<\/p><p>NAMTECH has partnered with ASDC to support curriculum design, content development and delivery for vocational upskilling programmes under NAMTECH School for Social Impact aligned with the TVET model.<\/p>"},{"question":"ICICI Foundation","answer":"<p>NAMTECH has partnered with the ICICI Foundation for Inclusive Growth, dedicated to skill development and sustainable livelihoods for the less privileged. This partnership brings together expertise in technical training and social impact to enhance our outreach programmes and grassroots relevance.<\/p><p>This strategic collaboration reflects NAMTECH\u2019S commitment to delivering industry-relevant education and empowering underprivileged learners to excel in the dynamic fields of technical and vocational education.<\/p><p>The partnership with leaders like the ICICI Foundation to launch the NSSI outreach program, establish digital infrastructure, and deploy \"smart labs on wheels\" is highly beneficial for our learners. Moreover, by working closely with partners, NAMTECH ensures that its initiatives are aligned with societal and industry needs, providing students with hands-on experience, cutting-edge infrastructure, and pathways to meaningful careers.<\/p>"},{"question":"Rockwell Automation","answer":"<p>NAMTECH has partnered with Rockwell Automation, a global leader in industrial automation and digital transformation. This partnership brings together expertise in smart manufacturing and industrial technology to enhance our academic programmes and industry relevance.<\/p><p>This strategic collaboration reflects NAMTECH\u2019S commitment to delivering industry-relevant education and empowering students to excel in the dynamic fields of Industry 4.0 and sustainability in the field of manufacturing.<\/p><p>The partnership with industry leaders like Rockwell to co-design curriculum electives, co-invest in dedicated training facilities equipped with proprietary hardware, and participate in internship and scholarship drives is highly beneficial for our young professionals. This ensures that the curriculum is aligned with industry needs, providing students with hands-on experience, cutting-edge infrastructure, and pathways to meaningful careers.<\/p>"},{"question":"Analog Devices","answer":"<p>NAMTECH has partnered with Analog Devices, Inc. (ADI), a global semiconductor leader that bridges the physical and digital worlds. This partnership brings together expertise in semiconductor technologies and digital innovation to enhance our academic programmes and industry relevance.<\/p><p>This strategic collaboration reflects NAMTECH\u2019S commitment to delivering industry-relevant education and empowering students to excel in the dynamic fields of semiconductor manufacturing, engineering, and technology.<\/p><p>The partnership with industry leaders like ADI to co-design curriculum, support the development of a state-of-the-art semiconductor laboratory, and participate in hiring and upskilling drives is highly beneficial for our young professionals.<\/p>"},{"question":"FANUC","answer":"<p>NAMTECH has partnered with FANUC India Private Limited, a pioneer and global leader in Computer Numerical Control (CNC) and robotics technology. This partnership brings together expertise in precision engineering and industrial automation to enhance our academic programmes and industry relevance.<\/p><p>This strategic collaboration reflects NAMTECH\u2019S commitment to delivering industry-relevant education and empowering students to excel in the dynamic fields of robotics and precision engineering in the field of smart manufacturing.<\/p><p>The partnership with industry leaders like FANUC to co-design specialized curriculum electives, establish a Centre for Excellence in Robotics, and scale ITI outreach programs is highly beneficial for our young professionals.<\/p>"},{"question":"L&T Heavy Engineering","answer":"<p>NAMTECH has partnered with L&amp;T Heavy Engineering, a prominent leader in the industrial and manufacturing sector. This partnership brings together expertise in advanced manufacturing technologies and digital innovation to enhance our academic programmes and industry relevance.<\/p><p>This strategic collaboration reflects NAMTECH\u2019S commitment to delivering industry-relevant education and empowering students to excel in the dynamic fields of AI\/ML, automation, and advanced manufacturing operations.<\/p><p>The partnership with industry leaders like L&amp;T Heavy Engineering to co-design capstone projects, tackle real-world challenges like drone surveillance, and provide direct industry certification is highly beneficial for our young professionals.<\/p>"},{"question":"Hi-Tech Pipes","answer":"<p>NAMTECH has partnered with HITECH PIPES LTD, a prominent manufacturing entity committed to the advancement of smart manufacturing. This partnership brings together shared aspirations and resources to build a future-ready engineering talent pipeline and enhance our academic programmes and industry relevance.<\/p><p>This strategic collaboration reflects NAMTECH\u2019S commitment to delivering industry-relevant education and empowering students to excel in the dynamic fields of industrial AI and advanced automation in the field of manufacturing.<\/p><p>The partnership with industry leaders like HITECH PIPES to co-invest in campus infrastructure through a substantial financial grant for mutually identified projects is highly beneficial for our young professionals.<\/p>"},{"question":"Surya Roshni","answer":"<p>NAMTECH has partnered with Surya Roshni Ltd, a key industry player committed to the evolution of smart manufacturing. This partnership brings together shared goals and financial investments to build a large-scale, future-ready engineering talent pipeline and enhance our academic programmes and industry relevance.<\/p><p>This strategic collaboration reflects NAMTECH\u2019S commitment to delivering industry-relevant education and empowering students to excel in the dynamic fields of industrial AI and advanced automation in the Manufacturing, Engineering, and Technology (MET) sector.<\/p><p>The partnership with industry leaders like Surya Roshni to co-invest in developmental initiatives through targeted financial grants for campus projects is highly beneficial for our young professionals.<\/p>"},{"question":"KPMG in India","answer":"<p>KPMG in India is part of a global network of professional services firms providing Audit, Tax, and Advisory services. With a presence in over 140 countries, KPMG in India is a recognised leader in ESG and sustainability consulting, helping organisations transition to responsible and resilient business models.<\/p><p>This partnership equips students with industry-relevant skills and global sustainability exposure, preparing them for impactful careers in India\u2019s manufacturing transformation.<\/p>"},{"question":"NTPC","answer":"<p>NTPC is supporting the establishment of the Centre for Sustainable Energy and Circularity through its Corporate Social Responsibility (CSR) initiative, enabling the development of experiential learning infrastructure, capacity-building programmes and outreach initiatives focused on sustainable energy and circularity.<\/p>"}],"layout":"split"}', '2026-11-18 06:43:47', '2026-11-18 06:43:47', 'page', 21),
(182, 'testimonials', NULL, NULL, 1, 8, '{"eyebrow":null,"heading":"Hear from our Leaders","items":[{"quote":"The progress NAMTECH has achieved is nothing short of remarkable. We are happy to partner with NAMTECH \u2013 a beacon of technical education in India.","name":"Mr. Bruce Poh","role":"CEO, ITEES Singapore","image":null},{"quote":"NAMTECH has a visionary approach\u2026 focus on skilling at high scales for manufacturing\u2026 Posterity will acknowledge this impactful initiative and its institutional model that would bring up a future-ready high-tech workforce for India and the world.","name":"Dr. Koppillil Radhakrishnan","role":"Former Chairman \u2013 ISRO also led Mangalyaan (India\u2019s Mars mission)","image":null},{"quote":"I commend the founders and faculty of NAMTECH for creating a unique institution that is not just a center of academic excellence but also a beacon of hope for the future of engineering in India.","name":"Dr. Kamlesh Nilkanth Vyas","role":"Former Chairman \u2013 Indian Atomic Energy Commission, Distinguished Homi Bhabha Chair Professor at the Department of Atomic Energy","image":null}],"layout":"quotes","body":"Hear from industrial pioneers, visionaries and institutional heads who have experienced the approach, progress and success of the NAMTECH model.","tone":null}', '2026-11-18 06:43:47', '2026-11-18 06:43:47', 'page', 21),
(183, 'page_hero', NULL, NULL, 1, 0, '{"eyebrow":"Corporate Partnerships","title":"Sponsored Research","body":"Driving industry innovation through research-led collaboration. Support targeted research programmes, engage with leading faculty and researchers and advance new knowledge and intellectual property development through a flexible, collaborative research partnership.","image":83,"cta_label":"Partner with us","cta_url":"#enquiry:partnership","secondary_label":null,"secondary_url":null,"statistics_group":null,"layout":null,"meta":[]}', '2026-11-18 06:43:47', '2026-11-18 06:43:47', 'page', 22),
(184, 'card_grid', NULL, NULL, 1, 1, '{"eyebrow":null,"heading":"How We Work Together","body":"NAMTECH\u2019s Sponsored Research partnerships give industry sponsors meaningful influence over research direction and a clear pathway to commercialize outcomes. Whether you have a specific industrial problem to solve or a technology frontier to explore, we design research engagements that deliver.","columns":"3","tone":"white","cards":[{"icon":"flask","title":"Directed Research Projects","body":"Sponsor a focused, time-bound research project led by NAMTECH faculty and graduate researchers. You define the problem statement and desired outcomes; we bring the research capability, facilities and academic methodology. Regular reporting, milestone check-ins and IP-sharing agreements ensure that the project delivers commercially viable insights within agreed timelines.","link_url":null},{"icon":"people","title":"Faculty Exchange & Collaborative Research","body":"Embed your technical experts in NAMTECH\u2019s laboratories and research community and vice versa. Faculty exchange programs allow your team to co-author research, co-supervise graduate students and jointly present findings at international conferences.","link_url":null},{"icon":"award","title":"Research Chairs & Long-Term Programs","body":"Establish a named Research Chair in your chosen technology or industry domain. This could be a professorial or associate professorial position focused on academic research challenges. Endowed chairs attract top-tier academic talent, build research capability over multiple years and create a permanent institutional association.","link_url":null}],"style":"joined","cta_label":null,"cta_url":null}', '2026-11-18 06:43:47', '2026-11-18 06:43:47', 'page', 22),
(185, 'contact_band', NULL, NULL, 1, 2, '{"heading":"Co-create with us","body":"NAMTECH partners with leading industries and technology organizations to build future-ready training programs. Together, we design best-in-class learning programs and deliver 100% experiential education, building a globally competitive engineering workforce.","cta_label":"Partner with us","cta_url":"#enquiry:partnership","contacts_label":"For More Information","contacts":[{"name":"Ms. Nandini Dasgupta","role":"Director - Corporate Partnerships","email":"nandini.dasgupta@namtech.ac"},{"name":"Mr. Sridhar Kanukollu","role":"Associate Director \u2013 Corporate Partnerships","email":"sridhar.kanukollu@namtech.ac"}]}', '2026-11-18 06:43:47', '2026-11-18 06:43:47', 'page', 22),
(186, 'page_hero', NULL, NULL, 1, 0, '{"eyebrow":"Academic Partnerships","title":"A Collaborative Academic Platform to Advance Engineering Education In India","body":"Academic partnerships at NAMTECH are pioneering a shift in engineering and technical education. Through robust partnerships with world-class academic institutions in India and beyond, NAMTECH integrates experiential learning with cutting-edge labs, applied research and advanced industrial systems. Partnering with NAMTECH ensures that top educational establishments have a definitive stake in equipping learners with the expertise to shape the future of manufacturing.","image":98,"cta_label":"Partner with us","cta_url":"#enquiry:partnership","secondary_label":null,"secondary_url":null,"statistics_group":null,"layout":null,"meta":[]}', '2026-11-18 06:43:47', '2026-11-18 06:43:47', 'page', 23),
(187, 'feature_list', NULL, NULL, 1, 1, '{"eyebrow":null,"heading":"Our Academic Partners","body":null,"tabs":[{"label":null,"items":[{"icon":"graduation","text":"Massachusetts Institute of Technology Department of Mechanical Engineering, United States"},{"icon":"graduation","text":"Carnegie Mellon University, United States"},{"icon":"graduation","text":"Technical University of Munich (TUM ASIA), Singapore"},{"icon":"graduation","text":"Purdue University Northwest, United States"},{"icon":"graduation","text":"ITEES, Singapore"}]}]}', '2026-11-18 06:43:47', '2026-11-18 06:43:47', 'page', 23),
(188, 'media_cards', NULL, NULL, 1, 2, '{"eyebrow":null,"heading":"Global Academic Collaborations In Action","body":null,"items":[{"image":31,"logo":null,"icon":null,"tag":null,"date":null,"title":"Massachusetts Institute of Technology Department of Mechanical Engineering, United States","subtitle":null,"body":"An 18-month pilot initiative designed to adapt, scale and implement MIT MechE\u2019s renowned curriculum. By integrating advanced AR\/VR architectures and phygital labs, we\u2019re setting a new standard for engineering execution.","meta":null,"link_url":null},{"image":32,"logo":null,"icon":null,"tag":null,"date":null,"title":"Carnegie Mellon University, United States","subtitle":null,"body":"Our collaboration with Carnegie Mellon includes their Simon Initiative and Open Learning Initiative (OLI). NAMTECH and OLI are co-designing STEM courses, comprehensive faculty upskilling via the Learning Engineering Fellows program and upskilling ITI students. With the impact already visible, this valuable collaboration with Carnegie Mellon University will also lead to the establishment of a Learning Science Research Center on the NAMTECH campus.","meta":null,"link_url":null},{"image":5,"logo":24,"icon":null,"tag":null,"date":null,"title":"Technical University of Munich (TUM ASIA), Singapore","subtitle":null,"body":"A continuous curriculum enhancement initiative in collaboration with TUM Asia is designed to anchor NAMTECH\u2019s iPMP programs within changing Industry 4.0 standards, integrating innovative teaching methodologies and global academic practices. TUM Asia regularly conducts specialized training programs for NAMTECH faculty and students, while NAMTECH\u2019s elite faculty members conduct specialized training programs in Singapore. Students completing iPMP programs receive joint certification from NAMTECH and TUM Asia.","meta":null,"link_url":null},{"image":100,"logo":null,"icon":null,"tag":null,"date":null,"title":"Purdue University Northwest (PNW), United States","subtitle":null,"body":"The objective of this collaboration is to deliver customized, experiential and smart manufacturing-focused engineering programs that have helped close the gap between foundational studies and advanced research. Highly experienced PNW visiting faculty members assist NAMTECH faculty in delivering specialized modules in its programs. Additionally, NAMTECH and PNW\u2019s 1+1 Pathway Program provides iPMP-SMG students with an exclusive opportunity to seamlessly transition into PNW\u2019s Master of Science in Mechanical Engineering program in Indiana.","meta":null,"link_url":null},{"image":94,"logo":null,"icon":null,"tag":null,"date":null,"title":"ITEES, Singapore","subtitle":null,"body":"A co-designed curriculum that integrates Indian technologists with Industry 4.0 standards and moulds them through Singapore\u2019s elite postgraduate discipline. This partnership has enabled NAMTECH to build a strong trainer ecosystem. Over the last two years, NAMTECH has trained more than 100 trainers and impacted over 3,600 learners through its programs.","meta":null,"link_url":null}],"layout":"logo","tone":null,"cta_label":null,"cta_url":null,"footer_label":null,"footer_url":null,"card_link_label":null}', '2026-11-18 06:43:47', '2026-11-18 06:43:47', 'page', 23),
(189, 'card_grid', NULL, NULL, 1, 3, '{"eyebrow":null,"heading":"Here\u2019s Why Leading Academic Institutions Partner With NAMTECH","body":null,"columns":"3","tone":"white","cards":[{"icon":"handshake","title":"Curriculum Co-Designed with Industry","body":"Our curriculum is designed and delivered in direct collaboration with industry leaders, ensuring students learn the skills, technologies and practices that are relevant to the evolving demands of the workplace.","link_url":null},{"icon":"factory","title":"Immersive and Experiential Learning","body":"NAMTECH trains within specialized labs, or \u2018micro-factories\u2019 that replicate live, high-tech production floors. By developing skills within these micro-factories, NAMTECH graduates are \u201cDay-Zero Ready\u201d, when they enter the workforce.","link_url":null},{"icon":"globe","title":"The MET Ecosystem Hub","body":"NAMTECH is the founding member, convenor, and the catalyst of the Manufacturing Engineering Technology (MET) platform that seeks to engage government, industry, and academia in a shared execution and governance framework to enhance India\u2019s manufacturing competitiveness.","link_url":null}],"style":"joined","cta_label":null,"cta_url":null}', '2026-11-18 06:43:47', '2026-11-18 06:43:47', 'page', 23),
(190, 'card_grid', NULL, NULL, 1, 4, '{"eyebrow":null,"heading":"Co-Create The Future With NAMTECH","body":"NAMTECH works with leading Indian and global academic institutions, researchers, and think tanks across six core areas for academic collaboration.","columns":"3","tone":"lavender","cards":[{"icon":"flask","title":"Joint Research, Innovation & Technology Development","body":"Collaborate on applied research, industry-sponsored projects and deep-tech innovations in smart manufacturing, sustainability, automotive systems, robotics, semiconductor manufacturing and AI. NAMTECH delivers direct access to robust industry networks, advanced experiential labs and interdisciplinary research opportunities.","link_url":null},{"icon":"book","title":"Advanced Skilling, Curriculum Development & Academic Innovation","body":"Co-develop industry-aligned curricula, micro-credentials, certification programs and experiential learning modules. NAMTECH houses extensive expertise in outcome-based education, industry integration and competency mapping.","link_url":null},{"icon":"globe","title":"Joint Academic Programs & Global Pathways","body":"Establish integrated academic programs, credit-transfer and semester abroad opportunities along with jointly delivered courses. NAMTECH provides flexible program structures, industry-integrated learning and access to a growing network of reputed international academic institutions.","link_url":null},{"icon":"graduation","title":"Faculty Development, Executive Education & Professional Upskilling","body":"Design and deliver jointly certified Faculty Development Programs (FDPs), Executive Development Programs (EDPs), leadership programs and professional upskilling programs. NAMTECH possesses expertise in advanced manufacturing & sustainability education as well as workforce transformation initiatives.","link_url":null},{"icon":"people","title":"Faculty, Student & Industry Practitioner Exchanges","body":"Facilitate short-term and long-term exchange and engagement opportunities for faculty, researchers, students and industry experts. NAMTECH provides robust industrial infrastructure, strong industry connectivity and experiential learning environments.","link_url":null},{"icon":"lightbulb","title":"Ecosystem Innovation, Entrepreneurship & Venture Platforms","body":"Collaborate to strengthen innovation and entrepreneurship through startup incubation, innovation challenges, hackathons, consortiums, competitions and platforms addressing national priorities such as green mobility, advanced manufacturing and sustainable development. NAMTECH offers access to industry partnerships and convening power to scale meaningfully.","link_url":null}],"style":"outlined","cta_label":null,"cta_url":null}', '2026-11-18 06:43:47', '2026-11-18 06:43:47', 'page', 23),
(191, 'testimonials', NULL, NULL, 1, 5, '{"eyebrow":null,"heading":"Endorsements Of Global Leaders On NAMTECH","items":[{"quote":"The progress NAMTECH has achieved is nothing short of remarkable. We are happy to partner with NAMTECH \u2013 a beacon of technical education in India.","name":"Mr. Bruce Poh","role":"CEO, ITEES Singapore","image":null},{"quote":"NAMTECH has a visionary approach\u2026 focus on skilling at high scales for manufacturing\u2026 Posterity will acknowledge this impactful initiative and its institutional model that would bring up a future-ready high-tech workforce for India and the world.","name":"Dr. Koppillil Radhakrishnan","role":"Former Chairman, ISRO. Also led Mangalyaan (India\u2019s Mars mission)","image":null},{"quote":"I commend the founders and faculty of NAMTECH for creating a unique institution that is not just a centre of academic excellence but also a beacon of hope for the future of engineering in India.","name":"Dr. Kamlesh Nilkanth Vyas","role":"Former Chairman, Indian Atomic Energy Commission. Distinguished Homi Bhabha Chair Professor at the Department of Atomic Energy","image":null}],"layout":"quotes","body":"Hear from visionaries and institutional heads who have experienced the approach, progress and success of the NAMTECH model.","tone":null}', '2026-11-18 06:43:47', '2026-11-18 06:43:47', 'page', 23),
