(198, 'cta_band', NULL, NULL, 1, 4, '{"heading":"Have Questions? Get in touch with us","body":"We partner with the best of industry, academia, and technology to co-create curriculum and align training with workforce needs. Partner with us to shape a skilled workforce for India\u2019s future.","cta_label":"Contact us","cta_url":"\/contact","tone":null}', '2026-11-18 06:43:47', '2026-11-18 06:43:47', 'page', 24),
