(201, 'card_grid', NULL, NULL, 1, 2, '{"eyebrow":null,"heading":"Research & Publications @ NAMTECH","body":null,"columns":"2","tone":"white","cards":[{"icon":"factory","title":"Learning by building","body":"Learning happens by building. At NAMTECH, classrooms don\u2019t have desks but machines used in the industry.","link_url":null},{"icon":"globe","title":"Global co-delivery","body":"Our curriculum is co-designed and co-delivered with academicians from global universities.","link_url":null}],"style":"outlined","cta_label":null,"cta_url":null}', '2026-11-18 06:43:47', '2026-11-18 06:43:47', 'page', 25),
