(207, 'tabs', NULL, NULL, 1, 3, '{"eyebrow":null,"heading":"Industrial Sectors we serve","body":null,"tabs":[{"label":"Energy & Resources","title":"Energy & Resources","body":"<p>Accelerating decarbonization, renewable energy grid integration, and circular resource management across mining, metallurgy, and utility sectors.<\/p>","image":null},{"label":"Industrials & Mobility","title":"Industrials & Mobility","body":"<p>Engineering connected factory environments, EV powertrain optimization, collaborative robotics deployment, and lean production workflows for modern manufacturing.<\/p>","image":null},{"label":"Financial Services","title":"Financial Services","body":"<p>Enabling ESG compliance frameworks, green capital financing assessments, and data-driven risk modeling for industrial assets.<\/p>","image":null},{"label":"MET Sector","title":"MET Sector","body":"<p>Pioneering manufacturing engineering &amp; technology breakthroughs, heavy industry automation, digital twins, and advanced materials engineering.<\/p>","image":null},{"label":"Health & Life Sciences","title":"Health & Life Sciences","body":"<p>Consulting on precision cleanroom automation, medical device rapid prototyping, and pharmaceutical manufacturing supply chain resilience.<\/p>","image":null},{"label":"Infrastructure & Built Environment","title":"Infrastructure & Built Environment","body":"<p>Advising on smart city infrastructure, sustainable building materials, low-carbon construction methods, and industrial estate optimization.<\/p>","image":null}],"layout":"centered","tone":"light"}', '2026-11-18 06:43:47', '2026-11-18 06:43:47', 'page', 26),
(208, 'intro', NULL, NULL, 1, 4, '{"eyebrow":null,"heading":"Our Consulting Services","body":"<p>NAMTECH\u2019s Consultancy division partners with industrial enterprises to drive operational excellence, digital transformation, AI adoption, and sustainable green manufacturing practices. Leveraging state-of-the-art labs and distinguished faculty, we help organizations accelerate productivity and engineer tomorrow''s industrial capabilities.<\/p>","cta_label":null,"cta_url":null,"icon":null,"tone":null}', '2026-11-18 06:43:47', '2026-11-18 06:43:47', 'page', 26),
