(212, 'page_hero', NULL, NULL, 1, 0, '{"eyebrow":"School of Technical Education","title":"School of Technical Education: Building Industry 4.0\u2013Ready Technologists","body":null,"image":87,"cta_label":"Explore Programs","cta_url":"#programs","secondary_label":null,"secondary_url":null,"statistics_group":null,"layout":null,"meta":[]}', '2026-11-18 06:43:47', '2026-11-18 06:43:47', 'page', 28),
(213, 'intro', NULL, NULL, 1, 1, '{"eyebrow":null,"heading":"Overview","body":"<p>The School of Technical Education (STE) is dedicated to preparing technician-engineers for the demanding realities of Industry 4.0. Through intensive hands-on curricula, simulation labs, and industry co-delivered modules, STE transforms diploma holders and technical learners into world-class automation and robotics technologists.<\/p>","cta_label":null,"cta_url":null,"icon":"cap","tone":null}', '2026-11-18 06:43:47', '2026-11-18 06:43:47', 'page', 28),
(214, 'card_grid', NULL, NULL, 1, 2, '{"eyebrow":"Talking Points","heading":"Transforming India\u2019s technical workforce","body":null,"columns":"4","tone":"white","cards":[{"icon":"people","title":"Transforming India\u2019s Technician Workforce","body":null,"link_url":null},{"icon":"robot","title":"Experiential Learning Through Advanced Technology","body":null,"link_url":null},{"icon":"factory","title":"Industry-integrated, applied learning models","body":null,"link_url":null},{"icon":"globe","title":"Scaling Skills Access Across India","body":null,"link_url":null}],"style":"joined","cta_label":null,"cta_url":null}', '2026-11-18 06:43:47', '2026-11-18 06:43:47', 'page', 28),
(215, 'programs_list', NULL, 'programs', 1, 3, '{"eyebrow":null,"heading":"Explore Programs @ School of Technical Education","level":"technical","school":null}', '2026-11-18 06:43:47', '2026-11-18 06:43:47', 'page', 28),
(216, 'video_feature', NULL, NULL, 1, 4, '{"layout":"overlay","eyebrow":null,"heading":"Here\u2019s What the Dean Says","body":"At the School of Technical Education, our focus is squarely on transforming India\u2019s technical workforce through immersive, shop-floor learning. We don\u2019t just teach theory\u2014we empower technicians and engineers with the exact hands-on skills global manufacturers are looking for.","name":"Mr. Sandeep Achantani","role":"Director, School of Technical Education","image":70,"video_url":null}', '2026-11-18 06:43:47', '2026-11-18 06:43:47', 'page', 28),
