(224, 'image_text', NULL, NULL, 1, 1, '{"eyebrow":null,"heading":"Our Vision","body":"<p>To empower 3 million youth with advancement in the MET sector and position India as a global hub for manufacturing excellence.<\/p>","image":105,"image_position":"left","cta_label":null,"cta_url":null,"layout":"staggered","tone":null}', '2026-11-18 06:43:48', '2026-11-18 06:43:48', 'page', 29),
(225, 'image_text', NULL, NULL, 1, 2, '{"eyebrow":null,"heading":"Our Mission","body":"<p>To empower 3 million youth with advancement in the MET sector and position India as a global hub for manufacturing excellence.<\/p>","image":106,"image_position":"right","cta_label":null,"cta_url":null,"layout":"staggered","tone":null}', '2026-11-18 06:43:48', '2026-11-18 06:43:48', 'page', 29),
(226, 'accordion_media', NULL, NULL, 1, 3, '{"eyebrow":null,"heading":"Current Gaps in Tech-Vocational Education","items":[{"title":"A growing skills gap","text":"Vocational education focuses on routine skills, but Industry 4.0 requires more. Digital systems and collaboration are now essential. Without updated training, many students risk being left behind.","image":47},{"title":"Infrastructure hasn\u2019t kept up","text":"Most ITIs aren\u2019t designed for advanced manufacturing. They lack smart labs and real tools, limiting hands-on learning and exposure to modern production.","image":61},{"title":"From operators to future leaders","text":"Many students are trained to operate machines. Tomorrow\u2019s industry needs technicians who can adapt and lead on the shop floor.","image":87}]}', '2026-11-18 06:43:48', '2026-11-18 06:43:48', 'page', 29),
(227, 'card_tabs', NULL, NULL, 1, 4, '{"eyebrow":null,"heading":"NAMTECH\u2019s Hubs and Spokes Model","body":null,"cta_label":"Read Case Study","cta_url":"\/impact\/stories","tone":"lavender","tabs":[{"label":"Overview","cards":[{"icon":"building","title":"Infrastructure of the hubs","text":null},{"icon":"globe","title":"Spokes\u2019 ITI Network","text":null},{"icon":"code","title":"Learning Delivery Model","text":null},{"icon":"trend","title":"Student Impact & Career Pathways","text":null}]},{"label":"Infrastructure","cards":[{"icon":"building","title":"State-of-the-Art Training Hubs","text":"Equipped with mobile training units, specialized robotic work cells, and cloud-connected phygital simulation stations deployed across regional centers."},{"icon":"gear","title":"Mobile Campuses & Labs on Wheels","text":"Bringing high-technology manufacturing equipment and certified training directly to remote ITIs and technical institutions."}]},{"label":"Locations","cards":[{"icon":"pin","title":"Key Industrial Clusters","text":"Expanding across major manufacturing corridors in Gujarat, Maharashtra, Tamil Nadu, Andhra Pradesh, and Northern industrial hubs."},{"icon":"globe","title":"Pan-India Reach","text":"Partnering with state technical boards and central agencies to scale reach to over 500 partner polytechnics and ITIs."}]},{"label":"Impact Stories","cards":[{"icon":"trend","title":"Social Upliftment & Employability","text":"Empowering youth from tier-2 and tier-3 towns with immediate placement pathways in high-growth automation roles."},{"icon":"award","title":"Career Acceleration","text":"Over 90% of certified technicians report a 2x increase in starting salaries upon completing the phygital skill pathways."}]}]}', '2026-11-18 06:43:48', '2026-11-18 06:43:48', 'page', 29),
(228, 'numbered_list', NULL, NULL, 1, 5, '{"eyebrow":null,"heading":"NAMTECH\u2019s Scaling Strategies","body":"NAMTECH is scaling its Hub-and-Spoke Model by partnering with Central & State Departments, Government ITIs and institutions for large-scale program implementation and with Industry to upskill their existing workforce.","list_label":"Our expansion focuses on:","items":[{"text":"Collaborating with Central & State Government for effective program implementation across technical institutions"},{"text":"Partnering with Industry for customized upskilling, apprenticeships, and placements"},{"text":"Replicating proven infrastructure and phygital learning solutions"},{"text":"Strengthening faculty development and industry-aligned curriculum"}],"footer":"Through this collaborative approach, NAMTECH aims to empower nearly 3 million learners across India with future-ready technical skills and sustainable employment opportunities."}', '2026-11-18 06:43:48', '2026-11-18 06:43:48', 'page', 29),
(229, 'card_grid', NULL, NULL, 1, 6, '{"eyebrow":"Partnerships Opportunities","heading":"Support & Partnership Opportunities","body":"NAMTECH School of Technical Education invites industry leaders, corporates, and CSR foundations to partner with us in transforming technical education and empowering underprivileged youth across India. We offer multiple meaningful collaboration models that deliver measurable social impact while providing strategic value to your organization.","columns":"3","tone":"white","cards":[{"icon":"building","title":"Infrastructure & labs Sponsorship","body":"Support the development of advanced labs, smart classrooms, EV training facilities, and Lab on Wheels to provide students with industry-relevant, hands-on learning experiences.","link_url":null},{"icon":"code","title":"Phygital Training Program","body":"Sponsor student cohorts through NAMTECH\u2019s Phygital Learning Program, enabling access to digital learning platforms, simulations, and practical training.","link_url":null},{"icon":"people","title":"Serve India Fellowship","body":"Fund fellowships for professionals working with government ITIs to mentor faculty, strengthen institutions, and improve student learning outcomes.","link_url":null},{"icon":"graduation","title":"Skill Development & Employability Programs","body":"Support specialized training, industry immersion, placement readiness initiatives, and soft skills programs that prepare students for successful careers.","link_url":null},{"icon":"handshake","title":"Adopt-an-ITI \/ Hub & Spoke Model","body":"Partner with one or more ITIs to strengthen infrastructure, faculty capability, and student outcomes through NAMTECH\u2019s Hub & Spoke model.","link_url":null},{"icon":"leaf","title":"Corporate CSR Projects & Impact Funding","body":"Collaborate on customized CSR initiatives with measurable outcomes, transparent reporting, and long-term community impact.","link_url":null}],"style":"outlined","cta_label":null,"cta_url":null}', '2026-11-18 06:43:48', '2026-11-18 06:43:48', 'page', 29),
(230, 'tabs_media', NULL, NULL, 1, 7, '{"eyebrow":null,"heading":"Partnership Models","body":"Through the innovative Hub-and-Spoke model, the program proudly supports an impressive 1,800 ITI learners each year. This initiative not only connects them to essential industry-ready skills but also provides invaluable mentorship and diverse career pathways.","tone":null,"tabs":[{"label":"Infrastructure & labs","image":35,"title":"Infrastructure & labs Sponsorship","text":"Support the development of advanced labs, smart classrooms, EV training facilities, and Lab on Wheels to provide students with industry-relevant, hands-on learning experiences.","points":[],"links":[]},{"label":"Phygital Training Program","image":32,"title":"Phygital Training Program","text":"Sponsor student cohorts through NAMTECH\u2019s Phygital Learning Program, enabling access to digital learning platforms, simulations, and practical training.","points":[],"links":[]},{"label":"Serve India Fellowship","image":100,"title":"Serve India Fellowship","text":"Fund fellowships for professionals working with government ITIs to mentor faculty, strengthen institutions, and improve student learning outcomes.","points":[],"links":[]},{"label":"Skill Development","image":47,"title":"Skill Development & Employability Programs","text":"Support specialized training, industry immersion, placement readiness initiatives, and soft skills programs that prepare students for successful careers.","points":[],"links":[]},{"label":"Hub & Spoke Model","image":92,"title":"Adopt-an-ITI \/ Hub & Spoke Model","text":"Partner with one or more ITIs to strengthen infrastructure, faculty capability, and student outcomes through NAMTECH\u2019s Hub & Spoke model.","points":[],"links":[]},{"label":"CSR & Impact","image":59,"title":"Corporate CSR Projects & Impact Funding","text":"Collaborate on customized CSR initiatives with measurable outcomes, transparent reporting, and long-term community impact.","points":[],"links":[]}]}', '2026-11-18 06:43:48', '2026-11-18 06:43:48', 'page', 29),
(231, 'feature_list', NULL, NULL, 1, 8, '{"eyebrow":null,"heading":"Why Partner with NAMTECH?","body":null,"tabs":[{"label":null,"items":[{"icon":"people","text":"Industry-ready Talent Pipeline"},{"icon":"handshake","text":"Employee Engagement"},{"icon":"trend","text":"High-impact Social Outcomes"},{"icon":"sparkle","text":"Brand Visibility & Recognition"},{"icon":"document","text":"CSR & ESG Reporting"}]}]}', '2026-11-18 06:43:48', '2026-11-18 06:43:48', 'page', 29),
(232, 'contact_band', NULL, NULL, 1, 9, '{"heading":"Connect with our Team","body":null,"cta_label":"Contact us","cta_url":"\/contact","contacts_label":"For More Information","contacts":[{"name":"Dr. Ravi Shankar","role":"Associate Director","email":"dvravi.shankar@namtech.ac"},{"name":"Vibha Desai","role":"Associate Director","email":"vibha.desai@namtech.ac"}]}', '2026-11-18 06:43:48', '2026-11-18 06:43:48', 'page', 29),
(233, 'page_hero', NULL, NULL, 1, 0, '{"eyebrow":"School of Technical Education","title":"International Professional Technologist Program (iPTP)","body":"An intensive 1-year immersion program bridging technical diplomas and high-demand Industry 4.0 shop-floor careers, co-designed with ITE Education Services (ITEES), Singapore.","image":87,"cta_label":"Apply for iPTP","cta_url":"\/admissions#enquire","secondary_label":null,"secondary_url":null,"statistics_group":null,"layout":null,"meta":[]}', '2026-11-18 06:43:48', '2026-11-18 06:43:48', 'page', 30),
(234, 'stat_cards', NULL, NULL, 1, 1, '{"eyebrow":"Outcomes","heading":"Why Choose iPTP?","body":null,"tone":"lavender","items":[{"icon":"check","value":"100%","label":"Placement Track Record","text":null},{"icon":"people","value":"500+","label":"Certified Technologists","text":null},{"icon":"globe","value":"ITEES","label":"Singapore Co-Certification","text":null},{"icon":"rupee","value":"2.5x","label":"Average Salary Uplift","text":null}]}', '2026-11-18 06:43:48', '2026-11-18 06:43:48', 'page', 30),
(235, 'intro', NULL, NULL, 1, 2, '{"eyebrow":null,"heading":"Program Overview","body":"<p>The International Professional Technologist Program (iPTP) transforms ITI and polytechnic diploma holders into high-productivity shop-floor engineers. Through 1,200+ hours of hands-on training on industrial-grade CNC machines, mechatronics stations, and collaborative robotics cells, graduates enter the workforce Day-Zero Ready.<\/p>","cta_label":null,"cta_url":null,"icon":"cap","tone":null}', '2026-11-18 06:43:48', '2026-11-18 06:43:48', 'page', 30),
(236, 'timeline', NULL, NULL, 1, 3, '{"eyebrow":"Curriculum Pathway","heading":"Program Structure","body":"Four progressive terms of rigorous technical training and industry immersion.","items":[{"year":"Term 1","title":"Foundations of Advanced Manufacturing","text":"Core mechanical, electrical, and pneumatic systems, safety standards, and engineering precision.","image":null},{"year":"Term 2","title":"Automation, CNC & PLC Systems","text":"Programming and operation of modern industrial automation rigs, PLC ladders, and CNC machining centers.","image":null},{"year":"Term 3","title":"Robotics & Industry 4.0 Integration","text":"Cobot deployment, sensor integration, IoT telemetry, and digital maintenance practices.","image":null},{"year":"Term 4","title":"Paid Industry Internship & Capstone","text":"Full-time immersion inside top partner manufacturing facilities with guaranteed placement transition.","image":null}]}', '2026-11-18 06:43:48', '2026-11-18 06:43:48', 'page', 30),
(237, 'eligibility', NULL, NULL, 1, 4, '{"eyebrow":"Admission","heading":"Eligibility & Selection","body":null,"criteria":[{"text":"Diploma in Mechanical, Electrical, Mechatronics, or Automobile Engineering, or ITI certificate."},{"text":"Minimum 55% marks in qualifying technical examination."},{"text":"Candidate must pass NAMTECH Technical Aptitude & Practical Hands-on Assessment."}],"list_heading":null,"items":[]}', '2026-11-18 06:43:48', '2026-11-18 06:43:48', 'page', 30),
(238, 'faq', NULL, NULL, 1, 5, '{"heading":"Frequently Asked Questions","body":null,"items":[{"question":"Who is eligible for the iPTP program?","answer":"<p>Candidates holding a diploma in engineering or ITI certificate in relevant mechanical, electrical, or automation disciplines are eligible.<\/p>"},{"question":"Is placement guaranteed after completing iPTP?","answer":"<p>NAMTECH provides comprehensive placement support, with a 100% placement track record across our previous cohorts in leading manufacturing plants.<\/p>"},{"question":"What certificate do graduates receive?","answer":"<p>Graduates receive a joint certification from NAMTECH and ITE Education Services (ITEES), Singapore.<\/p>"}],"layout":"centered"}', '2026-11-18 06:43:48', '2026-11-18 06:43:48', 'page', 30),
(239, 'cta_band', NULL, NULL, 1, 6, '{"heading":"Have Questions? Get in touch with us","body":"We partner with the best of industry, academia, and technology to co-create curriculum and align training with workforce needs. Partner with us to shape a skilled workforce for India\u2019s future.","cta_label":"Contact us","cta_url":"\/contact","tone":null}', '2026-11-18 06:43:48', '2026-11-18 06:43:48', 'page', 30),
