(248, 'page_hero', NULL, NULL, 1, 0, '{"eyebrow":"Support the Cause","title":"Creating Social Impact Together","body":"At NAMTECH, social impact is embedded in how we design education, engage with industry, and prepare the next generation of skilled professionals. We invite corporates, foundations, and CSR partners to support initiatives that deliver measurable outcomes in education, employability, gender equity, and workforce readiness.","image":59,"cta_label":"Partner With Us","cta_url":"\/contact","secondary_label":null,"secondary_url":null,"statistics_group":null,"layout":null,"meta":[]}', '2026-11-18 06:43:48', '2026-11-18 06:43:48', 'page', 33),
(249, 'card_grid', NULL, NULL, 1, 1, '{"eyebrow":"Key Initiative","heading":"Women in Manufacturing (WiM) Initiative","body":null,"columns":"4","tone":"lavender","cards":[{"icon":"graduation","title":"Advanced MET Education","body":"Enable women from across India to pursue advanced manufacturing & technology education through dedicated scholarships.","link_url":null},{"icon":"trend","title":"High-Growth Tech Roles","body":"Increase female participation in high-growth robotics, automation, and semiconductor engineering careers.","link_url":null},{"icon":"people","title":"Diverse Talent Pipeline","body":"Build an inclusive, future-ready manufacturing workforce that reflects modern India.","link_url":null},{"icon":"award","title":"Long-Term Independence","body":"Support long-term employability, leadership development, and economic independence for female technologists.","link_url":null}],"style":"joined","cta_label":null,"cta_url":null}', '2026-11-18 06:43:48', '2026-11-18 06:43:48', 'page', 33),
(250, 'card_grid', NULL, NULL, 1, 2, '{"eyebrow":"How You Can Support","heading":"CSR & Impact Focus Areas","body":null,"columns":"3","tone":"white","cards":[{"icon":"graduation","title":"Scholarships & Financial Aid","body":"Fund merit-cum-means scholarships and living stipends for talented students from underserved communities.","link_url":null},{"icon":"certificate","title":"Training & Certification Delivery","body":"Sponsor cohorts through NAMTECH\u2019s Phygital Training Program and advanced Industry 4.0 certifications.","link_url":null},{"icon":"people","title":"Faculty & Curriculum Development","body":"Empower vocational trainers and government ITI faculty with modern pedagogical tools and industry immersion.","link_url":null},{"icon":"truck","title":"Mobility Outreach & Lab on Wheels","body":"Support mobile training campuses bringing specialized robotics and CNC machinery directly to rural ITIs.","link_url":null},{"icon":"briefcase","title":"Placement & Career Facilitation","body":"Bridge the last-mile gap from technical training to high-productivity shop-floor employment.","link_url":null},{"icon":"heart","title":"Trusted Giving Channels","body":"Partner with transparent governance, quantifiable social metrics, and comprehensive CSR compliance reporting.","link_url":null}],"style":"outlined","cta_label":null,"cta_url":null}', '2026-11-18 06:43:48', '2026-11-18 06:43:48', 'page', 33);
