(259, 'page_hero', NULL, NULL, 1, 0, '{"eyebrow":"Life @ NAMTECH","title":"A day in the life of a NAMTECH Student","body":null,"image":55,"cta_label":null,"cta_url":null,"secondary_label":null,"secondary_url":null,"statistics_group":null,"layout":null,"meta":[]}', '2026-11-18 06:43:48', '2026-11-18 06:43:48', 'page', 35),
(260, 'tabs', NULL, NULL, 1, 1, '{"eyebrow":null,"heading":"What You\u2019ll Find On NAMTECH Campus","body":null,"tabs":[{"label":"Campus","title":"Campus","body":"<p>NAMTECH\u2019s modern campus at GIFT City, Gandhinagar is designed to inspire innovation and collaboration. Equipped with cutting-edge laboratories, open collaborative spaces, and modern recreational zones, the campus provides an energizing atmosphere where academic rigor meets real-world industry practice.<\/p>","image":91},{"label":"Housing","title":"Housing","body":"<p>Comfortable and secure on-campus and partnered student housing facilities provide a home away from home. Equipped with high-speed Wi-Fi, study lounges, dining options, and 24\/7 security, our residences ensure learners can focus on their studies and build lifelong friendships.<\/p>","image":49},{"label":"Health and Services","title":"Health and Services","body":"<p>Comprehensive wellness support is available to all students, including on-campus medical consultation, dedicated counseling and mental health services, fitness centers, and emergency response partnerships with premier local hospitals.<\/p>","image":86},{"label":"Transport and Accessibility","title":"Transport and Accessibility","body":"<p>Strategically situated in Gandhinagar, the campus is easily accessible via dedicated shuttle services connecting student housing, major transit hubs, Ahmedabad Airport, and local railway stations. Our campus facilities are fully barrier-free and accessible.<\/p>","image":6},{"label":"Library","title":"Library","body":"<p>Our hybrid digital and physical resource center houses thousands of technical journals, research publications, industrial standards, and access to leading engineering databases like IEEE Xplore, ScienceDirect, and digital manufacturing repositories.<\/p>","image":102}],"layout":"standard","tone":null}', '2026-11-18 06:43:48', '2026-11-18 06:43:48', 'page', 35),
(261, 'image_mosaic', NULL, NULL, 1, 2, '{"eyebrow":null,"heading":"Life @ NAMTECH","body":null,"images":[{"image":55},{"image":49},{"image":107},{"image":108}],"quote":null,"quote_name":null,"quote_role":null}', '2026-11-18 06:43:48', '2026-11-18 06:43:48', 'page', 35),
(262, 'faq', NULL, NULL, 1, 3, '{"heading":"Frequently Asked Questions","body":null,"items":[{"question":"What clubs, events, and extracurricular activities can students participate in?","answer":"<p>Students can join diverse student-led clubs ranging from Robotics and Coding to Sports, Cultural, and Sustainability initiatives. Regular hackathons, industry guest lectures, and cultural fests keep campus life lively and enriching.<\/p>"},{"question":"What makes the campus experience at NAMTECH unique?","answer":"<p>At NAMTECH, learning extends far beyond traditional classrooms into living labs, smart factory setups, and collaborative MakerSpaces where students work on real-world industry challenges alongside faculty and corporate mentors.<\/p>"},{"question":"How does NAMTECH support student wellbeing and personal growth?","answer":"<p>We take a holistic approach to student development through dedicated wellness counselors, sports facilities, peer mentorship programs, and structured workshops on communication, leadership, and emotional intelligence.<\/p>"},{"question":"What support systems are available for students?","answer":"<p>Learners have access to academic advising, career coaching, resume workshops, mock interviews with hiring partners, 24\/7 health assistance, and faculty office hours for personalized academic guidance.<\/p>"},{"question":"How does NAMTECH foster a vibrant campus community?","answer":"<p>With learners joining from across India and diverse backgrounds, NAMTECH fosters an inclusive, collaborative community through cross-disciplinary hackathons, cultural festivals, sports tournaments, and community engagement projects.<\/p>"}],"layout":"centered"}', '2026-11-18 06:43:48', '2026-11-18 06:43:48', 'page', 35),
(263, 'cta_band', NULL, NULL, 1, 4, '{"heading":"Experience NAMTECH Campus","body":null,"cta_label":"Take a Virtual 360\u00b0 Tour","cta_url":"\/campus\/virtual-tour","tone":null}', '2026-11-18 06:43:48', '2026-11-18 06:43:48', 'page', 35),
