(284, 'card_grid', NULL, NULL, 1, 1, '{"eyebrow":null,"heading":"Why Build Your Career @ NAMTECH","body":null,"columns":"3","tone":"white","cards":[{"icon":"factory","title":"Learning by building","body":"Learning happens by building. At NAMTECH, classrooms don\u2019t have desks but machines used in the industry.","link_url":null},{"icon":"globe","title":"Global collaboration","body":"Our curriculum is co-designed and co-delivered with academicians from global universities.","link_url":null},{"icon":"people","title":"People-First Culture","body":"We foster an inclusive, merit-driven environment where educators, engineers, and researchers innovate together to transform manufacturing.","link_url":null}],"style":"joined","cta_label":null,"cta_url":null}', '2026-11-18 06:43:49', '2026-11-18 06:43:49', 'page', 42),
