(293, 'card_grid', NULL, NULL, 1, 8, '{"heading":"NAMTECH\u2019S Unique Teaching Style","body":null,"columns":"3","tone":"white","style":"joined","cards":[{"icon":"people","title":"Interactive Lectures","body":"Learn by engaging with faculty, peers, and live challenges that mirror real-world decision-making.","link_url":null},{"icon":"robot","title":"Hands-on Labs","body":"Learning happens by building. At NAMTECH, classrooms don\u2019t have desks but machines used in the industry.","link_url":null},{"icon":"globe","title":"Global immersion","body":"Our curriculum is co-designed and co-delivered with academicians from global universities.","link_url":null}]}', '2026-11-18 06:43:51', '2026-11-18 06:43:51', 'page', 12),
(294, 'faq', NULL, NULL, 0, 9, '{"heading":"Frequently Asked Questions","body":"Find answers to common questions about the Program, admissions, and student life.","layout":"centered","items":[{"question":"What is the application process for programmes?","answer":null},{"question":"Are the programmes available in online or on-campus mode?","answer":null},{"question":"What are the tuition fees and payment options?","answer":null},{"question":"Who can I contact for admission-related queries?","answer":null},{"question":"Do the programs offer certificates, placements, or career support?","answer":null}]}', '2026-11-18 06:43:51', '2026-11-18 06:43:51', 'page', 12),
