INSERT INTO `events` VALUES
(1, 'conference', 4, NULL, 'Sustainable Manufacturing Summit 2026', 'sustainable-manufacturing-summit-2026', 'Masterclass by Prof. Daniel Philip, MIT', 'Experience learning with real industry equipment and state-of-the-art infrastructure designed for the future of manufacturing.', '<p>Join global leaders, faculty, and industry pioneers for an intensive masterclass exploring the future of sustainable manufacturing, decarbonization technologies, and circular economy practices. Experience hands-on sessions in state-of-the-art labs and network with leading academicians from MIT and TUM Asia.</p>', '[{"text":"Understand the core principles of Industry 5.0 and sustainable factory design."},{"text":"Hands-on exposure to decarbonization frameworks, digital twins, and resource efficiency tools."},{"text":"Direct networking with leaders from MIT, TUM Asia, and global manufacturing giants."}]', '{"name":"Prof. Daniel Philip","role":"Dean of Research, MIT","photo":38,"quote":"Sustainability in manufacturing is no longer an optional initiative\u2014it is the engineering discipline that will define industrial competitiveness for the next century.","bio":"<p>Prof. Daniel Philip is the Dean of Research at MIT, specializing in advanced manufacturing systems, precision engineering, and sustainable industrial ecosystems. He has authored over 120 peer-reviewed papers and advises governments and Fortune 500 manufacturers globally.<\/p>"}', '2027-04-15 09:00:00', '2027-04-15 17:00:00', 'NAMTECH Auditorium 3', '/contact', 75, 'published', NULL, '2026-11-18 06:42:42', NULL, NULL, NULL, '2026-11-18 06:43:42', '2026-11-18 06:43:42', NULL, NULL, NULL, NULL, 0, NULL);
INSERT INTO `jobs_openings` VALUES
(1, 'academic', 'School of Manufacturing Technologies', 'Assistant Professor - Mechanical Engineering', 'assistant-professor-mechanical-engineering', 'Join our faculty and leadership team to shape the future of manufacturing education in India.', '<p>We are seeking high-caliber professionals to lead curriculum delivery, student mentorship, and applied research in manufacturing technology, robotics, and industrial leadership. Candidates should have a proven track record of academic or industrial excellence and a passion for hands-on, experiential learning.</p><h3>Key Responsibilities</h3><ul><li>Design and deliver state-of-the-art experiential coursework and lab modules.</li><li>Engage in industry-collaborative research and student capstone projects.</li><li>Mentor students for career advancement and global industry placement.</li></ul>', NULL, 'On Campus (Gujarat Campus)', 0, 'published', NULL, '2026-11-18 06:42:42', NULL, NULL, NULL, '2026-11-18 06:43:42', '2026-11-18 06:43:42', NULL, NULL, NULL, NULL, 0),
(2, 'executive', 'NAMTECH', 'Associate / Assistant Director - Marketing and Admissions', 'associate-assistant-director-marketing-and-admissions', 'Join our faculty and leadership team to shape the future of manufacturing education in India.', '<p>We are seeking high-caliber professionals to lead curriculum delivery, student mentorship, and applied research in manufacturing technology, robotics, and industrial leadership. Candidates should have a proven track record of academic or industrial excellence and a passion for hands-on, experiential learning.</p><h3>Key Responsibilities</h3><ul><li>Design and deliver state-of-the-art experiential coursework and lab modules.</li><li>Engage in industry-collaborative research and student capstone projects.</li><li>Mentor students for career advancement and global industry placement.</li></ul>', NULL, 'Remote', 1, 'published', NULL, '2026-11-18 06:42:42', NULL, NULL, NULL, '2026-11-18 06:43:42', '2026-11-18 06:43:42', NULL, NULL, NULL, NULL, 0),
(3, 'executive', 'NAMTECH', 'MEPF Manager - Mechanical', 'mepf-manager-mechanical', 'Join our faculty and leadership team to shape the future of manufacturing education in India.', '<p>We are seeking high-caliber professionals to lead curriculum delivery, student mentorship, and applied research in manufacturing technology, robotics, and industrial leadership. Candidates should have a proven track record of academic or industrial excellence and a passion for hands-on, experiential learning.</p><h3>Key Responsibilities</h3><ul><li>Design and deliver state-of-the-art experiential coursework and lab modules.</li><li>Engage in industry-collaborative research and student capstone projects.</li><li>Mentor students for career advancement and global industry placement.</li></ul>', NULL, 'On Campus (Gujarat Campus)', 2, 'published', NULL, '2026-11-18 06:42:42', NULL, NULL, NULL, '2026-11-18 06:43:42', '2026-11-18 06:43:42', NULL, NULL, NULL, NULL, 0);
INSERT INTO `posts` VALUES
(1, 'news', 1, 1, 'AM/NS India Leadership Visits NAMTECH', 'am-ns-india-leadership-visits-namtech', 'Senior executive leadership from ArcelorMittal Nippon Steel India visited NAMTECH’s living laboratories, reviewing student capstones in automated defect detection and advanced robotics cells.', '<p>A high-level executive delegation from ArcelorMittal Nippon Steel India (AM/NS India) toured NAMTECH’s advanced manufacturing campus to evaluate student-led innovations and review ongoing co-created curriculum initiatives.</p><p>The leadership team interacted with undergraduate and postgraduate cohorts working on live industrial capstone challenges, including real-time machine vision inspection systems, robotic welding cells, and industrial IoT monitoring rigs.</p><p>AM/NS India reiterated its long-term commitment to nurturing world-class technical talent in India and expanding industry residency opportunities for NAMTECH graduates across its national manufacturing assets.</p>', 16, 1, 1, 'published', NULL, '2026-11-16 06:43:42', NULL, NULL, NULL, '2026-11-18 06:43:42', '2026-11-18 06:43:42', NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL),
(2, 'news', 1, 1, 'Dr. Bobby Mitra, CIO & President of Tata Electronics, Engages with NAMTECH', 'dr-bobby-mitra-cio-and-president-of-tata-electronics-engages-with-namtech', 'Dr. Bobby Mitra engaged with faculty and students on semiconductor ecosystem scaling, packaging innovations, and India’s growing semiconductor workforce requirements.', '<p>Dr. Bobby Mitra, CIO & President of Tata Electronics, delivered a distinguished keynote address to the NAMTECH community, highlighting the transformative potential of India’s semiconductor mission and precision electronics manufacturing.</p><p>During the interactive session, Dr. Mitra emphasized the urgent need for skilled technologists proficient in cleanroom operations, advanced lithography, chip packaging, and automated test methodologies.</p><p>Tata Electronics and NAMTECH leadership explored collaborative avenues for specialized talent incubation, curriculum benchmarking, and student internships aligned with next-generation semiconductor fabrication lines.</p>', 17, 1, 0, 'published', NULL, '2026-11-15 06:43:42', NULL, NULL, NULL, '2026-11-18 06:43:42', '2026-11-18 06:43:42', NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL),
(3, 'news', 3, 1, 'NAMTECH Strengthens Automotive Engineering Capabilities', 'namtech-strengthens-automotive-engineering-capabilities', 'NAMTECH expanded its Center of Excellence in Automotive Engineering with specialized testbeds for electric vehicle powertrains and autonomous driving simulation.', '<p>NAMTECH announced a major expansion of its Center of Excellence in Automotive Engineering, integrating state-of-the-art battery testbenches, electric motor dynos, and hardware-in-the-loop (HIL) simulation stations.</p><p>Developed in close consultation with leading automotive OEMs, the facility enables students and industry researchers to design, calibrate, and validate electric vehicle powertrains, battery management systems (BMS), and ADAS safety controllers.</p><p>This initiative directly supports India’s accelerating transition to sustainable e-mobility and provides engineering graduates with Day-Zero readiness for global automotive careers.</p>', 18, 1, 0, 'published', NULL, '2026-11-14 06:43:42', NULL, NULL, NULL, '2026-11-18 06:43:42', '2026-11-18 06:43:42', NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL),
(4, 'blog', 5, 1, 'From Industry 4.0 to 5.0: India’s Stride Towards Human–Tech Synergy', 'from-industry-40-to-50-indias-stride-towards-human-tech-synergy', 'An in-depth perspective on the technological and human convergence reshaping modern factories across India and global supply chains.', '<h2>Understanding Industry 4.0</h2><p>Industry 4.0 represents the ongoing digital transformation of traditional manufacturing and industrial practices. By integrating large-scale cyber-physical systems, IoT sensors, cloud computing, and real-time machine telemetry, modern production lines achieve unprecedented levels of automation, predictive maintenance, and operational visibility.</p><h2>India’s Industry 4.0 Journey</h2><p>India’s manufacturing landscape is witnessing rapid acceleration under national initiatives like Make in India and Viksit Bharat 2047. Leading enterprises are upgrading legacy infrastructure with intelligent edge devices, AI-driven quality inspection, and automated guided vehicles (AGVs) to compete effectively on the global stage.</p><h2>The Requirement of Industry 5.0</h2><p>While Industry 4.0 focused intensely on automated efficiency and connectivity, Industry 5.0 re-centers the human element. It pairs human creativity, problem-solving, and cognitive nuance with the repetitive precision and physical strength of collaborative robots (cobots) to deliver bespoke, sustainable products.</p><h2>Unlocking Limitless Potential</h2><p>Realizing the full promise of advanced manufacturing demands a new breed of engineering professionals who move comfortably between mechanical shop floors and advanced digital systems. Immersive educational models that emphasize hands-on experimentation are vital to closing this capability divide.</p><h2>Manufacturing as India’s Global Game-Changer</h2><p>Sustainable, digitally empowered manufacturing is set to be the primary engine of India’s economic growth in the 21st century. By cultivating skilled talent equipped for Industry 5.0, India can pioneer resilient industrial ecosystems that balance high productivity with environmental stewardship.</p>', 76, 1, 1, 'published', NULL, '2026-11-13 06:43:42', NULL, NULL, NULL, '2026-11-18 06:43:42', '2026-11-18 06:43:42', NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL),
(5, 'story', 6, 1, 'iPTP Graduate → Smart Manufacturing Engineer, Germany', 'iptp-graduate-to-smart-manufacturing-engineer-germany', 'Aruna Kumari, an iPTP student from a Tier-3 town, joined NAMTECH without experience. She became a manufacturing engineer at a global automotive supplier in Germany, focusing on production optimization.', '<p>Coming from a humble background in a Tier-3 town, Aruna Kumari joined NAMTECH’s International Professional Technologist Program with an aspiration to master industrial automation. Through intensive hands-on training on Siemens PLC systems, ABB robotics cells, and digital simulation tools, she developed deep technical fluency.</p><p>Following an outstanding industry residency, Aruna was recruited by a premier tier-1 German automotive manufacturing enterprise, where she now oversees automated assembly line optimization and predictive maintenance architectures.</p><p>“NAMTECH didn’t just teach me theory—it gave me real machines, industrial mentors, and the confidence to operate at global standards,” says Aruna.</p>', 59, 1, 1, 'published', NULL, '2026-11-12 06:43:42', NULL, NULL, NULL, '2026-11-18 06:43:42', '2026-11-18 06:43:42', NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL),
(6, 'story', 6, 1, 'NAMTECH Graduate Experiences Nearly 90% Increase in Salary', 'namtech-graduate-experiences-nearly-90-increase-in-salary', 'Rohan Patel transitioned from entry-level plant maintenance to a high-growth Industrial AI Lead role with an 88% compensation increase post-graduation.', '<p>After working for two years in conventional mechanical maintenance, Rohan Patel sought to future-proof his career by enrolling in NAMTECH’s Master in Smart Manufacturing Technology & Management.</p><p>Equipped with specialized capabilities in cyber-physical systems, digital twin simulation, and machine vision analytics, Rohan received multiple competitive job offers during campus placements, ultimately accepting an Industrial AI Lead position at ₹18 LPA—an 88% leap over his prior CTC.</p><p>“The experiential labs at NAMTECH bridge the exact gap between traditional engineering and modern Industry 4.0 factories,” Rohan remarked.</p>', 77, 1, 0, 'published', NULL, '2026-11-11 06:43:42', NULL, NULL, NULL, '2026-11-18 06:43:42', '2026-11-18 06:43:42', NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL),
(7, 'story', 10, 1, 'NAMTECH Students Revolutionize Prosthetics Design using 3D Printing', 'namtech-students-revolutionize-prosthetics-design-using-3d-printing', 'A multidisciplinary student team deployed advanced additive manufacturing technologies to produce low-cost, patient-customized prosthetic limbs.', '<p>A student research team from the School of Manufacturing Technologies and School of Robotics successfully engineered a patient-customized, 3D-printed bionic prosthetic hand capable of multi-grip adaptability.</p><p>Leveraging NAMTECH’s Additive Manufacturing & Precision Engineering Lab, the team utilized SLA resin printing and biocompatible carbon-reinforced polymers, reducing fabrication costs by 80% compared to conventional prosthetics while maintaining exceptional structural durability.</p><p>The project received top recognition at the National Smart Manufacturing Hackathon and is currently undergoing clinical trials with partner healthcare institutions.</p>', 60, 1, 0, 'published', NULL, '2026-11-10 06:43:42', NULL, NULL, NULL, '2026-11-18 06:43:42', '2026-11-18 06:43:42', NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL);
